package com.mystix;

import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class GoalImageCacheTest {
	@Test
	public void smallImagesAreLeftAlone() {
		BufferedImage small = new BufferedImage(20, 16, BufferedImage.TYPE_INT_ARGB);
		assertSame(small, GoalImageCache.fit(small));
	}

	@Test
	public void largeImagesFitTheIconSquareKeepingAspect() {
		BufferedImage tall = new BufferedImage(200, 400, BufferedImage.TYPE_INT_ARGB);
		BufferedImage fitted = GoalImageCache.fit(tall);
		assertEquals(GoalImageCache.ICON_SIZE, fitted.getHeight());
		assertEquals(16, fitted.getWidth());

		BufferedImage wide = new BufferedImage(640, 64, BufferedImage.TYPE_INT_ARGB);
		BufferedImage fittedWide = GoalImageCache.fit(wide);
		assertEquals(GoalImageCache.ICON_SIZE, fittedWide.getWidth());
		assertTrue(fittedWide.getHeight() <= GoalImageCache.ICON_SIZE);
	}

	@Test
	public void onlyWikiImagesAreFetched() {
		assertTrue(GoalImageCache.isAllowed("https://oldschool.runescape.wiki/images/Zulrah.png"));
		assertTrue(GoalImageCache.isAllowed("https://oldschool.runescape.wiki/images/Attack_icon.png?7d0d4"));

		assertFalse(GoalImageCache.isAllowed(null));
		assertFalse(GoalImageCache.isAllowed(""));
		assertFalse(GoalImageCache.isAllowed("http://oldschool.runescape.wiki/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://example.com/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://oldschool.runescape.wiki.example.com/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://oldschool.runescape.wiki@example.com/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://oldschool.runescape.wiki:8443/images/Zulrah.png"));
		assertFalse(GoalImageCache.isAllowed("https://oldschool.runescape.wiki/w/Zulrah"));
	}
}

package com.mystix;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Before;
import org.junit.Test;

/**
 * Tests for QuestMonitor config toggle behavior.
 */
public class QuestMonitorTest {
	private TestMystixConfig config;

	@Before
	public void setUp() {
		config = new TestMystixConfig();
	}

	@Test
	public void testConfigSyncQuestsDefaultIsTrue() {
		assertTrue(config.syncQuests());
	}

	@Test
	public void testConfigSyncQuestsCanBeDisabled() {
		config.setSyncQuests(false);
		assertFalse(config.syncQuests());
	}

	@Test
	public void testConfigSyncQuestsCanBeReEnabled() {
		config.setSyncQuests(false);
		assertFalse(config.syncQuests());

		config.setSyncQuests(true);
		assertTrue(config.syncQuests());
	}

	@Test
	public void scrollNamesAQuestTheEnumDoesNotKnow() {
		assertEquals("A Ruff Situation",
				QuestMonitor.parseQuestCompletedScroll("You have completed A Ruff Situation!"));
		assertEquals("The Corsair Curse",
				QuestMonitor.parseQuestCompletedScroll("You have completed The Corsair Curse!"));
		assertEquals("One Small Favour",
				QuestMonitor.parseQuestCompletedScroll("'One Small Favour' completed!"));
	}

	@Test
	public void scrollRestoresQuestWordAndRfdPrefix() {
		assertEquals("Doric's Quest",
				QuestMonitor.parseQuestCompletedScroll("You have completed Doric's Quest!"));
		assertEquals("Recipe for Disaster - Mountain Dwarf",
				QuestMonitor.parseQuestCompletedScroll("You have freed the Mountain Dwarf!"));
	}

	@Test
	public void scrollIgnoresNonCompletions() {
		assertNull(QuestMonitor.parseQuestCompletedScroll(null));
		assertNull(QuestMonitor.parseQuestCompletedScroll("You have kind of completed the Cook's Assistant!"));
	}

	@Test
	public void questTableStatusMirrorsRuneLitesEnumRead() {
		// QUEST_STATUS_GET returns 2 finished, 1 not started, anything else in progress.
		assertEquals(2, QuestMonitor.statusFromScript(2));
		assertEquals(0, QuestMonitor.statusFromScript(1));
		assertEquals(1, QuestMonitor.statusFromScript(0));
		assertEquals(1, QuestMonitor.statusFromScript(3));
	}
}

package com.mystix;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.AbstractExecutorService;
import java.util.concurrent.Callable;
import java.util.concurrent.Delayed;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/**
 * Deterministic {@link ScheduledExecutorService} for tests: {@code execute} runs
 * inline, scheduled tasks are recorded with a due time and only run when
 * {@link #runDue(long)} advances the fake clock past them.
 */
public class FakeScheduledExecutorService extends AbstractExecutorService implements ScheduledExecutorService {
	public final class FakeTask implements ScheduledFuture<Object> {
		public final Runnable runnable;
		public long dueMs;
		public final long periodMs;
		public boolean cancelled;
		public int runs;

		FakeTask(Runnable runnable, long dueMs, long periodMs) {
			this.runnable = runnable;
			this.dueMs = dueMs;
			this.periodMs = periodMs;
		}

		@Override
		public long getDelay(TimeUnit unit) {
			return unit.convert(dueMs - nowMs, TimeUnit.MILLISECONDS);
		}

		@Override
		public int compareTo(Delayed o) {
			return Long.compare(getDelay(TimeUnit.MILLISECONDS), o.getDelay(TimeUnit.MILLISECONDS));
		}

		@Override
		public boolean cancel(boolean mayInterruptIfRunning) {
			cancelled = true;
			return true;
		}

		@Override
		public boolean isCancelled() {
			return cancelled;
		}

		@Override
		public boolean isDone() {
			return cancelled || (periodMs <= 0 && runs > 0);
		}

		@Override
		public Object get() {
			return null;
		}

		@Override
		public Object get(long timeout, TimeUnit unit) {
			return null;
		}
	}

	public final List<FakeTask> tasks = new ArrayList<>();
	public long nowMs;
	private boolean shutdown;

	/** Live (not cancelled, not finished) scheduled tasks. */
	public List<FakeTask> liveTasks() {
		List<FakeTask> live = new ArrayList<>();
		for (FakeTask t : tasks) {
			if (!t.isDone()) {
				live.add(t);
			}
		}
		return live;
	}

	/** Advances the clock to {@code toMs} and runs every task due by then, in order. */
	public void runDue(long toMs) {
		nowMs = toMs;
		boolean ran = true;
		while (ran) {
			ran = false;
			for (FakeTask t : new ArrayList<>(tasks)) {
				if (t.isDone() || t.dueMs > nowMs) {
					continue;
				}
				t.runs++;
				if (t.periodMs > 0) {
					t.dueMs += t.periodMs;
				}
				t.runnable.run();
				ran = true;
			}
		}
	}

	@Override
	public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit) {
		FakeTask task = new FakeTask(command, nowMs + unit.toMillis(delay), 0);
		tasks.add(task);
		return task;
	}

	@Override
	public <V> ScheduledFuture<V> schedule(Callable<V> callable, long delay, TimeUnit unit) {
		throw new UnsupportedOperationException();
	}

	@Override
	public ScheduledFuture<?> scheduleAtFixedRate(Runnable command, long initialDelay, long period, TimeUnit unit) {
		FakeTask task = new FakeTask(command, nowMs + unit.toMillis(initialDelay), unit.toMillis(period));
		tasks.add(task);
		return task;
	}

	@Override
	public ScheduledFuture<?> scheduleWithFixedDelay(Runnable command, long initialDelay, long delay, TimeUnit unit) {
		return scheduleAtFixedRate(command, initialDelay, delay, unit);
	}

	@Override
	public void execute(Runnable command) {
		command.run();
	}

	@Override
	public void shutdown() {
		shutdown = true;
	}

	@Override
	public List<Runnable> shutdownNow() {
		shutdown = true;
		return new ArrayList<>();
	}

	@Override
	public boolean isShutdown() {
		return shutdown;
	}

	@Override
	public boolean isTerminated() {
		return shutdown;
	}

	@Override
	public boolean awaitTermination(long timeout, TimeUnit unit) {
		return true;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.model.RoadmapSummary;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class RoadmapListCacheTest {
	private static final List<RoadmapSummary> ONE = Collections.singletonList(
			new Gson().fromJson("{\"collection_id\":7,\"title\":\"Maxing\",\"goal_count\":3}", RoadmapSummary.class));

	private final RoadmapListCache cache = new RoadmapListCache();

	@Test
	public void emptyUntilRecorded() {
		assertNull(cache.reusable("Zezima", 0));
	}

	@Test
	public void reusedForTheSamePlayerWhileRecent() {
		cache.record("Zezima", ONE, 1_000);
		assertEquals(ONE, cache.reusable("Zezima", 1_000 + RoadmapListCache.REUSE_MS - 1));
		assertNull(cache.reusable("Zezima", 1_000 + RoadmapListCache.REUSE_MS));
	}

	@Test
	public void neverReusedForAnotherPlayer() {
		cache.record("Zezima", ONE, 0);
		assertNull(cache.reusable("Lynx Titan", 1));
	}

	@Test
	public void invalidateForcesAFetch() {
		cache.record("Zezima", ONE, 0);
		cache.invalidate();
		assertNull(cache.reusable("Zezima", 1));
	}

	@Test
	public void anEmptyListIsReusedToo() {
		cache.record("Zezima", Collections.emptyList(), 0);
		assertEquals(Collections.emptyList(), cache.reusable("Zezima", 1));
	}
}

package com.mystix;

import static org.junit.Assert.assertEquals;

import com.mystix.model.BankSyncPayload;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Tests that ItemCollector produces canonical, order-independent item lists.
 */
public class ItemCollectorTest {

	@Test
	public void toBankItemListSortsByItemId() {
		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		quantities.put(995, 100);
		quantities.put(385, 2);
		quantities.put(4151, 1);

		List<BankSyncPayload.BankItem> items = ItemCollector.toBankItemList(quantities);

		assertEquals(385, items.get(0).getItemId());
		assertEquals(995, items.get(1).getItemId());
		assertEquals(4151, items.get(2).getItemId());
	}

	@Test
	public void toBankItemListOrderIndependentOfInsertionOrder() {
		/* Same contents inserted in different order must yield the same canonical list,
		   so a pure reorder is dedup-identical and won't trigger a redundant sync. */
		Map<Integer, Integer> insertedOneWay = new LinkedHashMap<>();
		insertedOneWay.put(995, 100);
		insertedOneWay.put(385, 2);
		insertedOneWay.put(4151, 1);

		Map<Integer, Integer> insertedAnotherWay = new LinkedHashMap<>();
		insertedAnotherWay.put(4151, 1);
		insertedAnotherWay.put(995, 100);
		insertedAnotherWay.put(385, 2);

		List<BankSyncPayload.BankItem> listA = ItemCollector.toBankItemList(insertedOneWay);
		List<BankSyncPayload.BankItem> listB = ItemCollector.toBankItemList(insertedAnotherWay);

		assertEquals(listA.size(), listB.size());
		for (int i = 0; i < listA.size(); i++) {
			assertEquals(listA.get(i).getItemId(), listB.get(i).getItemId());
			assertEquals(listA.get(i).getQuantity(), listB.get(i).getQuantity());
		}
	}
}

