package com.mystix.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Tests for BankSyncPayload JSON serialization.
 */
public class BankSyncPayloadTest {
	private final Gson gson = new Gson();

	@Test
	public void testPayloadStructure() {
		List<BankSyncPayload.BankItem> items = Arrays.asList(
				new BankSyncPayload.BankItem(4151, 1),
				new BankSyncPayload.BankItem(385, 500));
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", items);
		BankSyncPayload payload = new BankSyncPayload("TestPlayer", itemsBySource);
		String json = payload.toJson(gson);

		assertNotNull(json);
		assertTrue(json.contains("\"player_username\":\"TestPlayer\""));
		assertTrue(json.contains("\"bank\""));
		assertTrue(json.contains("\"item_id\":4151"));
		assertTrue(json.contains("\"quantity\":1"));
		assertTrue(json.contains("\"item_id\":385"));
		assertTrue(json.contains("\"quantity\":500"));
	}

	@Test
	public void testEmptyItemsMap() {
		BankSyncPayload payload = new BankSyncPayload("EmptyPlayer", Collections.emptyMap());
		String json = payload.toJson(gson);

		assertNotNull(json);
		assertTrue(json.contains("\"player_username\":\"EmptyPlayer\""));
		assertTrue(json.contains("\"items\":{}"));
	}

	@Test
	public void testEmptySourceList() {
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", Collections.emptyList());
		BankSyncPayload payload = new BankSyncPayload("EmptyBank", itemsBySource);
		String json = payload.toJson(gson);

		assertNotNull(json);
		assertTrue(json.contains("\"bank\":[]"));
	}

	@Test
	public void testGetters() {
		BankSyncPayload.BankItem item = new BankSyncPayload.BankItem(4151, 10);
		assertEquals(4151, item.getItemId());
		assertEquals(10, item.getQuantity());

		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", Collections.singletonList(item));
		BankSyncPayload payload = new BankSyncPayload("Zezima", itemsBySource);
		assertEquals("Zezima", payload.getPlayerUsername());
		assertEquals(1, payload.getItems().size());
		assertEquals(1, payload.getTotalItemCount());
	}

	@Test
	public void testMultipleSources() {
		List<BankSyncPayload.BankItem> bankItems = Arrays.asList(
				new BankSyncPayload.BankItem(4151, 1));
		List<BankSyncPayload.BankItem> vaultItems = Arrays.asList(
				new BankSyncPayload.BankItem(385, 200));
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", bankItems);
		itemsBySource.put("seed_vault", vaultItems);
		BankSyncPayload payload = new BankSyncPayload("MultiPlayer", itemsBySource);

		assertEquals(2, payload.getTotalItemCount());
		String json = payload.toJson(gson);
		assertTrue(json.contains("\"bank\""));
		assertTrue(json.contains("\"seed_vault\""));
	}

	@Test
	public void testLargeQuantityValues() {
		BankSyncPayload.BankItem item = new BankSyncPayload.BankItem(995, 2147483647);
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		itemsBySource.put("bank", Collections.singletonList(item));
		BankSyncPayload payload = new BankSyncPayload("RichPlayer", itemsBySource);
		String json = payload.toJson(gson);

		assertNotNull(json);
		assertTrue(json.contains("\"item_id\":995"));
		assertTrue(json.contains("\"quantity\":2147483647"));
	}
}

package com.mystix.model;

import com.google.gson.Gson;
import java.time.Instant;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests parsing of the roadmap API responses and the next-goal / progress
 * helpers the panel and overlay rely on.
 */
public class RoadmapModelTest {
	private static final Gson GSON = new Gson();

	@Test
	public void testParseRoadmapList() {
		String json = "{\"player\":\"Zezima\",\"runelite_connected\":true,"
				+ "\"roadmaps\":[{\"collection_id\":1,\"title\":\"Maxing\",\"goal_count\":3},"
				+ "{\"collection_id\":2,\"title\":\"Iron grind\",\"goal_count\":0}]}";
		RoadmapList list = GSON.fromJson(json, RoadmapList.class);

		assertEquals("Zezima", list.getPlayer());
		assertTrue(list.isRuneliteConnected());
		assertEquals(2, list.getRoadmaps().size());
		assertEquals("Maxing", list.getRoadmaps().get(0).getTitle());
		assertEquals(3, list.getRoadmaps().get(0).getGoalCount());
	}

	@Test
	public void testRoadmapListEmptyRoadmapsIsNeverNull() {
		RoadmapList list = GSON.fromJson("{\"player\":\"Z\"}", RoadmapList.class);
		assertNotNull(list.getRoadmaps());
		assertTrue(list.getRoadmaps().isEmpty());
	}

	@Test
	public void testParseRoadmapDetailAndSorting() {
		String json = "{\"collection_id\":1,\"title\":\"Maxing\",\"goal_count\":2,"
				+ "\"goals\":["
				+ "{\"id\":11,\"goal_type\":\"skill_level\",\"sort_order\":2,\"name\":\"Level 99 Slayer\","
				+ "\"current\":50,\"target\":100,\"progress_percent\":63,\"is_complete\":false},"
				+ "{\"id\":10,\"goal_type\":\"quest\",\"sort_order\":1,\"name\":\"Cook's Assistant\","
				+ "\"current\":1,\"target\":1,\"progress_percent\":null,\"is_complete\":true}]}";
		Roadmap roadmap = GSON.fromJson(json, Roadmap.class);

		assertEquals(1, roadmap.getCollectionId());
		assertEquals(2, roadmap.getGoals().size());
		// Sorted by sort_order: the quest (1) before the skill (2).
		assertEquals(10, roadmap.getGoalsSorted().get(0).getId());
		assertEquals(11, roadmap.getGoalsSorted().get(1).getId());
	}

	@Test
	public void testFirstIncompleteGoalSkipsCompleted() {
		String json = "{\"collection_id\":1,\"goals\":["
				+ "{\"id\":1,\"sort_order\":1,\"name\":\"Done\",\"is_complete\":true},"
				+ "{\"id\":2,\"sort_order\":2,\"name\":\"Next up\",\"is_complete\":false},"
				+ "{\"id\":3,\"sort_order\":3,\"name\":\"Later\",\"is_complete\":false}]}";
		Roadmap roadmap = GSON.fromJson(json, Roadmap.class);

		RoadmapGoal next = roadmap.firstIncompleteGoal();
		assertNotNull(next);
		assertEquals("Next up", next.getName());
	}

	@Test
	public void testFirstIncompleteGoalNullWhenAllComplete() {
		String json = "{\"collection_id\":1,\"goals\":["
				+ "{\"id\":1,\"sort_order\":1,\"name\":\"Done\",\"is_complete\":true}]}";
		Roadmap roadmap = GSON.fromJson(json, Roadmap.class);
		assertNull(roadmap.firstIncompleteGoal());
	}

	@Test
	public void testProgressLabel() {
		RoadmapGoal measurable = GSON.fromJson(
				"{\"id\":1,\"progress_percent\":42,\"is_complete\":false}", RoadmapGoal.class);
		assertEquals("42%", measurable.progressLabel());

		RoadmapGoal binary = GSON.fromJson(
				"{\"id\":2,\"progress_percent\":null,\"is_complete\":false}", RoadmapGoal.class);
		assertEquals("", binary.progressLabel());
		assertFalse(binary.isComplete());
	}

	@Test
	public void testCompletedAtParsesAndTolerates() {
		assertEquals(Instant.parse("2026-09-07T12:34:56.123456Z"),
				GSON.fromJson("{\"id\":1,\"completed_at\":\"2026-09-07T12:34:56.123456Z\"}", RoadmapGoal.class)
						.getCompletedAt());
		assertEquals(Instant.parse("2026-09-07T12:34:56Z"),
				GSON.fromJson("{\"id\":1,\"completed_at\":\"2026-09-07T12:34:56+00:00\"}", RoadmapGoal.class)
						.getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1,\"completed_at\":null}", RoadmapGoal.class).getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1}", RoadmapGoal.class).getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1,\"completed_at\":\"\"}", RoadmapGoal.class).getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1,\"completed_at\":\"not-a-date\"}", RoadmapGoal.class).getCompletedAt());
		assertNull(GSON.fromJson("{\"id\":1,\"completed_at\":\"2026-09-07\"}", RoadmapGoal.class).getCompletedAt());
	}

	@Test
	public void testImageUrlParses() {
		assertEquals("https://oldschool.runescape.wiki/images/Tormented_Demon.png",
				GSON.fromJson("{\"id\":1,\"image_url\":\"https://oldschool.runescape.wiki/images/Tormented_Demon.png\"}",
						RoadmapGoal.class).getImageUrl());
		assertNull(GSON.fromJson("{\"id\":1,\"image_url\":null}", RoadmapGoal.class).getImageUrl());
	}

	@Test
	public void testNpcMetaParses() {
		RoadmapGoal g = GSON.fromJson("{\"id\":1,\"meta\":{\"npc_id\":384,\"npc_name\":\"Guard\"}}", RoadmapGoal.class);
		assertEquals(Integer.valueOf(384), g.getNpcId());
		assertEquals("Guard", g.getNpcName());
		assertNull(GSON.fromJson("{\"id\":1,\"meta\":{}}", RoadmapGoal.class).getNpcName());
	}
}

