package com.mystix;

import com.mystix.model.Roadmap;
import com.mystix.model.RoadmapGoal;
import java.util.ArrayList;
import java.util.List;

/** Records every outbound action {@link GoalProgressState} requests. */
class RecordingSyncHooks implements GoalProgressState.SyncHooks {
	int skillsSyncs;
	int lootFlushes;
	int bankSyncs;
	final List<Integer> reconcileDelays = new ArrayList<>();
	final List<Integer> completedGoalIds = new ArrayList<>();
	final List<Integer> completedCollectionIds = new ArrayList<>();

	@Override
	public void forceSkillsSync() {
		skillsSyncs++;
	}

	@Override
	public void flushLootDrops() {
		lootFlushes++;
	}

	@Override
	public void forceBankSync() {
		bankSyncs++;
	}

	@Override
	public void requestReconcile(int delaySeconds) {
		reconcileDelays.add(delaySeconds);
	}

	@Override
	public void goalCompleted(RoadmapGoal goal, Roadmap roadmap) {
		completedGoalIds.add(goal.getId());
		completedCollectionIds.add(roadmap == null ? -1 : roadmap.getCollectionId());
	}
}

package com.mystix;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BankDepositLedgerTest {
	private static Map<Integer, Integer> qty(int id, int q) {
		Map<Integer, Integer> m = new HashMap<>();
		m.put(id, q);
		return m;
	}

	@Test
	public void itemsRemovedInADepositContextAreBankedUntilTheBankIsRead() {
		BankDepositLedger l = new BankDepositLedger(Map::of);
		// Dropping a fish is not a deposit.
		assertFalse(l.onItemsRemoved(qty(13439, 1), 10));
		// With the deposit box interface open every removal counts.
		l.onDepositInterface(true);
		assertTrue(l.onItemsRemoved(qty(13439, 12), 21));
		assertTrue(l.onItemsRemoved(qty(13439, 3), 40));
		l.onDepositInterface(false);
		assertEquals(Integer.valueOf(15), l.contents().get(13439));
		assertFalse(l.onItemsRemoved(qty(13439, 1), 44));
		// Reading the bank proper folds them in.
		assertTrue(l.onBankRead());
		assertTrue(l.contents().isEmpty());
		assertFalse(l.onBankRead());
	}

	@Test
	public void firstDepositOfASessionBuildsOnTheServersFigure() {
		Map<Integer, Integer> server = qty(13439, 5);
		BankDepositLedger l = new BankDepositLedger(() -> server);
		l.onDepositInterface(true);
		l.onItemsRemoved(qty(13439, 2), 1);
		assertEquals(Integer.valueOf(7), l.contents().get(13439));
		// A bank read supersedes the server's figure; later deposits start from zero.
		l.onBankRead();
		l.onItemsRemoved(qty(13439, 1), 50);
		assertEquals(Integer.valueOf(1), l.contents().get(13439));
		// Next session seeds again.
		l.resetSession();
		server.put(13439, 9);
		l.onDepositInterface(true);
		l.onItemsRemoved(qty(13439, 1), 100);
		assertEquals(Integer.valueOf(10), l.contents().get(13439));
	}

	@Test
	public void aContainerEmptiedIntoADepositBoxCountsAsDeposited() {
		BankDepositLedger l = new BankDepositLedger(Map::of);
		l.onContainerEmptied(qty(13439, 28));
		assertEquals(Integer.valueOf(28), l.contents().get(13439));
		l.onBankRead();
		assertTrue(l.contents().isEmpty());
	}
}

package com.mystix;

import net.runelite.api.WorldType;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests for special game mode detection using WorldType enum.
 * Verifies that all special game mode world types are available for checking.
 * Special modes that should be excluded: SEASONAL, DEADMAN, FRESH_START_WORLD,
 * TOURNAMENT_WORLD, BETA_WORLD, NOSAVE_MODE, QUEST_SPEEDRUNNING, PVP_ARENA
 * (a PvP Arena world hands the player a temporary copy of their character).
 */
public class SpecialGameModeTest
{
	@Test
	public void testSpecialGameModeWorldTypesExist()
	{
		assertNotNull("WorldType.SEASONAL should exist", WorldType.SEASONAL);
		assertNotNull("WorldType.DEADMAN should exist", WorldType.DEADMAN);
		assertNotNull("WorldType.FRESH_START_WORLD should exist", WorldType.FRESH_START_WORLD);
		assertNotNull("WorldType.TOURNAMENT_WORLD should exist", WorldType.TOURNAMENT_WORLD);
		assertNotNull("WorldType.BETA_WORLD should exist", WorldType.BETA_WORLD);
		assertNotNull("WorldType.NOSAVE_MODE should exist", WorldType.NOSAVE_MODE);
		assertNotNull("WorldType.QUEST_SPEEDRUNNING should exist", WorldType.QUEST_SPEEDRUNNING);
		assertNotNull("WorldType.PVP_ARENA should exist", WorldType.PVP_ARENA);
	}

	@Test
	public void testNormalGameModeWorldTypesExist()
	{
		assertNotNull("WorldType.MEMBERS should exist", WorldType.MEMBERS);
		assertNotNull("WorldType.SKILL_TOTAL should exist", WorldType.SKILL_TOTAL);
		assertNotNull("WorldType.PVP should exist", WorldType.PVP);
	}

	@Test
	public void testWorldTypeEnumValues()
	{
		WorldType[] types = WorldType.values();
		assertNotNull(types);
		assertTrue("Should have multiple WorldType values", types.length >= 7);

		boolean hasAllSpecialModes = true;
		WorldType[] specialModes = {
			WorldType.SEASONAL,
			WorldType.DEADMAN,
			WorldType.FRESH_START_WORLD,
			WorldType.TOURNAMENT_WORLD,
			WorldType.BETA_WORLD,
			WorldType.NOSAVE_MODE,
			WorldType.QUEST_SPEEDRUNNING,
			WorldType.PVP_ARENA
		};

		for (WorldType specialMode : specialModes)
		{
			boolean found = false;
			for (WorldType type : types)
			{
				if (type == specialMode)
				{
					found = true;
					break;
				}
			}
			if (!found)
			{
				hasAllSpecialModes = false;
				break;
			}
		}
		assertTrue("WorldType enum should contain all special game mode types", hasAllSpecialModes);
	}
}

package com.mystix;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Before;
import org.junit.Test;

/**
 * Tests for SlayerMonitor's outcome claim table and config toggle.
 *
 * <p>The claim mirrors the backend decision table: streak advance (either
 * counter) or completion chat = completed; block-list membership = blocked;
 * a points drop with neither = skipped. Point AMOUNTS never classify, because
 * Mortimer's skip costs 100, the classic block price.
 */
public class SlayerMonitorTest {
	private TestMystixConfig config;

	@Before
	public void setUp() {
		config = new TestMystixConfig();
	}

	@Test
	public void testConfigSyncSlayerDefaultIsTrue() {
		assertTrue(config.syncSlayer());
	}

	@Test
	public void testConfigSyncSlayerCanBeDisabled() {
		config.setSyncSlayer(false);
		assertFalse(config.syncSlayer());
	}

	@Test
	public void testStreakAdvanceIsCompleted() {
		assertEquals("completed",
				SlayerMonitor.claimOutcome(39, 40, 3, 3, 470, 500, false, false, false));
	}

	@Test
	public void testWildernessStreakAdvanceIsCompleted() {
		assertEquals("completed",
				SlayerMonitor.claimOutcome(39, 39, 3, 4, 470, 500, false, false, false));
	}

	@Test
	public void testChatAloneIsCompleted() {
		assertEquals("completed",
				SlayerMonitor.claimOutcome(39, 39, 3, 3, 500, 500, true, false, false));
	}

	@Test
	public void testBlockListGainIsBlockedRegardlessOfPointCost() {
		// -120 (Mortimer block) and -100 (classic block) both classify by
		// membership, not amount.
		assertEquals("blocked",
				SlayerMonitor.claimOutcome(39, 39, 3, 3, 520, 400, false, true, false));
		assertEquals("blocked",
				SlayerMonitor.claimOutcome(39, 39, 3, 3, 500, 400, false, true, false));
	}

	@Test
	public void testMortimerHundredPointDropWithoutBlockIsSkip() {
		// The collision case: -100 is Mortimer's SKIP cost. Without block-list
		// membership it must never classify as blocked.
		assertEquals("skipped",
				SlayerMonitor.claimOutcome(39, 39, 3, 3, 500, 400, false, false, false));
	}

	@Test
	public void testClassicSkipIsSkipped() {
		assertEquals("skipped",
				SlayerMonitor.claimOutcome(39, 39, 3, 3, 500, 470, false, false, false));
	}

	@Test
	public void testStreakResetIsReset() {
		assertEquals("reset",
				SlayerMonitor.claimOutcome(39, 0, 3, 3, 500, 500, false, false, false));
	}

	@Test
	public void testNoSignalsIsUnknown() {
		assertEquals("unknown",
				SlayerMonitor.claimOutcome(39, 39, 3, 3, 500, 500, false, false, false));
	}

	@Test
	public void testMortimerPointsAwardWithFlatStreakIsCompleted() {
		// Mortimer keeps its own streak, which no varbit exposes, and its chat
		// line does not match the completion pattern. The +15 modifier award is
		// the only signal, and nothing but a completion pays.
		assertEquals("completed",
				SlayerMonitor.claimOutcome(121, 121, 0, 0, 291, 306, false, false, false));
	}

	@Test
	public void testMortimerUnpaidTaskCompletesOnCountdownToZero() {
		// A Mortimer task offered without a points modifier awards nothing, so
		// the observed countdown to 0 is all that separates it from a cancel.
		assertEquals("completed",
				SlayerMonitor.claimOutcome(121, 121, 0, 0, 306, 306, false, false, true));
	}

	@Test
	public void testCountdownToZeroNeverOutranksACharge() {
		// A cancel clears the same varp to 0: the charge has to win, or every
		// skip and block would read as a completion.
		assertEquals("skipped",
				SlayerMonitor.claimOutcome(121, 121, 0, 0, 406, 306, false, false, true));
		assertEquals("blocked",
				SlayerMonitor.claimOutcome(121, 121, 0, 0, 426, 306, false, true, true));
	}

	@Test
	public void testBlockListDecodesPackedBytes() {
		// Live-captured varp values: 424696191 packs Blue dragons (25), Cave
		// horrors (80), Spiritual creatures (89), Metal dragons (127), which
		// matched the four blocked rows in the rewards-interface scrape.
		SlayerMonitor.Snapshot s = new SlayerMonitor.Snapshot();
		s.blockList = java.util.List.of(0, 0, 4784128, 0, 424696191);
		java.util.Set<Integer> ids = s.decodedBlockIds();
		assertTrue(ids.containsAll(java.util.List.of(25, 80, 89, 127, 73)));
		assertFalse(ids.contains(0));
	}

	@Test
	public void testStreakAdvanceWinsOverBlockFlag() {
		// If both fire in one coalesced window, completion (authoritative
		// streak) outranks the block corroboration.
		assertEquals("completed",
				SlayerMonitor.claimOutcome(39, 40, 3, 3, 500, 400, false, true, false));
	}

	@Test
	public void testHasStoredTaskRegularTask() {
		assertTrue(SlayerMonitor.hasStoredTask(51, 77));
		assertFalse(SlayerMonitor.hasStoredTask(0, 77));
		assertFalse(SlayerMonitor.hasStoredTask(51, 0));
		assertFalse(SlayerMonitor.hasStoredTask(0, 0));
		// Negative amounts only render for the boss sentinel in game.
		assertFalse(SlayerMonitor.hasStoredTask(51, -1));
	}

	@Test
	public void testHasStoredTaskBossSentinel() {
		assertTrue(SlayerMonitor.hasStoredTask(98, 5));
		// The rewards script draws a name-only slot for a boss with amount -1.
		assertTrue(SlayerMonitor.hasStoredTask(98, -1));
		assertFalse(SlayerMonitor.hasStoredTask(98, 0));
	}

	@Test
	public void testStoredTaskExtraEmptyUntilCaptured() {
		assertTrue(SlayerMonitor.storedTaskExtra(null).isEmpty());
	}

	@Test
	public void testStoredTaskExtraCarriesCapture() {
		SlayerMonitor.StoredTaskCapture capture = new SlayerMonitor.StoredTaskCapture();
		capture.taskId = 98;
		capture.amount = 35;
		capture.bossTaskId = 3;
		capture.taskName = "Kalphite Queen";
		capture.capturedAt = "2026-07-28T00:00:00Z";
		java.util.Map<String, Object> extra = SlayerMonitor.storedTaskExtra(capture);
		assertEquals(98, extra.get("stored_task_id"));
		assertEquals(35, extra.get("stored_task_amount"));
		assertEquals(3, extra.get("stored_boss_task_id"));
		assertEquals("Kalphite Queen", extra.get("stored_task_name"));
		assertEquals("2026-07-28T00:00:00Z", extra.get("stored_task_captured_at"));
	}

	@Test
	public void testStoredTaskExtraOmitsUnresolvedName() {
		// A capture that confirmed the storage is EMPTY still syncs zeros, so
		// the backend can distinguish "empty" from "never captured".
		SlayerMonitor.StoredTaskCapture capture = new SlayerMonitor.StoredTaskCapture();
		capture.capturedAt = "2026-07-28T00:00:00Z";
		java.util.Map<String, Object> extra = SlayerMonitor.storedTaskExtra(capture);
		assertEquals(0, extra.get("stored_task_id"));
		assertEquals(0, extra.get("stored_task_amount"));
		assertEquals(0, extra.get("stored_boss_task_id"));
		assertFalse(extra.containsKey("stored_task_name"));
	}

	@Test
	public void testParseTaskOffersAgainstCapturedDialogRows() {
		// Verbatim rows captured from the live Slayer Task Choice dialog
		// (interface 236.3), including its underline name tags.
		java.util.List<java.util.Map<String, Object>> offers =
				SlayerMonitor.parseTaskOffers(java.util.Arrays.asList(
						"Slayer Task Choice",
						"<u=ff981f>Turoth", "Amount: 80 to 120", "+15 Slayer points",
						"<u=ff981f>Gryphons", "Amount: 80 to 120", "+20 Slayer points",
						"<col=b2b2b2>Complete 50 tasks with Mortimer to unlock a third choice."));
		assertEquals(2, offers.size());
		assertEquals("Turoth", offers.get(0).get("name"));
		assertEquals(80, offers.get(0).get("amount_min"));
		assertEquals(120, offers.get(0).get("amount_max"));
		assertEquals("+15 Slayer points", offers.get(0).get("modifier_text"));
		assertEquals(15, offers.get(0).get("modifier_value"));
		assertEquals("Slayer points", offers.get(0).get("modifier_label"));
		assertEquals("Gryphons", offers.get(1).get("name"));
		assertEquals(20, offers.get(1).get("modifier_value"));
	}

	@Test
	public void testParseTaskOffersHandlesEveryObservedModifierForm() {
		// value, isPercent, label, and the row as displayed in game.
		Object[][] cases = {
				{30, true, "Slayer XP", "+30% Slayer XP"},
				{300, true, "Superior Chance", "+300% Superior Chance"},
				{100, false, "Assigned", "+100 Assigned"},
				{2, false, "clue scrolls", "x2 clue scrolls"},
		};
		for (Object[] c : cases) {
			java.util.List<java.util.Map<String, Object>> offers =
					SlayerMonitor.parseTaskOffers(java.util.Arrays.asList(
							"<u=ff981f>Turoth", "Amount: 80 to 120", (String) c[3]));
			assertEquals(1, offers.size());
			assertEquals(c[3], offers.get(0).get("modifier_text"));
			assertEquals(c[0], offers.get(0).get("modifier_value"));
			assertEquals(c[1], offers.get(0).get("modifier_is_percent"));
			assertEquals(c[2], offers.get(0).get("modifier_label"));
		}
	}

	@Test
	public void testUnparseableModifierWordingIsStillSent() {
		java.util.List<java.util.Map<String, Object>> offers =
				SlayerMonitor.parseTaskOffers(java.util.Arrays.asList(
						"Dust devils", "Amount: 145 to 237", "Guaranteed superior spawn"));
		assertEquals(1, offers.size());
		assertEquals("Guaranteed superior spawn", offers.get(0).get("modifier_text"));
		assertFalse(offers.get(0).containsKey("modifier_value"));
	}

	@Test
	public void testParseTaskOffersSingleAmountAndNoModifier() {
		java.util.List<java.util.Map<String, Object>> offers =
				SlayerMonitor.parseTaskOffers(java.util.Arrays.asList(
						"Basilisks", "Amount: 48", ""));
		assertEquals(1, offers.size());
		assertEquals(48, offers.get(0).get("amount_min"));
		assertEquals(48, offers.get(0).get("amount_max"));
		assertFalse(offers.get(0).containsKey("modifier_text"));
	}

	@Test
	public void testNegativeModifierKeepsItsSign() {
		// Mortimer's "-20 Assigned" asks for 20 FEWER kills than the amount
		// rolled; dropping the sign would have it ask for 20 more.
		java.util.List<java.util.Map<String, Object>> offers =
				SlayerMonitor.parseTaskOffers(java.util.Arrays.asList(
						"<u=ff981f>Banshees", "Amount: 35 to 50", "-20 Assigned"));
		assertEquals(1, offers.size());
		assertEquals("-20 Assigned", offers.get(0).get("modifier_text"));
		assertEquals(-20, offers.get(0).get("modifier_value"));
		assertEquals("Assigned", offers.get(0).get("modifier_label"));
		assertFalse((Boolean) offers.get(0).get("modifier_multiplies"));
	}

	@Test
	public void testModifierIsFoundAcrossUntextedRows() {
		// The dialog's rows are only consecutive once its untexted widgets are
		// stepped over; indexing straight to the next row misses the modifier.
		java.util.List<java.util.Map<String, Object>> offers =
				SlayerMonitor.parseTaskOffers(java.util.Arrays.asList(
						"<u=ff981f>Turoth", "Amount: 80 to 120", "", "+15 Slayer points",
						"<u=ff981f>Kurask", "Amount: 40 to 60", "", "+20 Slayer points"));
		assertEquals(2, offers.size());
		assertEquals("+15 Slayer points", offers.get(0).get("modifier_text"));
		assertEquals("Kurask", offers.get(1).get("name"));
		assertEquals("+20 Slayer points", offers.get(1).get("modifier_text"));
	}

	@Test
	public void testNextOffersNameIsNotReadAsAModifier() {
		java.util.List<java.util.Map<String, Object>> offers =
				SlayerMonitor.parseTaskOffers(java.util.Arrays.asList(
						"<u=ff981f>Turoth", "Amount: 80 to 120",
						"<u=ff981f>Kurask", "Amount: 40 to 60"));
		assertEquals(2, offers.size());
		assertFalse(offers.get(0).containsKey("modifier_text"));
		assertEquals("Kurask", offers.get(1).get("name"));
	}

	@Test
	public void testReadingOrderSortsRowsDownTheDialog() {
		// Walking the static, dynamic and nested child lists in turn groups
		// the rows by list; only where they drew says which offer owns which.
		java.util.List<String> texts = SlayerMonitor.readingOrder(java.util.Arrays.asList(
				new SlayerMonitor.OfferRow("<u=ff981f>Turoth", 20, 40),
				new SlayerMonitor.OfferRow("<u=ff981f>Kurask", 20, 80),
				new SlayerMonitor.OfferRow("Amount: 80 to 120", 20, 55),
				new SlayerMonitor.OfferRow("Amount: 40 to 60", 20, 95),
				new SlayerMonitor.OfferRow("+15 Slayer points", 20, 70),
				new SlayerMonitor.OfferRow("+20 Slayer points", 20, 110)));
		java.util.List<java.util.Map<String, Object>> offers =
				SlayerMonitor.parseTaskOffers(texts);
		assertEquals(2, offers.size());
		assertEquals("Turoth", offers.get(0).get("name"));
		assertEquals(15, offers.get(0).get("modifier_value"));
		assertEquals("Kurask", offers.get(1).get("name"));
		assertEquals(20, offers.get(1).get("modifier_value"));
	}

	@Test
	public void testReadingOrderKeepsWalkOrderWhenAnyRowIsUnplaced() {
		java.util.List<String> texts = SlayerMonitor.readingOrder(java.util.Arrays.asList(
				new SlayerMonitor.OfferRow("second", 20, 80),
				new SlayerMonitor.OfferRow("first", null, null)));
		assertEquals(java.util.Arrays.asList("second", "first"), texts);
	}

	@Test
	public void testParseTaskOffersRejectsNonOfferDialogs() {
		java.util.List<String> texts = java.util.Arrays.asList(
				"Select an option", "Yes", "No", "Cancel");
		org.junit.Assert.assertTrue(SlayerMonitor.parseTaskOffers(texts).isEmpty());
	}
}

package com.mystix;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class StorageItemLedgerTest {
	private static final Map<Integer, String> NAMES = new HashMap<>();

	static {
		NAMES.put(ItemID.RAW_ANGLERFISH, "Raw anglerfish");
		NAMES.put(ItemID.RAW_SHARK, "Raw shark");
		NAMES.put(ItemID.RAW_SHRIMP, "Raw shrimps");
		NAMES.put(ItemID.MORT_SLIMEY_EEL, "Raw slimy eel");
		NAMES.put(ItemID.TBWT_RAW_KARAMBWAN, "Raw karambwan");
		NAMES.put(ItemID.OAK_LOGS, "Oak logs");
		NAMES.put(ItemID.YEW_LOGS, "Yew logs");
		NAMES.put(ItemID.UNCUT_SAPPHIRE, "Uncut sapphire");
		NAMES.put(ItemID.UNCUT_RUBY, "Uncut ruby");
		NAMES.put(ItemID.UNCUT_RED_TOPAZ, "Uncut red topaz");
		NAMES.put(ItemID.COAL, "Coal");
		NAMES.put(ItemID.UNIDENTIFIED_RANARR, "Grimy ranarr weed");
		NAMES.put(ItemID.UNIDENTIFIED_GUAM, "Grimy guam leaf");
	}

	private static StorageItemLedger ledger(StorageItemSpec spec) {
		return new StorageItemLedger(spec, id -> NAMES.getOrDefault(id, "Item " + id));
	}

	private static Map<Integer, Integer> qty(int id, int q) {
		Map<Integer, Integer> m = new HashMap<>();
		m.put(id, q);
		return m;
	}

	@Test
	public void catchesWithOpenBarrelAreCreditedPerFish() {
		StorageItemLedger l = ledger(StorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		assertTrue(l.settle(true));
		l.onGatherMessage("You catch a shark.");
		l.onGatherMessage("Rada's blessing enabled you to catch an extra fish.");
		l.settle(true);
		l.onGatherMessage("You catch some shrimps.");
		l.onGatherMessage("You catch a slimy swamp eel.");
		l.onGatherMessage("You catch a Karambwan.");
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.RAW_ANGLERFISH));
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.RAW_SHARK));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.RAW_SHRIMP));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.MORT_SLIMEY_EEL));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.TBWT_RAW_KARAMBWAN));
	}

	@Test
	public void closedBarrelOrFishLandingInInventoryIsNotCredited() {
		StorageItemLedger l = ledger(StorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		assertFalse(l.settle(false));
		assertTrue(l.contents().isEmpty());

		// Open, but the fish showed up in the inventory: the barrel is full.
		l.onGatherMessage("You catch an anglerfish!");
		l.onInventoryDiff(qty(ItemID.RAW_ANGLERFISH, 1), Map.of(), false, false);
		assertFalse(l.settle(true));
		assertTrue(l.isFull());
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void infernalHarpoonCookedFishIsNotStored() {
		StorageItemLedger l = ledger(StorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		l.onXp(Skill.COOKING, 230);
		l.settle(true);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void fillMovesInventoryFishInAndCapacityCaps() {
		StorageItemLedger l = ledger(StorageItemSpec.fishBarrel());
		l.onInventoryDiff(Map.of(), qty(ItemID.RAW_SHARK, 20), true, false);
		l.onInventoryDiff(Map.of(), qty(ItemID.RAW_ANGLERFISH, 20), true, false);
		l.settle(false);
		assertEquals(Integer.valueOf(20), l.contents().get(ItemID.RAW_SHARK));
		assertEquals(Integer.valueOf(8), l.contents().get(ItemID.RAW_ANGLERFISH));
		assertEquals(28, l.total());
		assertTrue(l.isFull());
		// Without a recent Fill click, fish leaving the inventory is a drop / use.
		l.onInventoryDiff(Map.of(), qty(ItemID.RAW_SHARK, 5), false, false);
		l.settle(false);
		assertEquals(28, l.total());
	}

	@Test
	public void emptyingIntoTheBankClearsAndCheckResyncs() {
		StorageItemLedger l = ledger(StorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		assertTrue(l.onGameMessage("You empty all of your containers into the bank."));
		assertTrue(l.settle(true));
		assertTrue(l.contents().isEmpty());

		assertTrue(l.onCheckText("The barrel contains: 5 x Raw anglerfish,<br>3 x Raw shark"));
		assertTrue(l.settle(false));
		assertEquals(Integer.valueOf(5), l.contents().get(ItemID.RAW_ANGLERFISH));
		assertEquals(Integer.valueOf(3), l.contents().get(ItemID.RAW_SHARK));
		assertTrue(l.onCheckText("The barrel is empty."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
		// Unrelated text is ignored.
		assertFalse(l.onCheckText("You have 3 x Raw shark in your bank."));
		assertFalse(l.onGameMessage("Your Ring of Recoil has shattered."));
	}

	@Test
	public void fullMessageStopsCreditingUntilEmptied() {
		StorageItemLedger l = ledger(StorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		l.onGameMessage("The barrel is full. It may be emptied at a bank.");
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		assertEquals(1, l.total());
		l.onGameMessage("Your containers are already empty.");
		l.settle(true);
		assertTrue(l.contents().isEmpty());
		assertFalse(l.isFull());
	}

	@Test
	public void logBasketCountsChoppedLogsAndPartialEmpties() {
		StorageItemLedger l = ledger(StorageItemSpec.logBasket());
		l.onGatherMessage("You get some oak logs.");
		l.onGatherMessage("Your Kandarin headgear provides you with an additional log.");
		l.settle(true);
		l.onGatherMessage("You get some yew logs.");
		l.onXp(Skill.FIREMAKING, 200); // infernal axe burnt it
		l.settle(true);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.OAK_LOGS));
		assertNull(l.contents().get(ItemID.YEW_LOGS));
		// "Empty" then one log appears in the inventory.
		l.onInventoryDiff(qty(ItemID.OAK_LOGS, 1), Map.of(), false, true);
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.OAK_LOGS));
		assertTrue(l.onGameMessage("You empty your basket into the bank."));
		l.settle(true);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void gemBagParsesMinedGemsAndTheCheckMessage() {
		StorageItemLedger l = ledger(StorageItemSpec.gemBag());
		l.onGatherMessage("You just mined a sapphire!");
		l.onGatherMessage("You just found a ruby!");
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNCUT_SAPPHIRE));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNCUT_RUBY));
		assertTrue(l.onGameMessage("Sapphires: 12 / Rubies: 3 / Red topazes: 2"));
		l.settle(false);
		assertEquals(Integer.valueOf(12), l.contents().get(ItemID.UNCUT_SAPPHIRE));
		assertEquals(Integer.valueOf(3), l.contents().get(ItemID.UNCUT_RUBY));
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNCUT_RED_TOPAZ));
		assertTrue(l.onGameMessage("You empty your gem bag into the bank."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void coalBagCountsMinedCoalAndParsesItsCheckMessage() {
		StorageItemLedger l = ledger(StorageItemSpec.coalBag());
		l.onGatherMessage("You manage to mine some coal.");
		l.onGatherMessage("Your Celestial ring allows you to mine an additional ore.");
		l.settle(true);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.COAL));
		assertTrue(l.onGameMessage("The coal bag contains 27 pieces of coal."));
		l.settle(false);
		assertEquals(Integer.valueOf(27), l.contents().get(ItemID.COAL));
		assertTrue(l.onGameMessage("The coal bag contains one piece of coal."));
		l.settle(false);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.COAL));
		assertTrue(l.onGameMessage("The coal bag is now empty."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void herbSackCreditsHarvestsByFarmingXpOnly() {
		StorageItemLedger l = ledger(StorageItemSpec.herbSack());
		// Ranarr harvest: 30.5 XP shows as 30 or 31 with nothing entering the inventory.
		l.onXp(Skill.FARMING, 31);
		l.settle(true);
		l.onXp(Skill.FARMING, 30);
		l.settle(true);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
		// An allotment harvest changes the inventory: no herb credit even when the XP happens to match.
		l.onXp(Skill.FARMING, 12);
		l.onInventoryDiff(Map.of(), Map.of(), false, false);
		l.settle(true);
		assertNull(l.contents().get(ItemID.UNIDENTIFIED_GUAM));
		// Closed sack: the herb lands in the inventory instead.
		l.onXp(Skill.FARMING, 30);
		l.settle(false);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
		// Check lists one herb per line until the tick settles.
		assertTrue(l.onGameMessage("You look in your herb sack and see:"));
		assertTrue(l.onGameMessage("7 x Grimy ranarr weed"));
		assertTrue(l.onGameMessage("2 x Grimy guam leaf"));
		l.settle(true);
		assertEquals(Integer.valueOf(7), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNIDENTIFIED_GUAM));
	}

	@Test
	public void unknownLedgerSeedsFromTheServerOnFirstSignalOnly() {
		Map<Integer, Integer> server = new HashMap<>();
		server.put(ItemID.RAW_ANGLERFISH, 2);
		StorageItemLedger l = new StorageItemLedger(StorageItemSpec.fishBarrel(),
				id -> NAMES.getOrDefault(id, "Item " + id), () -> server);
		assertFalse(l.isKnown());
		assertFalse(l.settle(true));
		assertTrue("nothing observed yet", l.contents().isEmpty());
		// First catch of the session builds on the server's 2.
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		assertTrue(l.isKnown());
		assertEquals(Integer.valueOf(3), l.contents().get(ItemID.RAW_ANGLERFISH));
		// Next session: unknown again until a signal, and re-seeded from whatever the server has then.
		l.resetSession();
		server.put(ItemID.RAW_ANGLERFISH, 10);
		assertFalse(l.isKnown());
		l.onGameMessage("The barrel is full. It may be emptied at a bank.");
		assertTrue(l.isKnown());
		assertEquals(Integer.valueOf(10), l.contents().get(ItemID.RAW_ANGLERFISH));
	}

	@Test
	public void singularisesCheckNames() {
		assertEquals("sapphire", StorageItemLedger.singular("Sapphires"));
		assertEquals("ruby", StorageItemLedger.singular("Rubies"));
		assertEquals("red topaz", StorageItemLedger.singular("Red topazes"));
		assertEquals("opal", StorageItemLedger.singular("Opal"));
	}

	@Test
	public void herbSackCountsPickupsAndPickedPatchesByName() {
		StorageItemLedger l = ledger(StorageItemSpec.herbSack());
		l.onGatherMessage("You put the Grimy ranarr weed herb into your herb sack.");
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
		// Harvest: the patch clicked names the herb, the XP confirms it.
		l.onPickTarget("<col=ffff>Herbs</col>");
		l.onPickTarget("Ranarr weed");
		l.onXp(Skill.FARMING, 31);
		l.settle(true);
		assertEquals(Integer.valueOf(2), l.contents().get(ItemID.UNIDENTIFIED_RANARR));
	}

	@Test
	public void outsideStateResyncsExactly() {
		StorageItemLedger l = ledger(StorageItemSpec.fishBarrel());
		l.onGatherMessage("You catch an anglerfish!");
		l.settle(true);
		l.resync(qty(ItemID.RAW_SHARK, 9));
		assertTrue(l.settle(false));
		assertEquals(Integer.valueOf(9), l.contents().get(ItemID.RAW_SHARK));
		assertNull(l.contents().get(ItemID.RAW_ANGLERFISH));
		assertTrue(l.isKnown());
		// Emptied to a deposit box with the item's own option.
		assertTrue(l.onGameMessage("You empty the barrel."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
	}

	@Test
	public void gemBagCountsThievingAndEmptiesForEveryVariant() {
		StorageItemLedger l = ledger(StorageItemSpec.gemBag());
		l.onGatherMessage("You steal an uncut sapphire and add it to your gem sack.");
		l.onGatherMessage("You put the stolen Uncut ruby into your gem bag.");
		l.settle(true);
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNCUT_SAPPHIRE));
		assertEquals(Integer.valueOf(1), l.contents().get(ItemID.UNCUT_RUBY));
		assertTrue(l.onGameMessage("You empty the gem sack into the bank."));
		l.settle(false);
		assertTrue(l.contents().isEmpty());
	}
}

