package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.BankSyncPayload;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ScriptID;
import net.runelite.api.GameState;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors potion storage contents and syncs them to the Mystix API.
 * Potion storage is not a regular container — doses are tracked in VarPlayers
 * and must be read via client scripts.
 */
@Slf4j
@Singleton
public class PotionStorageMonitor {
	private static final String SOURCE = "potion_storage";
	private static final int MAX_DOSES = 4;

	private final Client client;
	private final MystixConfig config;
	private final SourceSyncer syncer;

	private Set<Integer> potionStoreVarps;
	private boolean needsRebuild;
	private GameState previousGameState = GameState.UNKNOWN;

	@Inject
	public PotionStorageMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			Gson gson,
			ScheduledExecutorService executor) {
		this.client = client;
		this.config = config;
		this.syncer = new SourceSyncer(SOURCE, gson, executor,
				() -> config.syncBankMemory() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client),
				() -> SyncGuard.getPlayerUsername(client),
				apiClient::sendBankSync);
	}

	/** Item ids active owned-item goals are counting (short debounce for them); set by the plugin. */
	public void setGoalItems(Supplier<Set<Integer>> goalItems) {
		syncer.setGoalItems(goalItems);
	}

	public void stop() {
		syncer.stop();
		potionStoreVarps = null;
		needsRebuild = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (SyncGuard.isLogout(previousGameState, newState)) {
			syncer.flushPending();
		}
		previousGameState = newState;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		if (event.getGroupId() == InterfaceID.BANKMAIN) {
			needsRebuild = true;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (potionStoreVarps != null && potionStoreVarps.contains(event.getVarpId())) {
			needsRebuild = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event) {
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload()) {
			potionStoreVarps = null;
		}
	}

	/**
	 * On client tick, if a potion store varp changed, rebuild potion data and sync.
	 * We process on ClientTick (like RuneLite's PotionStorage) so the script runs
	 * on the client thread before the CS2 VM updates widgets.
	 */
	@Subscribe
	public void onClientTick(ClientTick event) {
		if (!needsRebuild) {
			return;
		}
		needsRebuild = false;

		if (!config.syncBankMemory() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}

		// Cache the varp triggers from the widget on first rebuild
		if (potionStoreVarps == null) {
			Widget w = client.getWidget(InterfaceID.Bankmain.POTIONSTORE_ITEMS);
			if (w == null) {
				return;
			}
			int[] triggers = w.getVarTransmitTrigger();
			if (triggers == null) {
				return;
			}
			potionStoreVarps = new HashSet<>();
			Arrays.stream(triggers).forEach(potionStoreVarps::add);
		}

		Map<Integer, Integer> quantities = new LinkedHashMap<>();
		for (BankSyncPayload.BankItem item : collectPotionItems()) {
			quantities.merge(item.getItemId(), item.getQuantity(), Integer::sum);
		}
		syncer.submit(quantities, false);
	}

	/**
	 * Reads all potions from potion storage using game enums and client scripts.
	 * Each potion is stored as its 4-dose item ID (or highest available dose for mixes).
	 */
	private List<BankSyncPayload.BankItem> collectPotionItems() {
		List<BankSyncPayload.BankItem> items = new ArrayList<>();

		EnumComposition potions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
		EnumComposition unfinished = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);

		for (EnumComposition enumComp : new EnumComposition[]{potions, unfinished}) {
			for (int potionEnumId : enumComp.getIntVals()) {
				EnumComposition potionEnum = client.getEnum(potionEnumId);

				client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
				int totalDoses = client.getIntStack()[0];

				if (totalDoses <= 0) {
					continue;
				}

				// Find the highest dose variant available for this potion
				int maxDose = findMaxDose(potionEnum);
				int itemId = potionEnum.getIntValue(maxDose);
				int quantity = totalDoses / maxDose;
				int remainderDoses = totalDoses % maxDose;

				if (quantity > 0) {
					items.add(new BankSyncPayload.BankItem(itemId, quantity));
				}

				// Add remainder as lower-dose item if applicable
				if (remainderDoses > 0) {
					int remainderItemId = potionEnum.getIntValue(remainderDoses);
					items.add(new BankSyncPayload.BankItem(remainderItemId, 1));
				}
			}
		}

		int vials = client.getVarpValue(VarPlayerID.POTIONSTORE_VIALS);
		if (vials > 0) {
			items.add(new BankSyncPayload.BankItem(ItemID.VIAL_EMPTY, vials));
		}

		return items;
	}

	/** Finds the highest dose key (4, 3, 2, or 1) that has a valid item ID in the enum. */
	private int findMaxDose(EnumComposition potionEnum) {
		for (int dose = MAX_DOSES; dose >= 1; dose--) {
			int itemId = potionEnum.getIntValue(dose);
			if (itemId > 0) {
				return dose;
			}
		}
		return 1;
	}
}

package com.mystix;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

/**
 * Inferred contents of one storage item (see {@link StorageItemSpec}),
 * per item id. Pure: fed chat lines, inventory diffs, XP drops and the
 * "Check" text by {@link StorageItemMonitor}, settled once per game tick.
 *
 * <p>Gather messages ("You catch an anglerfish") while the open container is
 * carried credit the item unless it landed in the inventory that tick (the
 * container was full or closed). "Fill" moves the inventory's accepted items
 * in; "Empty" moves them out; the bank's empty-containers action clears it;
 * the Check listing is an exact resync. The ledger is only ever as good as
 * these signals, so the monitor logs inferred-vs-checked totals to judge it.
 */
@Slf4j
final class StorageItemLedger {
	private static final Pattern CHECK_ENTRY = Pattern.compile("(\\d+)\\s*[x×]\\s*([A-Za-z' ]+?)\\s*(?:,|$|/)");
	private static final Pattern GEM_ENTRY = Pattern.compile("([A-Za-z ]+?):\\s*(\\d+)");
	private static final Pattern COAL_ENTRY = Pattern.compile("contains (\\d+|one) pieces? of coal");
	private static final Pattern TAGS = Pattern.compile("<[^>]+>");

	final StorageItemSpec spec;
	/** Resolves an item id to its in-game name; supplied by the monitor (client thread). */
	private final IntFunction<String> itemName;
	/** What the server last knew this container held (goal items only); applied before the first signal of a session. */
	private final Supplier<Map<Integer, Integer>> seed;

	private final Map<Integer, Integer> contents = new LinkedHashMap<>();
	private Map<String, Integer> chatNameIndex;
	private boolean full;
	private boolean changed;
	/** True once a real signal (gather, fill, empty, check) has been seen this session. */
	private boolean known;
	private boolean seeded;

	// Per-tick observations.
	private final Map<Integer, Integer> gatheredThisTick = new HashMap<>();
	private final Map<Integer, Integer> inventoryGainThisTick = new HashMap<>();
	private int consumedThisTick;
	private int lastGatheredItem = -1;
	private boolean inventoryChangedThisTick;
	private int xpGainedThisTick;
	private Map<Integer, Integer> checkListing;
	private boolean checkedEmpty;
	private String lastPickTarget;

	StorageItemLedger(StorageItemSpec spec, IntFunction<String> itemName) {
		this(spec, itemName, Map::of);
	}

	StorageItemLedger(StorageItemSpec spec, IntFunction<String> itemName, Supplier<Map<Integer, Integer>> seed) {
		this.spec = spec;
		this.itemName = itemName;
		this.seed = seed == null ? Map::of : seed;
	}

	/**
	 * Contents are unknown at login. Rather than start from zero (which would
	 * overwrite the server's figure with nothing and lose whatever was already
	 * inside), the first signal of the session builds on what the server last
	 * saw for the goal items. Cleared by {@link #resetSession()}.
	 */
	private void ensureSeeded() {
		if (seeded) {
			return;
		}
		seeded = true;
		Map<Integer, Integer> server = seed.get();
		if (server != null) {
			server.forEach((id, qty) -> {
				if (spec.acceptedIds.contains(id) && qty != null && qty > 0) {
					contents.put(id, qty);
				}
			});
		}
	}

	/** Logout: the next session seeds again. */
	void resetSession() {
		seeded = false;
		known = false;
		full = false;
	}

	/** True once this session has observed the container (before that nothing is pushed or uploaded). */
	boolean isKnown() {
		return known;
	}

	// ----------------------------------------------------------- inputs

	/** A SPAM chat line while the open container is carried. */
	void onGatherMessage(String message) {
		if (message == null) {
			return;
		}
		ensureSeeded();
		if (spec.extraGatherMessages.contains(message)) {
			if (lastGatheredItem > 0 && !gatheredThisTick.isEmpty()) {
				gatheredThisTick.merge(lastGatheredItem, 1, Integer::sum);
			}
			return;
		}
		String text = clean(message);
		for (Pattern pattern : spec.gatherPatterns) {
			Matcher m = pattern.matcher(text);
			if (!m.matches()) {
				continue;
			}
			int itemId = itemIdForChatName(m.group(1));
			if (itemId > 0) {
				gatheredThisTick.merge(itemId, 1, Integer::sum);
				lastGatheredItem = itemId;
			}
			return;
		}
	}

	/** Exact contents from an authoritative outside source (the Charges Improved plugin's state). */
	void resync(Map<Integer, Integer> exact) {
		ensureSeeded();
		Map<Integer, Integer> next = new LinkedHashMap<>();
		if (exact != null) {
			exact.forEach((id, qty) -> {
				if (spec.acceptedIds.contains(id) && qty != null && qty > 0) {
					next.put(id, qty);
				}
			});
		}
		if (!next.equals(contents)) {
			contents.clear();
			contents.putAll(next);
			changed = true;
		}
		full = false;
		known = true;
	}

	/** The target of the player's last "Pick" click (a herb patch): names the herb a Farming XP drop stores. */
	void onPickTarget(String target) {
		lastPickTarget = target == null ? null : clean(target).toLowerCase(Locale.ROOT);
	}

	/** A GAMEMESSAGE line while the container is carried. Returns true when it was about this container. */
	boolean onGameMessage(String message) {
		if (message == null) {
			return false;
		}
		ensureSeeded();
		String text = clean(message);
		if (spec.emptiedMessages.contains(text) || spec.checkEmptyMessages.contains(text)) {
			clear();
			return true;
		}
		for (String prefix : spec.emptiedPrefixes) {
			if (text.startsWith(prefix)) {
				clear();
				return true;
			}
		}
		if (spec.fullMessages.contains(text)) {
			full = true;
			known = true;
			return true;
		}
		return onCheckText(text);
	}

	/**
	 * The "Check" listing (chat lines or the message-box widget). Herb sack
	 * lists one herb per line, so lines accumulate until the tick settles.
	 * Returns true when the text was recognised.
	 */
	boolean onCheckText(String text) {
		if (text == null) {
			return false;
		}
		ensureSeeded();
		text = clean(text);
		if (spec.checkEmptyMessages.contains(text)) {
			checkedEmpty = true;
			known = true;
			return true;
		}
		Map<Integer, Integer> parsed = parseListing(text);
		if (parsed == null) {
			return false;
		}
		if (checkListing == null) {
			checkListing = new LinkedHashMap<>();
		}
		parsed.forEach((id, qty) -> checkListing.merge(id, qty, Integer::sum));
		known = true;
		return true;
	}

	/** The inventory changed: {@code added} / {@code removed} are per-item deltas of accepted items only. */
	void onInventoryDiff(Map<Integer, Integer> added, Map<Integer, Integer> removed, boolean recentFill, boolean recentEmpty) {
		ensureSeeded();
		inventoryChangedThisTick = true;
		added.forEach((id, qty) -> inventoryGainThisTick.merge(id, qty, Integer::sum));
		if (recentFill && !removed.isEmpty()) {
			removed.forEach((id, qty) -> add(id, qty));
			if (!full && spec.capacity > 0 && total() >= spec.capacity) {
				full = true;
			}
		}
		if (recentEmpty && !added.isEmpty()) {
			added.forEach((id, qty) -> add(id, -qty));
			full = false;
		}
	}

	/** An XP drop in a skill this container cares about. */
	void onXp(net.runelite.api.Skill skill, int xpGained) {
		ensureSeeded();
		if (skill == spec.consumeSkill) {
			consumedThisTick++;
		}
		if (skill == spec.xpCreditSkill) {
			xpGainedThisTick += xpGained;
		}
	}

	/**
	 * Once per game tick. {@code open} is whether an open variant was carried.
	 * Returns true when the contents changed.
	 */
	boolean settle(boolean open) {
		if (checkListing != null || checkedEmpty) {
			Map<Integer, Integer> exact = checkListing == null ? Map.of() : checkListing;
			log.debug("{} check: inferred {} vs listed {}", spec.source, contents, exact);
			contents.clear();
			exact.forEach((id, qty) -> add(id, qty));
			full = false;
			changed = true;
		} else if (open) {
			creditGathers();
			creditXp();
		}
		gatheredThisTick.clear();
		inventoryGainThisTick.clear();
		consumedThisTick = 0;
		inventoryChangedThisTick = false;
		xpGainedThisTick = 0;
		checkListing = null;
		checkedEmpty = false;
		boolean result = changed;
		changed = false;
		return result;
	}

	private void creditGathers() {
		if (gatheredThisTick.isEmpty()) {
			return;
		}
		boolean landedInInventory = inventoryGainThisTick.values().stream().anyMatch(q -> q > 0);
		if (landedInInventory) {
			// The container did not take it: it is full (or the item is not accepted).
			full = true;
			return;
		}
		if (full) {
			return;
		}
		int consumed = consumedThisTick;
		for (Map.Entry<Integer, Integer> e : gatheredThisTick.entrySet()) {
			int credit = e.getValue();
			int eaten = Math.min(consumed, credit);
			credit -= eaten;
			consumed -= eaten;
			if (credit > 0) {
				add(e.getKey(), credit);
			}
		}
	}

	private void creditXp() {
		if (spec.xpCreditSkill == null || xpGainedThisTick <= 0 || inventoryChangedThisTick || full) {
			return;
		}
		// The patch just clicked names the herb; the XP amount confirms it.
		if (lastPickTarget != null) {
			for (Map.Entry<Integer, Double> e : spec.xpPerItem.entrySet()) {
				String name = chatNameIndex().entrySet().stream()
						.filter(n -> n.getValue().equals(e.getKey())).map(Map.Entry::getKey).findFirst().orElse(null);
				if (name != null && lastPickTarget.contains(name.split(" ")[0])
						&& Math.abs(xpGainedThisTick - e.getValue()) <= 1.0) {
					add(e.getKey(), 1);
					return;
				}
			}
		}
		// Whole-number XP drops of a fractional value alternate around it.
		for (Map.Entry<Integer, Double> e : spec.xpPerItem.entrySet()) {
			if (Math.abs(xpGainedThisTick - e.getValue()) <= 1.0) {
				add(e.getKey(), 1);
				return;
			}
		}
	}

	// ------------------------------------------------------------ state

	Map<Integer, Integer> contents() {
		return new LinkedHashMap<>(contents);
	}

	int total() {
		int t = 0;
		for (int q : contents.values()) {
			t += q;
		}
		return t;
	}

	boolean isFull() {
		return full;
	}

	void clear() {
		if (!contents.isEmpty()) {
			changed = true;
		}
		contents.clear();
		full = false;
		known = true;
	}

	private void add(int itemId, int delta) {
		if (!spec.acceptedIds.contains(itemId) || delta == 0) {
			return;
		}
		int current = contents.getOrDefault(itemId, 0);
		int next = Math.max(0, current + delta);
		if (spec.perItemCapacity > 0) {
			next = Math.min(next, spec.perItemCapacity);
		}
		if (spec.capacity > 0 && delta > 0) {
			int room = spec.capacity - (total() - current);
			next = Math.min(next, Math.max(0, room));
		}
		if (next == current) {
			return;
		}
		if (next == 0) {
			contents.remove(itemId);
		} else {
			contents.put(itemId, next);
		}
		changed = true;
		known = true;
	}

	// ---------------------------------------------------------- parsing

	/** "The barrel contains: 5 x Raw anglerfish, 3 x Raw shark", "Sapphires: 4 / Rubies: 1", "The coal bag contains 27 pieces of coal." */
	Map<Integer, Integer> parseListing(String text) {
		boolean prefixed = spec.checkPrefix == null || spec.checkPrefix.isEmpty() || text.startsWith(spec.checkPrefix);
		if (!prefixed && checkListing == null) {
			return null; // not a listing, and no listing in progress for follow-up lines
		}
		if (!prefixed) {
			return parseEntries(text);
		}
		Map<Integer, Integer> out = new LinkedHashMap<>();
		Matcher coal = COAL_ENTRY.matcher(text);
		if (spec.acceptedIds.size() == 1 && coal.find()) {
			String n = coal.group(1);
			out.put(spec.acceptedIds.iterator().next(), "one".equals(n) ? 1 : Integer.parseInt(n));
			return out;
		}
		String body = spec.checkPrefix == null ? text : text.substring(spec.checkPrefix.length());
		Map<Integer, Integer> entries = parseEntries(body);
		if (entries != null) {
			out.putAll(entries);
		}
		// A listing header with the entries on following lines (herb sack) is
		// still a listing: it opens the resync that those lines fill in.
		boolean header = !spec.checkPrefix.isEmpty() && body.trim().isEmpty();
		return out.isEmpty() && !header ? null : out;
	}

	/** "5 x Raw anglerfish, 3 x Raw shark" or "Sapphires: 4 / Rubies: 1"; null when nothing parses. */
	private Map<Integer, Integer> parseEntries(String body) {
		Map<Integer, Integer> out = new LinkedHashMap<>();
		Matcher entries = CHECK_ENTRY.matcher(body);
		while (entries.find()) {
			int id = itemIdForChatName(entries.group(2));
			if (id > 0) {
				out.merge(id, Integer.parseInt(entries.group(1)), Integer::sum);
			}
		}
		if (out.isEmpty() && spec.namePrefixToStrip != null && spec.namePrefixToStrip.startsWith("uncut")) {
			Matcher gems = GEM_ENTRY.matcher(body);
			while (gems.find()) {
				int id = itemIdForChatName(singular(gems.group(1)));
				if (id > 0) {
					out.merge(id, Integer.parseInt(gems.group(2)), Integer::sum);
				}
			}
		}
		return out.isEmpty() ? null : out;
	}

	/** "Sapphires" to "sapphire", "Rubies" to "ruby", "Red topazes" to "red topaz". */
	static String singular(String plural) {
		String p = plural.trim().toLowerCase(Locale.ROOT);
		if (p.endsWith("ies")) {
			return p.substring(0, p.length() - 3) + "y";
		}
		if (p.endsWith("zes")) {
			return p.substring(0, p.length() - 2);
		}
		if (p.endsWith("s")) {
			return p.substring(0, p.length() - 1);
		}
		return p;
	}

	private int itemIdForChatName(String chatName) {
		if (chatName == null) {
			return -1;
		}
		String name = chatName.trim().toLowerCase(Locale.ROOT);
		name = spec.nameAliases.getOrDefault(name, name);
		if (spec.namePrefixToStrip != null && name.startsWith(spec.namePrefixToStrip)) {
			name = name.substring(spec.namePrefixToStrip.length());
		}
		Map<String, Integer> index = chatNameIndex();
		Integer id = index.get(name);
		return id == null ? -1 : id;
	}

	private Map<String, Integer> chatNameIndex() {
		if (chatNameIndex == null) {
			Map<String, Integer> index = new HashMap<>();
			for (int id : spec.acceptedIds) {
				String n = itemName.apply(id);
				if (n != null && !n.isEmpty() && !"null".equals(n)) {
					index.put(spec.chatName(n), id);
				}
			}
			chatNameIndex = index;
		}
		return chatNameIndex;
	}

	private static String clean(String text) {
		return TAGS.matcher(text.replace("<br>", " ")).replaceAll("").replace(' ', ' ').trim();
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.model.BankSyncPayload;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/**
 * Uploads bank-memory sources (bank, inventory and gear, vaults, cargo
 * holds, pouches, storage-item ledgers) on one shared cadence:
 *
 * <ul>
 *   <li>A source's first contents of the session go up at once.</li>
 *   <li>Later changes are held and collapsed for {@link #DEFAULT_DEBOUNCE_SECONDS},
 *       or {@link #GOAL_DEBOUNCE_SECONDS} when the change touches an item an
 *       active owned-item goal is counting, so a goal the player is working on
 *       confirms quickly while routine skilling costs one request per burst.</li>
 *   <li>Unchanged contents are never re-sent.</li>
 *   <li>{@link #flushPending()} (logout, plugin stop) and an {@code immediate}
 *       submit (a goal completed locally, a container was emptied, the panel's
 *       sync button) skip the wait.</li>
 * </ul>
 *
 * Several sources may share one syncer (the bank monitor sends bank and
 * inventory together); pending contents merge per source. Gates (sync
 * enabled, app key, game mode, username) are supplied as functions so this
 * stays unit-testable.
 */
@Slf4j
final class SourceSyncer {
	static final long GOAL_DEBOUNCE_SECONDS = 30;
	static final long DEFAULT_DEBOUNCE_SECONDS = 180;

	private final String label;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final LongSupplier clockMs;
	private final BooleanSupplier syncEnabled;
	private final Supplier<String> username;
	private final Consumer<BankSyncPayload> send;

	/** Item ids active owned-item goals are counting; set by the plugin from the goal tracker. */
	private volatile Supplier<Set<Integer>> goalItems = Set::of;
	/** Runs after every upload; set by the monitor (the bank monitor triggers a roadmap reconcile). */
	private volatile Runnable onSent;

	/** Contents last uploaded this session, per source. A source absent here was never sent. */
	private final Map<String, Map<Integer, Integer>> sentBySource = new HashMap<>();
	private final Map<String, Map<Integer, Integer>> pendingBySource = new LinkedHashMap<>();
	private String pendingUsername;
	private ScheduledFuture<?> pendingSync;
	private long pendingDueMs;

	SourceSyncer(
			String label,
			Gson gson,
			ScheduledExecutorService executor,
			BooleanSupplier syncEnabled,
			Supplier<String> username,
			Consumer<BankSyncPayload> send) {
		this(label, gson, executor, System::currentTimeMillis, syncEnabled, username, send);
	}

	SourceSyncer(
			String label,
			Gson gson,
			ScheduledExecutorService executor,
			LongSupplier clockMs,
			BooleanSupplier syncEnabled,
			Supplier<String> username,
			Consumer<BankSyncPayload> send) {
		this.label = label;
		this.gson = gson;
		this.executor = executor;
		this.clockMs = clockMs;
		this.syncEnabled = syncEnabled;
		this.username = username;
		this.send = send;
	}

	void setGoalItems(Supplier<Set<Integer>> goalItems) {
		this.goalItems = goalItems == null ? Set::of : goalItems;
	}

	void setOnSent(Runnable onSent) {
		this.onSent = onSent;
	}

	/** New contents for the syncer's single source (its label). */
	void submit(Map<Integer, Integer> quantities, boolean immediate) {
		Map<String, Map<Integer, Integer>> bySource = new LinkedHashMap<>();
		bySource.put(label, quantities == null ? Map.of() : quantities);
		submitSources(bySource, immediate);
	}

	/**
	 * New contents for one or more sources (canonical item id to quantity).
	 * Uploaded after the debounce, or right away when {@code immediate}.
	 */
	synchronized void submitSources(Map<String, Map<Integer, Integer>> bySource, boolean immediate) {
		if (bySource == null || bySource.isEmpty() || !syncEnabled.getAsBoolean()) {
			return;
		}
		String playerUsername = username.get();
		if (playerUsername == null) {
			log.debug("{} sync skipped: could not get player username", label);
			return;
		}
		boolean neverSent = false;
		boolean goalRelevant = false;
		boolean anyChange = false;
		Set<Integer> goals = goalItems.get();
		for (Map.Entry<String, Map<Integer, Integer>> e : bySource.entrySet()) {
			String source = e.getKey();
			Map<Integer, Integer> contents = new LinkedHashMap<>(e.getValue());
			Map<Integer, Integer> baseline = pendingBySource.containsKey(source)
					? pendingBySource.get(source) : sentBySource.get(source);
			Map<Integer, Integer> sent = sentBySource.get(source);
			if (sent != null && sent.equals(contents)) {
				pendingBySource.remove(source); // back to what the server has
				continue;
			}
			if (baseline != null && baseline.equals(contents)) {
				continue; // already pending as-is
			}
			anyChange = true;
			if (sent == null) {
				neverSent = true;
			}
			if (touchesGoalItem(baseline == null ? Map.of() : baseline, contents, goals)) {
				goalRelevant = true;
			}
			pendingBySource.put(source, contents);
		}
		if (pendingBySource.isEmpty()) {
			cancelPending();
			return;
		}
		pendingUsername = playerUsername;
		if (immediate || neverSent) {
			flushPending();
			return;
		}
		if (!anyChange && pendingSync != null) {
			return;
		}
		long delayMs = TimeUnit.SECONDS.toMillis(goalRelevant ? GOAL_DEBOUNCE_SECONDS : DEFAULT_DEBOUNCE_SECONDS);
		long now = clockMs.getAsLong();
		if (pendingSync != null) {
			// A shorter wait already running (goal change) is never extended.
			delayMs = Math.min(delayMs, Math.max(0, pendingDueMs - now));
			cancelPending();
		}
		pendingDueMs = now + delayMs;
		log.debug("{} change detected, debouncing sync for {}s", label, delayMs / 1000);
		pendingSync = executor.schedule(this::flushPending, delayMs, TimeUnit.MILLISECONDS);
	}

	/** Sends whatever is pending now (logout, plugin shutdown, forced sync). */
	synchronized void flushPending() {
		cancelPending();
		if (pendingBySource.isEmpty() || pendingUsername == null) {
			return;
		}
		Map<String, List<BankSyncPayload.BankItem>> itemsBySource = new LinkedHashMap<>();
		for (Map.Entry<String, Map<Integer, Integer>> e : pendingBySource.entrySet()) {
			itemsBySource.put(e.getKey(), ItemCollector.toBankItemList(e.getValue()));
			sentBySource.put(e.getKey(), e.getValue());
		}
		BankSyncPayload payload = new BankSyncPayload(pendingUsername, itemsBySource);
		pendingBySource.clear();
		log.debug("Syncing {} {} items ({}) for player: {}", payload.getTotalItemCount(), label,
				String.join(",", itemsBySource.keySet()), pendingUsername);
		send.accept(payload);
		Runnable listener = onSent;
		if (listener != null) {
			listener.run();
		}
	}

	/** Forgets what was sent so the next submit uploads even unchanged contents. */
	synchronized void invalidate() {
		sentBySource.clear();
	}

	synchronized void stop() {
		flushPending();
		sentBySource.clear();
	}

	private static boolean touchesGoalItem(Map<Integer, Integer> before, Map<Integer, Integer> after, Set<Integer> goals) {
		if (goals == null || goals.isEmpty()) {
			return false;
		}
		Set<Integer> ids = new HashSet<>(before.keySet());
		ids.addAll(after.keySet());
		for (int id : ids) {
			if (goals.contains(id) && !before.getOrDefault(id, 0).equals(after.getOrDefault(id, 0))) {
				return true;
			}
		}
		return false;
	}

	private void cancelPending() {
		if (pendingSync != null) {
			pendingSync.cancel(false);
			pendingSync = null;
		}
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.mystix.api.MystixApiClient;
import com.mystix.model.LoadoutSyncPayload;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
public class LoadoutMonitor {
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	private static final int EQUIPMENT_CHANGE_DEBOUNCE_SECONDS = 60;
	private static final int EMPTY_SLOT_ID = -1;
	private static final int MAX_INVENTORY_SLOTS = 28;

	private static final String INVENTORY_SETUPS_CONFIG_GROUP = "inventorysetups";
	private static final String SETUPS_V3_PREFIX = "setupsV3_";

	private static final Map<Integer, String> EQUIPMENT_SLOT_MAP = new HashMap<>();

	static {
		EQUIPMENT_SLOT_MAP.put(0, "head");
		EQUIPMENT_SLOT_MAP.put(1, "cape");
		EQUIPMENT_SLOT_MAP.put(2, "neck");
		EQUIPMENT_SLOT_MAP.put(3, "weapon");
		EQUIPMENT_SLOT_MAP.put(4, "body");
		EQUIPMENT_SLOT_MAP.put(5, "shield");
		EQUIPMENT_SLOT_MAP.put(7, "legs");
		EQUIPMENT_SLOT_MAP.put(9, "hands");
		EQUIPMENT_SLOT_MAP.put(10, "feet");
		EQUIPMENT_SLOT_MAP.put(12, "ring");
		EQUIPMENT_SLOT_MAP.put(13, "ammo");
	}

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private ScheduledFuture<?> debounceFuture = null;
	private String lastSyncJson = null;

	@Inject
	public LoadoutMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService,
			ConfigManager configManager,
			ItemManager itemManager,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.gson = gson;
	}

	public void stop() {
		if (debounceFuture != null) {
			debounceFuture.cancel(false);
			debounceFuture = null;
		}
		previousGameState = GameState.UNKNOWN;
		lastSyncJson = null;
	}

	/**
	 * Re-runs the loadout sync immediately (on the client thread, since it reads
	 * item containers), forcing a resend by clearing the change-detection
	 * snapshot. Used by the roadmap panel's "Sync &amp; refresh" button.
	 */
	public void forceSync() {
		executorService.execute(() -> clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncLoadouts();
		}));
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (!config.syncLoadouts()) {
			return;
		}

		GameState newState = event.getGameState();

		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			log.debug("Player logged in, scheduling loadout sync in {}s", LOGIN_SYNC_DELAY_SECONDS);
			executorService.schedule(() -> clientThread.invokeLater(this::syncLoadouts),
					LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			log.debug("Player logged out, syncing loadouts immediately");
			syncLoadouts();
		}

		previousGameState = newState;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		int containerId = event.getContainerId();
		if (containerId != InventoryID.WORN && containerId != InventoryID.INV) {
			return;
		}

		if (!config.syncLoadouts()) {
			return;
		}

		if (debounceFuture != null) {
			debounceFuture.cancel(false);
		}
		log.debug("Equipment/inventory changed, scheduling loadout sync in {}s", EQUIPMENT_CHANGE_DEBOUNCE_SECONDS);
		debounceFuture = executorService.schedule(() -> clientThread.invokeLater(this::syncLoadouts),
				EQUIPMENT_CHANGE_DEBOUNCE_SECONDS, TimeUnit.SECONDS);
	}

	/**
	 * Builds the full loadout payload (active gear + Inventory Setups) and sends
	 * it to the Mystix API if the contents changed since the last sync.
	 */
	private void syncLoadouts() {
		if (!SyncGuard.hasAppKey(config)) {
			log.debug("Loadout sync skipped: no App Key configured");
			return;
		}
		if (!config.syncLoadouts()) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			log.debug("Loadout sync skipped: special game mode detected");
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Loadout sync skipped: could not get player username");
			return;
		}

		List<LoadoutSyncPayload.LoadoutSet> loadoutSets = new ArrayList<>();

		LoadoutSyncPayload.LoadoutSet activeGear = buildActiveGearLoadout();
		if (activeGear != null) {
			loadoutSets.add(activeGear);
		}

		loadoutSets.addAll(buildInventorySetups());

		LoadoutSyncPayload payload = new LoadoutSyncPayload(playerUsername, loadoutSets);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Loadout contents unchanged, skipping sync");
			return;
		}

		lastSyncJson = json;
		log.debug("Syncing {} loadout sets for player: {}", loadoutSets.size(), playerUsername);
		apiClient.sendLoadoutSync(payload);
	}

	/**
	 * Reads the player's currently worn equipment and inventory, returning them
	 * as an "active_gear" loadout set. Returns null if both are empty.
	 */
	private LoadoutSyncPayload.LoadoutSet buildActiveGearLoadout() {
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null) {
			return null;
		}

		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = parseEquipmentSlots(equipment.getItems());

		List<LoadoutSyncPayload.InventoryItem> inventoryItems = new ArrayList<>();
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null) {
			Item[] invItems = inventory.getItems();
			for (int i = 0; i < invItems.length && i < MAX_INVENTORY_SLOTS; i++) {
				Item item = invItems[i];
				if (item.getId() == EMPTY_SLOT_ID || item.getQuantity() <= 0) {
					continue;
				}
				int canonicalId = itemManager.canonicalize(item.getId());
				inventoryItems.add(new LoadoutSyncPayload.InventoryItem(canonicalId, i));
			}
		}

		if (equipmentItems.isEmpty() && inventoryItems.isEmpty()) {
			return null;
		}

		return new LoadoutSyncPayload.LoadoutSet(
				"Current Gear", "active_gear", null,
				equipmentItems, inventoryItems);
	}

	private List<LoadoutSyncPayload.EquipmentItem> parseEquipmentSlots(Item[] items) {
		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = new ArrayList<>();
		for (int i = 0; i < items.length; i++) {
			String slot = EQUIPMENT_SLOT_MAP.get(i);
			if (slot == null) {
				continue;
			}
			Item item = items[i];
			if (item.getId() == EMPTY_SLOT_ID || item.getQuantity() <= 0) {
				continue;
			}
			int canonicalId = itemManager.canonicalize(item.getId());
			equipmentItems.add(new LoadoutSyncPayload.EquipmentItem(canonicalId, slot));
		}
		return equipmentItems;
	}

	/**
	 * Reads saved Inventory Setups from ConfigManager. Tries V3 format first,
	 * falling back to legacy V2/V1 formats if V3 is unavailable.
	 */
	private List<LoadoutSyncPayload.LoadoutSet> buildInventorySetups() {
		List<LoadoutSyncPayload.LoadoutSet> setups = new ArrayList<>();

		if (tryLoadV3Setups(setups)) {
			return setups;
		}

		loadLegacySetups(setups);
		return setups;
	}

	/**
	 * Attempts to load Inventory Setups using the V3 per-setup key format.
	 * Returns true if V3 keys were found (even if parsing individual setups fails).
	 */
	private boolean tryLoadV3Setups(List<LoadoutSyncPayload.LoadoutSet> setups) {
		try {
			String wholePrefix = ConfigManager.getWholeKey(INVENTORY_SETUPS_CONFIG_GROUP, null, SETUPS_V3_PREFIX);
			List<String> v3Keys = configManager.getConfigurationKeys(wholePrefix);
			if (v3Keys == null || v3Keys.isEmpty()) {
				return false;
			}

			log.debug("Found {} Inventory Setups (V3 format)", v3Keys.size());
			Map<String, String> sectionMap = loadSectionMap();

			for (String fullKey : v3Keys) {
				String configKey = fullKey.substring(INVENTORY_SETUPS_CONFIG_GROUP.length() + 1);
				String setupJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, configKey);
				if (setupJson == null || setupJson.isBlank()) {
					continue;
				}
				try {
					JsonObject setup = gson.fromJson(setupJson, JsonObject.class);
					LoadoutSyncPayload.LoadoutSet loadoutSet = parseInventorySetupV3(setup, sectionMap);
					if (loadoutSet != null) {
						setups.add(loadoutSet);
					}
				} catch (Exception e) {
					log.debug("Failed to parse V3 setup key {}: {}", configKey, e.getMessage());
				}
			}
			return true;
		} catch (Exception e) {
			log.debug("V3 Inventory Setups read failed: {}", e.getMessage());
			return false;
		}
	}

	/**
	 * Loads Inventory Setups from legacy V2 or V1 single-array config format.
	 */
	private void loadLegacySetups(List<LoadoutSyncPayload.LoadoutSet> setups) {
		String setupsJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, "setupsV2");
		if (setupsJson == null || setupsJson.isBlank()) {
			setupsJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, "setups");
		}
		if (setupsJson == null || setupsJson.isBlank()) {
			return;
		}

		try {
			JsonArray setupsArray = gson.fromJson(setupsJson, JsonArray.class);
			log.debug("Found {} Inventory Setups (legacy format)", setupsArray.size());
			for (JsonElement element : setupsArray) {
				JsonObject setup = element.getAsJsonObject();
				LoadoutSyncPayload.LoadoutSet loadoutSet = parseLegacySetup(setup);
				if (loadoutSet != null) {
					setups.add(loadoutSet);
				}
			}
		} catch (Exception e) {
			log.warn("Failed to parse Inventory Setups data: {}", e.getMessage());
		}
	}

	/**
	 * Reads the Inventory Setups sections config and builds a map of
	 * setup name to section/category name for folder grouping.
	 */
	private Map<String, String> loadSectionMap() {
		Map<String, String> sectionMap = new HashMap<>();
		try {
			String sectionsJson = configManager.getConfiguration(INVENTORY_SETUPS_CONFIG_GROUP, "sections");
			if (sectionsJson != null && !sectionsJson.isBlank()) {
				JsonArray sections = gson.fromJson(sectionsJson, JsonArray.class);
				for (JsonElement sectionEl : sections) {
					JsonObject section = sectionEl.getAsJsonObject();
					String sectionName = section.has("name") ? section.get("name").getAsString() : null;
					if (sectionName != null && section.has("setups")) {
						JsonArray setupNames = section.getAsJsonArray("setups");
						for (JsonElement nameEl : setupNames) {
							sectionMap.put(nameEl.getAsString(), sectionName);
						}
					}
				}
			}
		} catch (Exception e) {
			log.debug("Failed to load Inventory Setups sections: {}", e.getMessage());
		}
		return sectionMap;
	}

	private LoadoutSyncPayload.LoadoutSet parseInventorySetupV3(JsonObject setup, Map<String, String> sectionMap) {
		String name = getJsonString(setup, "name", "Unnamed Setup");
		String category = sectionMap.getOrDefault(name, null);

		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = parseJsonEquipmentArray(setup, "eq");
		List<LoadoutSyncPayload.InventoryItem> inventoryItems = parseJsonInventoryArray(setup, "inv");

		if (equipmentItems.isEmpty() && inventoryItems.isEmpty()) {
			return null;
		}

		return new LoadoutSyncPayload.LoadoutSet(name, "inventory_setup", category, equipmentItems, inventoryItems);
	}

	private LoadoutSyncPayload.LoadoutSet parseLegacySetup(JsonObject setup) {
		String name = getJsonString(setup, "name", "Unnamed Setup");

		String category = null;
		if (setup.has("stackName") && !setup.get("stackName").isJsonNull()) {
			category = setup.get("stackName").getAsString();
		}

		List<LoadoutSyncPayload.EquipmentItem> equipmentItems = parseJsonEquipmentArray(setup, "equipment");
		List<LoadoutSyncPayload.InventoryItem> inventoryItems = parseJsonInventoryArray(setup, "inventory");

		if (equipmentItems.isEmpty() && inventoryItems.isEmpty()) {
			return null;
		}

		return new LoadoutSyncPayload.LoadoutSet(name, "inventory_setup", category, equipmentItems, inventoryItems);
	}

	/**
	 * Parses a JSON array of equipment items from the given field, mapping each
	 * slot index to a named equipment slot via EQUIPMENT_SLOT_MAP.
	 */
	private List<LoadoutSyncPayload.EquipmentItem> parseJsonEquipmentArray(JsonObject setup, String fieldName) {
		List<LoadoutSyncPayload.EquipmentItem> items = new ArrayList<>();
		if (!setup.has(fieldName) || setup.get(fieldName).isJsonNull()) {
			return items;
		}

		JsonArray array = setup.getAsJsonArray(fieldName);
		for (int i = 0; i < array.size(); i++) {
			if (array.get(i).isJsonNull()) {
				continue;
			}
			JsonObject eq = array.get(i).getAsJsonObject();
			int itemId = eq.has("id") ? eq.get("id").getAsInt() : EMPTY_SLOT_ID;
			if (itemId <= 0) {
				continue;
			}

			String slot = EQUIPMENT_SLOT_MAP.get(i);
			if (slot == null) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			items.add(new LoadoutSyncPayload.EquipmentItem(canonicalId, slot));
		}
		return items;
	}

	/**
	 * Parses a JSON array of inventory items from the given field, preserving
	 * each item's slot index position.
	 */
	private List<LoadoutSyncPayload.InventoryItem> parseJsonInventoryArray(JsonObject setup, String fieldName) {
		List<LoadoutSyncPayload.InventoryItem> items = new ArrayList<>();
		if (!setup.has(fieldName) || setup.get(fieldName).isJsonNull()) {
			return items;
		}

		JsonArray array = setup.getAsJsonArray(fieldName);
		for (int i = 0; i < array.size(); i++) {
			if (array.get(i).isJsonNull()) {
				continue;
			}
			JsonObject inv = array.get(i).getAsJsonObject();
			int itemId = inv.has("id") ? inv.get("id").getAsInt() : EMPTY_SLOT_ID;
			if (itemId <= 0) {
				continue;
			}

			int canonicalId = itemManager.canonicalize(itemId);
			items.add(new LoadoutSyncPayload.InventoryItem(canonicalId, i));
		}
		return items;
	}

	private String getJsonString(JsonObject obj, String key, String defaultValue) {
		return obj.has(key) ? obj.get(key).getAsString() : defaultValue;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.BiConsumer;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks the plank sack from its per-plank varbits (exact, no interface
 * needed), feeding the goal tracker live and uploading bank-memory source
 * {@code plank_sack} through a debounced {@link SourceSyncer}.
 */
@Slf4j
@Singleton
public class PlankSackMonitor {
	static final String SOURCE = "plank_sack";

	/** Varbit to the plank item it counts. */
	static final Map<Integer, Integer> PLANK_VARBITS;

	static {
		Map<Integer, Integer> m = new LinkedHashMap<>();
		m.put(VarbitID.PLANK_SACK_PLAIN, ItemID.WOODPLANK);
		m.put(VarbitID.PLANK_SACK_OAK, ItemID.PLANK_OAK);
		m.put(VarbitID.PLANK_SACK_TEAK, ItemID.PLANK_TEAK);
		m.put(VarbitID.PLANK_SACK_MAHOGANY, ItemID.PLANK_MAHOGANY);
		m.put(VarbitID.PLANK_SACK_CAMPHOR, ItemID.PLANK_CAMPHOR);
		m.put(VarbitID.PLANK_SACK_IRONWOOD, ItemID.PLANK_IRONWOOD);
		m.put(VarbitID.PLANK_SACK_ROSEWOOD, ItemID.PLANK_ROSEWOOD);
		PLANK_VARBITS = java.util.Collections.unmodifiableMap(m);
	}

	private final Client client;
	private final SourceSyncer syncer;

	private boolean dirty;
	private GameState previousGameState = GameState.UNKNOWN;
	private volatile BiConsumer<String, Map<Integer, Integer>> snapshotListener;

	@Inject
	public PlankSackMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			Gson gson,
			ScheduledExecutorService executor) {
		this.client = client;
		this.syncer = new SourceSyncer(SOURCE, gson, executor,
				() -> config.syncBankMemory() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client),
				() -> SyncGuard.getPlayerUsername(client),
				apiClient::sendBankSync);
	}

	public void setSnapshotListener(BiConsumer<String, Map<Integer, Integer>> listener) {
		this.snapshotListener = listener;
	}

	/** Item ids active owned-item goals are counting (short debounce for them); set by the plugin. */
	public void setGoalItems(Supplier<Set<Integer>> goalItems) {
		syncer.setGoalItems(goalItems);
	}

	public void stop() {
		syncer.stop();
		dirty = false;
	}

	public void syncNow() {
		syncer.invalidate();
		dirty = true;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (PLANK_VARBITS.containsKey(event.getVarbitId())) {
			dirty = true;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			dirty = true;
		} else if (SyncGuard.isLogout(previousGameState, newState)) {
			syncer.flushPending();
		}
		previousGameState = newState;
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (!dirty) {
			return;
		}
		dirty = false;
		Map<Integer, Integer> contents = contents(client::getVarbitValue);
		BiConsumer<String, Map<Integer, Integer>> listener = snapshotListener;
		if (listener != null) {
			listener.accept(SOURCE, contents);
		}
		syncer.submit(contents, false);
	}

	/** Plank item id to count from the varbit values. */
	static Map<Integer, Integer> contents(IntUnaryOperator varbitValue) {
		Map<Integer, Integer> contents = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> e : PLANK_VARBITS.entrySet()) {
			int count = varbitValue.applyAsInt(e.getKey());
			if (count > 0) {
				contents.put(e.getValue(), count);
			}
		}
		return contents;
	}
}

package com.mystix;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the whole roadmap's progress bar inside the goal completion popup while
 * it is on screen. The game's notification widget only carries text, so the
 * popup body reserves blank lines at the bottom and this overlay paints the bar
 * ("done / total goals" plus percent) into that space, anchored to the widget.
 */
public class GoalCompletionOverlay extends Overlay {
	/** Inset from the popup's frame on each side. */
	private static final int SIDE_PAD = 14;
	/**
	 * Inset from the bottom of the popup's box. The body reserves two blank
	 * lines and the box adds its own margin under the text; the bar block
	 * (about two lines tall) sits at the bottom of that space so roughly a line
	 * of air separates it from the text above and a similar margin remains below.
	 */
	private static final int BOTTOM_PAD = 8;
	/** The box grows in during its open animation; wait until it has room. */
	private static final int MIN_BOX_HEIGHT = 48;

	private final Client client;
	private final GoalCompletionNotifier notifier;

	@Inject
	public GoalCompletionOverlay(Client client, GoalCompletionNotifier notifier) {
		this.client = client;
		this.notifier = notifier;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		GoalCompletionNotifier.Popup popup = notifier.getActive();
		if (popup == null || popup.getGoalsTotal() <= 0) {
			return null;
		}
		Widget container = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
		if (container == null || container.isHidden()) {
			return null;
		}
		Rectangle bounds = container.getBounds();
		if (bounds == null || bounds.width <= 2 * SIDE_PAD || bounds.height < MIN_BOX_HEIGHT) {
			return null;
		}

		int done = popup.getGoalsDone();
		int total = popup.getGoalsTotal();
		int percent = (int) Math.min(100, Math.max(0, (long) done * 100L / total));
		GoalProgressBarComponent bar = new GoalProgressBarComponent(
				percent / 100d, done + " / " + total + " goals", percent + "%");

		// Bar block height: top gap + bar + gap + one text line.
		int height = GoalProgressBarComponent.TOP_GAP + GoalProgressBarComponent.BAR_HEIGHT
				+ GoalProgressBarComponent.BAR_TEXT_GAP + graphics.getFontMetrics().getHeight();
		int width = bounds.width - 2 * SIDE_PAD;
		bar.setPreferredLocation(new Point(bounds.x + SIDE_PAD, bounds.y + bounds.height - BOTTOM_PAD - height));
		bar.setPreferredSize(new Dimension(width, 0));
		return bar.render(graphics);
	}
}

package com.mystix;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.LongSupplier;

/**
 * Coalesces roadmap re-reads: a periodic refresh plus debounced on-demand
 * requests. Several requests inside the delay window collapse into one read that
 * fires after the <em>last</em> request, so a burst of uploads produces a single
 * fetch once they have all landed. A read already in flight defers the next one
 * briefly instead of stacking requests, and reads are at least
 * {@link #MIN_INTERVAL_SECONDS} apart: a player uploading every few seconds
 * gets one re-read a minute, not one per upload.
 */
final class ReconcileScheduler {
	static final int PERIODIC_MINUTES = 10;
	static final int RETRY_WHEN_BUSY_SECONDS = 5;
	static final int MIN_INTERVAL_SECONDS = 60;
	/** A pending read closer than this counts as "syncing" for the UI hint. */
	static final int SYNCING_HINT_SECONDS = 15;

	private final ScheduledExecutorService executor;
	private final Runnable refresh;
	private final LongSupplier clockMs;
	private final AtomicBoolean inFlight = new AtomicBoolean();

	private ScheduledFuture<?> periodic;
	private ScheduledFuture<?> pending;
	private boolean busyRetryUsed;
	private long lastFireMs = Long.MIN_VALUE;
	private long pendingDueMs;

	ReconcileScheduler(ScheduledExecutorService executor, Runnable refresh) {
		this(executor, refresh, System::currentTimeMillis);
	}

	ReconcileScheduler(ScheduledExecutorService executor, Runnable refresh, LongSupplier clockMs) {
		this.executor = executor;
		this.refresh = refresh;
		this.clockMs = clockMs;
	}

	/** Re-read after {@code delaySeconds}, or once the minimum interval since
	 * the last read has passed if that is later; replaces any pending request. */
	synchronized void request(int delaySeconds) {
		if (pending != null) {
			pending.cancel(false);
		}
		long delayMs = TimeUnit.SECONDS.toMillis(Math.max(0, delaySeconds));
		if (lastFireMs != Long.MIN_VALUE) {
			long earliestMs = lastFireMs + TimeUnit.SECONDS.toMillis(MIN_INTERVAL_SECONDS);
			delayMs = Math.max(delayMs, earliestMs - clockMs.getAsLong());
		}
		pendingDueMs = clockMs.getAsLong() + delayMs;
		pending = executor.schedule(this::firePending, delayMs, TimeUnit.MILLISECONDS);
	}

	/** Starts the periodic refresh; safe to call more than once. */
	synchronized void startPeriodic() {
		if (periodic == null) {
			periodic = executor.scheduleAtFixedRate(
					this::firePeriodic, PERIODIC_MINUTES, PERIODIC_MINUTES, TimeUnit.MINUTES);
		}
	}

	synchronized void stop() {
		if (periodic != null) {
			periodic.cancel(false);
			periodic = null;
		}
		if (pending != null) {
			pending.cancel(false);
			pending = null;
		}
		inFlight.set(false);
		busyRetryUsed = false;
		lastFireMs = Long.MIN_VALUE;
	}

	/** True while a re-read is scheduled or running. */
	synchronized boolean isBusy() {
		return pending != null || inFlight.get();
	}

	/** True while a re-read is running or due within {@link #SYNCING_HINT_SECONDS}.
	 * Drives the "Syncing" hint: a read held back by the minimum interval
	 * would otherwise show it for up to a minute. */
	synchronized boolean isSyncingSoon() {
		if (inFlight.get()) {
			return true;
		}
		return pending != null
				&& pendingDueMs - clockMs.getAsLong() <= TimeUnit.SECONDS.toMillis(SYNCING_HINT_SECONDS);
	}

	/** Claims the in-flight slot; false when a read is already running. */
	boolean markInFlight() {
		return inFlight.compareAndSet(false, true);
	}

	void clearInFlight() {
		inFlight.set(false);
	}

	private void firePending() {
		synchronized (this) {
			pending = null;
		}
		fire();
	}

	/** The periodic read also answers any request still waiting, so drop it
	 * (left scheduled, a later request could no longer cancel it). */
	private void firePeriodic() {
		synchronized (this) {
			if (pending != null) {
				pending.cancel(false);
				pending = null;
			}
		}
		fire();
	}

	private void fire() {
		synchronized (this) {
			if (inFlight.get()) {
				// Let the running read finish; try once more shortly after.
				if (!busyRetryUsed) {
					busyRetryUsed = true;
					request(RETRY_WHEN_BUSY_SECONDS);
				}
				return;
			}
			busyRetryUsed = false;
			lastFireMs = clockMs.getAsLong();
		}
		refresh.run();
	}
}

package com.mystix;

import com.mystix.model.RoadmapGoal;
import java.io.File;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.SoundEffectID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.api.WidgetNode;
import net.runelite.client.RuneLite;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;

/**
 * Shows the game's own notification popup (the one used for collection log and
 * combat task completions) when a roadmap goal is completed, and plays a sound.
 *
 * <p>The popup is the {@code NOTIFICATION_DISPLAY} interface opened under the
 * current top-level layout's notifications component and initialised by its
 * script; it animates in on its own and is closed once its container collapses.
 * Popups queue so two quick completions show one after the other.
 */
@Slf4j
@Singleton
public class GoalCompletionNotifier {
	/** Fills the notification interface with a title and body; RuneLite's
	 * {@code ScriptID} only names the follow-up open/delay scripts (3346/3347). */
	static final int NOTIFICATION_DISPLAY_INIT = 3343;
	/** In-game sound effect for the default option. */
	static final int DEFAULT_SOUND_ID = SoundEffectID.GE_ADD_OFFER_DINGALING;
	static final String CUSTOM_SOUND_PATH = "mystix/goal-complete.wav";
	static final String TITLE = "<col=f28c28>Roadmap Goal Complete!</col>";

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final AudioPlayer audioPlayer;
	private final ScheduledExecutorService executorService;

	/** A popup that is queued or on screen, with the roadmap progress to draw under it. */
	public static final class Popup {
		private final String body;
		private final String roadmapTitle;
		private final int goalsDone;
		private final int goalsTotal;

		Popup(String body, String roadmapTitle, int goalsDone, int goalsTotal) {
			this.body = body;
			this.roadmapTitle = roadmapTitle;
			this.goalsDone = goalsDone;
			this.goalsTotal = goalsTotal;
		}

		public String getRoadmapTitle() {
			return roadmapTitle;
		}

		public int getGoalsDone() {
			return goalsDone;
		}

		public int getGoalsTotal() {
			return goalsTotal;
		}
	}

	private final Deque<Popup> queue = new ArrayDeque<>();
	private WidgetNode openNode;
	/** The popup currently on screen (read by the overlay on the render thread). */
	private volatile Popup active;

	@Inject
	public GoalCompletionNotifier(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			AudioPlayer audioPlayer,
			ScheduledExecutorService executorService) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.audioPlayer = audioPlayer;
		this.executorService = executorService;
	}

	/**
	 * Queues a popup for the goal; safe to call from any thread.
	 *
	 * @param goalsDone  completed goals in the roadmap (including this one)
	 * @param goalsTotal goals in the roadmap
	 */
	public void show(RoadmapGoal goal, String roadmapTitle, int goalsDone, int goalsTotal) {
		if (goal == null || goal.getName() == null) {
			return;
		}
		Popup popup = new Popup(body(goal.getName(), roadmapTitle, goalsDone, goalsTotal),
				roadmapTitle, goalsDone, goalsTotal);
		clientThread.invokeLater(() -> {
			if (!config.showGoalPopup() || client.getGameState() != GameState.LOGGED_IN) {
				return;
			}
			queue.add(popup);
			if (openNode == null) {
				showNext();
			}
		});
	}

	/** The popup on screen right now, or null. */
	public Popup getActive() {
		return active;
	}

	/** Drops queued popups and closes an open one (plugin shutdown). */
	public void clear() {
		clientThread.invokeLater(() -> {
			queue.clear();
			closeOpen();
		});
	}

	/** Blank lines reserved at the bottom of the body so the roadmap progress bar
	 * ({@link GoalCompletionOverlay}) can be drawn inside the box. */
	static final String PROGRESS_SPACER = "<br><br>";

	/** Builds the popup body: the goal name in white, the roadmap title beneath,
	 * then reserved space for the progress bar when the roadmap has goals. */
	static String body(String goalName, String roadmapTitle, int goalsDone, int goalsTotal) {
		String name = Text.removeTags(goalName);
		StringBuilder sb = new StringBuilder("<col=ffffff>").append(name).append("</col>");
		if (roadmapTitle != null && !roadmapTitle.trim().isEmpty()) {
			sb.append("<br><col=c6c6c6>").append(Text.removeTags(roadmapTitle)).append("</col>");
		}
		if (goalsTotal > 0) {
			sb.append(PROGRESS_SPACER);
		}
		return sb.toString();
	}

	/** The notifications component of the given top-level layout, or -1 when the
	 * layout has no popup slot the plugin knows about. */
	static int parentComponentFor(int topLevelInterfaceId) {
		switch (topLevelInterfaceId) {
			case InterfaceID.TOPLEVEL_OSRS_STRETCH:
				return InterfaceID.ToplevelOsrsStretch.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_PRE_EOC:
				return InterfaceID.ToplevelPreEoc.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL_DISPLAY:
				return InterfaceID.ToplevelDisplay.NOTIFICATIONS;
			case InterfaceID.TOPLEVEL:
				return InterfaceID.Toplevel.NOTIFICATIONS;
			default:
				return -1;
		}
	}

	// Client thread from here down.

	private void showNext() {
		Popup popup = queue.poll();
		if (popup == null) {
			return;
		}
		int parent = parentComponentFor(client.getTopLevelInterfaceId());
		if (parent == -1) {
			log.debug("No notification slot for top-level interface {}", client.getTopLevelInterfaceId());
			queue.clear();
			return;
		}
		try {
			openNode = client.openInterface(parent, InterfaceID.NOTIFICATION_DISPLAY, WidgetModalMode.MODAL_CLICKTHROUGH);
			client.runScript(NOTIFICATION_DISPLAY_INIT, TITLE, popup.body, -1);
		} catch (RuntimeException e) {
			log.debug("Goal popup could not be opened", e);
			openNode = null;
			return;
		}
		active = popup;
		playSound();
		clientThread.invokeLater(this::pollClosed);
	}

	/** Returns false to be invoked again next tick while the popup is still visible. */
	private boolean pollClosed() {
		if (openNode == null) {
			return true;
		}
		Widget container = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
		if (container != null && container.getWidth() > 0) {
			return false;
		}
		closeOpen();
		showNext();
		return true;
	}

	private void closeOpen() {
		active = null;
		if (openNode == null) {
			return;
		}
		try {
			client.closeInterface(openNode, true);
		} catch (RuntimeException e) {
			log.debug("Goal popup was already closed");
		}
		openNode = null;
	}

	private void playSound() {
		GoalCompleteSound sound = config.goalCompleteSound();
		if (sound == null || sound == GoalCompleteSound.OFF) {
			return;
		}
		int volume = client.getPreferences().getSoundEffectVolume();
		if (volume <= 0) {
			return;
		}
		if (sound == GoalCompleteSound.IN_GAME) {
			client.playSoundEffect(DEFAULT_SOUND_ID, volume);
			return;
		}
		File file = new File(RuneLite.RUNELITE_DIR, CUSTOM_SOUND_PATH);
		if (!file.isFile()) {
			log.debug("Custom goal sound not found at {}", file);
			return;
		}
		// Game sound effect volume is 0-127; map to a gain in dB like RuneLite's Notifier.
		float gainDb = (float) (20d * Math.log10(volume / 127d));
		executorService.execute(() -> {
			try {
				audioPlayer.play(file, gainDb);
			} catch (Exception e) {
				log.debug("Custom goal sound could not be played", e);
			}
		});
	}
}

package com.mystix;

import com.mystix.model.RoadmapSummary;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;

/**
 * The player's last fetched roadmap list, reused by background refreshes so they
 * re-read only the roadmaps themselves. Roadmaps created or deleted elsewhere
 * show up once the list is older than {@link #REUSE_MS} (the periodic refresh
 * always is) or when the panel opens.
 */
final class RoadmapListCache {
	static final long REUSE_MS = TimeUnit.MINUTES.toMillis(5);

	private String player;
	private List<RoadmapSummary> summaries;
	private long fetchedAtMs;

	synchronized void record(String player, List<RoadmapSummary> summaries, long nowMs) {
		this.player = player;
		this.summaries = summaries == null
				? Collections.emptyList()
				: Collections.unmodifiableList(new ArrayList<>(summaries));
		this.fetchedAtMs = nowMs;
	}

	/** The list to reuse for {@code player}, or null when it has to be fetched. */
	synchronized List<RoadmapSummary> reusable(String player, long nowMs) {
		if (summaries == null || this.player == null || !this.player.equals(player)) {
			return null;
		}
		return nowMs - fetchedAtMs < REUSE_MS ? summaries : null;
	}

	/** Forget the list (a roadmap read failed, or the session ended). */
	synchronized void invalidate() {
		summaries = null;
		player = null;
	}
}

package com.mystix;

import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;

/**
 * Describes one storage item whose contents the game never exposes as a
 * container or varbit (fish barrel, log basket, gem bag, coal bag, herb
 * sack): which items it takes, its capacity, and the chat text the game
 * emits when something goes in, when it is checked, and when it is emptied.
 * The bookkeeping lives in {@link StorageItemLedger}; RuneLite wiring in
 * {@link StorageItemMonitor}.
 */
final class StorageItemSpec {
	/** Chat lines (GAMEMESSAGE) every "empty your containers" bank action emits. */
	static final List<String> CONTAINERS_EMPTIED_MESSAGES = List.of(
			"You empty all of your containers into the bank.",
			"Your containers are already empty.");

	final String source;
	final Set<Integer> closedIds;
	final Set<Integer> openIds;
	/** Items the container accepts (canonical ids). */
	final Set<Integer> acceptedIds;
	/** Combined capacity, or 0 for no combined cap. */
	final int capacity;
	/** Per-item capacity, or 0 for none. */
	final int perItemCapacity;
	/** Chat lines emitted when an accepted item is gathered or stored; group 1 is the item name. Empty when the item has none. */
	final List<Pattern> gatherPatterns;
	/** SPAM lines meaning "one more of the item just gathered". */
	final Set<String> extraGatherMessages;
	/** Exact GAMEMESSAGE lines meaning the container is now empty. */
	final Set<String> emptiedMessages;
	/** GAMEMESSAGE prefixes meaning the container was emptied into the bank. */
	final Set<String> emptiedPrefixes;
	/** Exact GAMEMESSAGE lines meaning the container is full (gathering now lands in the inventory). */
	final Set<String> fullMessages;
	/** Chat / widget text prefix of the "Check" listing, e.g. "The barrel contains:". */
	final String checkPrefix;
	/** Chat / widget text meaning "Check" found it empty. */
	final Set<String> checkEmptyMessages;
	/** Skill whose XP drop on a gather tick means one gathered item was consumed instead of stored (infernal tools). */
	final Skill consumeSkill;
	/** Skill whose XP drop, with no inventory change, is itself the store signal (herb sack: Farming). */
	final Skill xpCreditSkill;
	/** For {@link #xpCreditSkill}: XP per stored item, keyed by item id. */
	final Map<Integer, Double> xpPerItem;
	/** Leading word to strip from item names before matching chat text ("raw ", "uncut "). */
	final String namePrefixToStrip;
	/** Chat names that differ from the item name (after the prefix strip). */
	final Map<String, String> nameAliases;

	private StorageItemSpec(Builder b) {
		this.source = b.source;
		this.closedIds = Set.copyOf(b.closedIds);
		this.openIds = Set.copyOf(b.openIds);
		this.acceptedIds = Set.copyOf(b.acceptedIds);
		this.capacity = b.capacity;
		this.perItemCapacity = b.perItemCapacity;
		this.gatherPatterns = List.copyOf(b.gatherPatterns);
		this.extraGatherMessages = Set.copyOf(b.extraGatherMessages);
		this.emptiedMessages = Set.copyOf(b.emptiedMessages);
		this.emptiedPrefixes = Set.copyOf(b.emptiedPrefixes);
		this.fullMessages = Set.copyOf(b.fullMessages);
		this.checkPrefix = b.checkPrefix;
		this.checkEmptyMessages = Set.copyOf(b.checkEmptyMessages);
		this.consumeSkill = b.consumeSkill;
		this.xpCreditSkill = b.xpCreditSkill;
		this.xpPerItem = Collections.unmodifiableMap(new LinkedHashMap<>(b.xpPerItem));
		this.namePrefixToStrip = b.namePrefixToStrip;
		this.nameAliases = Collections.unmodifiableMap(new HashMap<>(b.nameAliases));
	}

	boolean isContainerItem(int itemId) {
		return closedIds.contains(itemId) || openIds.contains(itemId);
	}

	/** The chat form of an item name: lower case, container prefix stripped. */
	String chatName(String itemName) {
		String name = itemName == null ? "" : itemName.trim().toLowerCase();
		if (namePrefixToStrip != null && name.startsWith(namePrefixToStrip)) {
			name = name.substring(namePrefixToStrip.length());
		}
		return name;
	}

	// ------------------------------------------------------------- specs

	static StorageItemSpec fishBarrel() {
		return new Builder("fish_barrel")
				.closed(ItemID.FISH_BARREL_CLOSED, ItemID.FISH_SACK_BARREL_CLOSED)
				.open(ItemID.FISH_BARREL_OPEN, ItemID.FISH_SACK_BARREL_OPEN)
				.accepts(ItemID.RAW_SHRIMP, ItemID.RAW_SARDINE, ItemID.RAW_HERRING, ItemID.RAW_ANCHOVIES,
						ItemID.RAW_MACKEREL, ItemID.RAW_TROUT, ItemID.RAW_COD, ItemID.RAW_PIKE, ItemID.MORT_SLIMEY_EEL,
						ItemID.RAW_SALMON, ItemID.RAW_TUNA, ItemID.HUNTING_RAW_FISH_SPECIAL, ItemID.RAW_CAVE_EEL,
						ItemID.RAW_LOBSTER, ItemID.RAW_BASS, ItemID.BRUT_SPAWNING_TROUT, ItemID.RAW_SWORDFISH,
						ItemID.RAW_LAVA_EEL, ItemID.BRUT_SPAWNING_SALMON, ItemID.RAW_MONKFISH, ItemID.TBWT_RAW_KARAMBWAN,
						ItemID.BRUT_STURGEON, ItemID.RAW_SHARK, ItemID.INFERNAL_EEL, ItemID.RAW_ANGLERFISH,
						ItemID.RAW_DARK_CRAB, ItemID.SNAKEBOSS_EEL, ItemID.RAW_SWORDTIP_SQUID, ItemID.RAW_JUMBO_SQUID,
						ItemID.AERIAL_FISHING_BLUEGILL, ItemID.AERIAL_FISHING_COMMON_TENCH,
						ItemID.AERIAL_FISHING_MOTTLED_EEL, ItemID.AERIAL_FISHING_GREATER_SIREN,
						ItemID.RAW_SEATURTLE, ItemID.RAW_MANTARAY, ItemID.RAW_GIANT_KRILL, ItemID.RAW_HADDOCK,
						ItemID.RAW_YELLOWFIN, ItemID.RAW_HALIBUT, ItemID.RAW_BLUEFIN, ItemID.RAW_MARLIN)
				.capacity(28)
				.gather("^You catch (?:an?|some)(?: raw)? ([a-zA-Z ]+?)[.!]?(?: It hardens as you handle it with your ice gloves\\.)?$")
				.extraGather("Rada's blessing enabled you to catch an extra fish.",
						"The spirit flakes enabled you to catch an extra fish.")
				.emptied("The barrel is empty.", "Your barrel is empty.", "You empty the barrel.")
				.full("The barrel is full. It may be emptied at a bank.")
				.check("The barrel contains:", "The barrel is empty.")
				.consumeSkill(Skill.COOKING)
				.stripPrefix("raw ")
				.alias("slimy swamp eel", "slimy eel")
				.alias("shrimp", "shrimps")
				.build();
	}

	static StorageItemSpec logBasket() {
		return new Builder("log_basket")
				.closed(ItemID.LOG_BASKET_CLOSED, ItemID.FORESTRY_BASKET_CLOSED)
				.open(ItemID.LOG_BASKET_OPEN, ItemID.FORESTRY_BASKET_OPEN)
				.accepts(ItemID.LOGS, ItemID.ACHEY_TREE_LOGS, ItemID.OAK_LOGS, ItemID.WILLOW_LOGS, ItemID.TEAK_LOGS,
						ItemID.MAPLE_LOGS, ItemID.MAHOGANY_LOGS, ItemID.ARCTIC_PINE_LOG, ItemID.YEW_LOGS,
						ItemID.MAGIC_LOGS, ItemID.REDWOOD_LOGS, ItemID.ROSEWOOD_LOGS, ItemID.IRONWOOD_LOGS,
						ItemID.CAMPHOR_LOGS, ItemID.BLISTERWOOD_LOGS, ItemID.JUNIPER_LOGS)
				.capacity(28)
				.gather("^You get some ([a-zA-Z ]+?)\\.?$")
				.gather("^You get some ([a-zA-Z ]+?) and give them to [A-Za-z ]+\\.$")
				.extraGather("Your Kandarin headgear provides you with an additional log.",
						"The nature offerings enabled you to chop an extra log.")
				.emptied("You empty your basket into the bank.", "You empty your basket.",
						"Your basket is empty.", "The basket is empty.")
				.full("The basket is full.")
				.check("The basket contains:", "The basket is empty.")
				.consumeSkill(Skill.FIREMAKING)
				.build();
	}

	static StorageItemSpec gemBag() {
		return new Builder("gem_bag")
				.closed(ItemID.GEM_BAG, ItemID.GEM_POUCH, ItemID.GEM_SATCHEL, ItemID.GEM_TOTE, ItemID.GEM_SACK)
				.open(ItemID.GEM_BAG_OPEN, ItemID.GEM_POUCH_OPEN, ItemID.GEM_SATCHEL_OPEN, ItemID.GEM_TOTE_OPEN,
						ItemID.GEM_SACK_OPEN)
				.accepts(ItemID.UNCUT_SAPPHIRE, ItemID.UNCUT_EMERALD, ItemID.UNCUT_RUBY, ItemID.UNCUT_DIAMOND,
						ItemID.UNCUT_DRAGONSTONE, ItemID.UNCUT_OPAL, ItemID.UNCUT_JADE, ItemID.UNCUT_RED_TOPAZ)
				.perItemCapacity(60)
				.gather("^You just (?:mined|found) an? ([a-zA-Z ]+?)[.!]?$")
				.gather("^You steal an uncut ([a-zA-Z ]+?) and add it to your gem [a-z]+\\.$")
				.gather("^You put the stolen Uncut ([a-zA-Z ]+?) into your gem [a-z]+\\.$")
				.emptiedPrefix("You empty your gem", "You empty the gem")
				.emptiedPrefix("The gem bag is", "The gem pouch is", "The gem satchel is", "The gem tote is", "The gem sack is")
				.check("", "The gem bag is empty.")
				.stripPrefix("uncut ")
				.build();
	}

	static StorageItemSpec coalBag() {
		return new Builder("coal_bag")
				.closed(ItemID.COAL_BAG)
				.open(ItemID.COAL_BAG_OPEN)
				.accepts(ItemID.COAL)
				.capacity(36) // 27, or 36 with a Smithing cape; the full message stops crediting either way
				.gather("^You manage to mine some (coal)\\.$")
				.extraGather("Your Celestial ring allows you to mine an additional ore.",
						"The Varrock platebody enabled you to mine an additional ore.")
				.emptied("The coal bag is now empty.", "The coal bag is empty.")
				.full("The coal bag is full.")
				.check("The coal bag", "The coal bag is empty.")
				.build();
	}

	static StorageItemSpec herbSack() {
		Builder b = new Builder("herb_sack")
				.closed(ItemID.SLAYER_HERB_SACK, ItemID.SLAYER_HERB_SACK_SILK)
				.open(ItemID.SLAYER_HERB_SACK_OPEN, ItemID.SLAYER_HERB_SACK_SILK_OPEN)
				// 30 per herb, or 100 for the silk-lined sack. The larger bound is
				// safe: once a sack is full the herb lands in the inventory, which
				// blocks the credit.
				.perItemCapacity(100)
				.gather("^You put the Grimy ([a-zA-Z ]+?) herb into your herb sack\\.$")
				.emptiedPrefix("You empty your herb sack", "You empty the herb sack")
				.emptied("The herb sack is empty.")
				.check("You look in your herb sack and see:", "The herb sack is empty.")
				.xpCreditSkill(Skill.FARMING)
				.stripPrefix("grimy ");
		// Farming XP per herb harvested: the only per-herb signal the game gives
		// when an open sack swallows the harvest.
		b.xp(ItemID.UNIDENTIFIED_GUAM, 12.5).xp(ItemID.UNIDENTIFIED_MARENTILL, 15).xp(ItemID.UNIDENTIFIED_TARROMIN, 18)
				.xp(ItemID.UNIDENTIFIED_HARRALANDER, 24).xp(ItemID.UNIDENTIFIED_RANARR, 30.5)
				.xp(ItemID.UNIDENTIFIED_TOADFLAX, 38.5).xp(ItemID.UNIDENTIFIED_IRIT, 48.5)
				.xp(ItemID.UNIDENTIFIED_AVANTOE, 61.5).xp(ItemID.UNIDENTIFIED_KWUARM, 78)
				.xp(ItemID.UNIDENTIFIED_SNAPDRAGON, 98.5).xp(ItemID.UNIDENTIFIED_HUASCA, 110)
				.xp(ItemID.UNIDENTIFIED_CADANTINE, 120).xp(ItemID.UNIDENTIFIED_LANTADYME, 151.5)
				.xp(ItemID.UNIDENTIFIED_DWARF_WEED, 192).xp(ItemID.UNIDENTIFIED_TORSTOL, 224.5);
		b.accepts(b.xpPerItem.keySet().stream().mapToInt(Integer::intValue).toArray());
		return b.build();
	}

	static List<StorageItemSpec> all() {
		return List.of(fishBarrel(), logBasket(), gemBag(), coalBag(), herbSack());
	}

	// ---------------------------------------------------------- builder

	private static final class Builder {
		final String source;
		final Set<Integer> closedIds = new java.util.HashSet<>();
		final Set<Integer> openIds = new java.util.HashSet<>();
		final Set<Integer> acceptedIds = new java.util.LinkedHashSet<>();
		int capacity;
		int perItemCapacity;
		final List<Pattern> gatherPatterns = new java.util.ArrayList<>();
		final Set<String> extraGatherMessages = new java.util.HashSet<>();
		final Set<String> emptiedMessages = new java.util.HashSet<>(CONTAINERS_EMPTIED_MESSAGES);
		final Set<String> emptiedPrefixes = new java.util.HashSet<>();
		final Set<String> fullMessages = new java.util.HashSet<>();
		String checkPrefix = "";
		final Set<String> checkEmptyMessages = new java.util.HashSet<>();
		Skill consumeSkill;
		Skill xpCreditSkill;
		final Map<Integer, Double> xpPerItem = new LinkedHashMap<>();
		String namePrefixToStrip;
		final Map<String, String> nameAliases = new HashMap<>();

		Builder(String source) {
			this.source = source;
		}

		Builder closed(int... ids) { for (int id : ids) closedIds.add(id); return this; }
		Builder open(int... ids) { for (int id : ids) openIds.add(id); return this; }
		Builder accepts(int... ids) { for (int id : ids) acceptedIds.add(id); return this; }
		Builder capacity(int c) { capacity = c; return this; }
		Builder perItemCapacity(int c) { perItemCapacity = c; return this; }
		Builder gather(String regex) { gatherPatterns.add(Pattern.compile(regex)); return this; }
		Builder extraGather(String... m) { Collections.addAll(extraGatherMessages, m); return this; }
		Builder emptied(String... m) { Collections.addAll(emptiedMessages, m); return this; }
		Builder emptiedPrefix(String... m) { Collections.addAll(emptiedPrefixes, m); return this; }
		Builder full(String... m) { Collections.addAll(fullMessages, m); return this; }
		Builder check(String prefix, String... empty) { checkPrefix = prefix; Collections.addAll(checkEmptyMessages, empty); return this; }
		Builder consumeSkill(Skill s) { consumeSkill = s; return this; }
		Builder xpCreditSkill(Skill s) { xpCreditSkill = s; return this; }
		Builder xp(int itemId, double xp) { xpPerItem.put(itemId, xp); return this; }
		Builder stripPrefix(String p) { namePrefixToStrip = p; return this; }
		Builder alias(String chat, String item) { nameAliases.put(chat, item); return this; }

		StorageItemSpec build() {
			return new StorageItemSpec(this);
		}
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.SlayerCatalogPayload;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Dumps the game-cache slayer DB tables (SlayerTask, SlayerMasterTask,
 * SlayerArea, SlayerTaskSublist, SlayerUnlock) and uploads them to the Mystix
 * API once per cache revision.
 *
 * <p>This is global data, identical for every player on the same revision, so
 * the flow is: dump on the client thread, hash, ask the server whether it
 * already has this hash, and upload only when it does not. In practice one
 * player per game update pays the upload for everyone.
 *
 * <p>Rows are enumerated by probing indexed key columns over bounded ranges
 * (the tables key on small integers); misses are cheap cache lookups.
 */
@Slf4j
@Singleton
public class SlayerCatalogMonitor {
	private static final int LOGIN_DUMP_DELAY_SECONDS = 12;
	private static final int MAX_TASK_ID = 512;
	private static final int MAX_MASTER_ID = 32;
	private static final int MAX_AREA_ID = 256;
	private static final int MAX_SUBLIST_ID = 64;
	private static final int MAX_UNLOCK_BIT = 96;

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	/** Hash already confirmed present server-side this session; skip re-checks. */
	private String confirmedHash;
	/** Cache revision whose dump was already confirmed; skips the ~1k table
	 * probes a world hop would otherwise repeat. */
	private int confirmedRevision = -1;

	@Inject
	public SlayerCatalogMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.gson = gson;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		confirmedHash = null;
		confirmedRevision = -1;
	}

	public void forceSync() {
		confirmedHash = null;
		confirmedRevision = -1;
		clientThread.invokeLater(this::dumpAndUpload);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			// Late enough that the cache DB tables are certainly readable, and
			// well behind the state monitors' own login syncs.
			executorService.schedule(() -> clientThread.invokeLater(this::dumpAndUpload),
					LOGIN_DUMP_DELAY_SECONDS, TimeUnit.SECONDS);
		}
		previousGameState = newState;
	}

	/** Dumps the tables and uploads when the server lacks this hash. Client thread only. */
	private void dumpAndUpload() {
		if (!config.syncSlayer() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}
		if (client.getRevision() == confirmedRevision) {
			return;
		}

		Map<String, List<Map<String, Object>>> tables;
		try {
			tables = dumpTables();
		} catch (RuntimeException e) {
			log.warn("Slayer catalog dump failed", e);
			return;
		}
		if (tables.get("slayer_task").isEmpty()) {
			log.debug("Slayer catalog dump produced no tasks; skipping");
			return;
		}

		String tablesJson = gson.toJson(tables);
		String hash = sha256(tablesJson);
		if (hash == null || hash.equals(confirmedHash)) {
			return;
		}
		String revision = String.valueOf(client.getRevision());

		SlayerCatalogPayload payload =
				new SlayerCatalogPayload(playerUsername, revision, hash, tables);
		apiClient.getSlayerCatalogStatus(hash, new MystixApiClient.RoadmapCallback<>() {
			@Override
			public void onSuccess(SlayerCatalogPayload.Status status) {
				confirmedHash = hash;
				confirmedRevision = client.getRevision();
				if (status.isNeeded()) {
					log.debug("Uploading slayer catalog (revision {}, {} tasks)",
							revision, tables.get("slayer_task").size());
					apiClient.sendSlayerCatalog(payload);
				} else {
					log.debug("Slayer catalog {} already known server-side", hash);
				}
			}

			@Override
			public void onError(String message) {
				log.debug("Slayer catalog status check failed: {}", message);
			}
		});
	}

	private Map<String, List<Map<String, Object>>> dumpTables() {
		Map<String, List<Map<String, Object>>> tables = new LinkedHashMap<>();
		tables.put("slayer_task", dumpSlayerTasks());
		tables.put("slayer_master_task", dumpMasterTasks());
		tables.put("slayer_area", dumpAreas());
		tables.put("slayer_task_sublist", dumpSublist());
		tables.put("slayer_unlock", dumpUnlocks());
		return tables;
	}

	private List<Map<String, Object>> dumpSlayerTasks() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int id = 0; id < MAX_TASK_ID; id++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, id)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("id", id);
				out.put("name", firstString(row, DBTableID.SlayerTask.ID,
						DBTableID.SlayerTask.COL_NAME_UPPERCASE));
				out.put("min_combat_level", firstInt(row, DBTableID.SlayerTask.ID,
						DBTableID.SlayerTask.COL_MIN_COMLEVEL));
				rows.add(out);
			}
		}
		return rows;
	}

	private List<Map<String, Object>> dumpMasterTasks() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int masterId = 0; masterId < MAX_MASTER_ID; masterId++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerMasterTask.ID,
					DBTableID.SlayerMasterTask.COL_MASTER_ID, 0, masterId)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("master_id", masterId);
				// COL_TASK is a dbrow reference; dereference to the task's id.
				Integer taskRow = firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_TASK);
				out.put("task_id", taskRow == null ? null
						: firstInt(taskRow, DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID));
				out.put("weight", firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_WEIGHT));
				out.put("min_amount", firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_MIN_AMOUNT));
				out.put("max_amount", firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_MAX_AMOUNT));
				Integer unlockRow = firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_TASK_UNLOCK);
				out.put("unlock_bit", unlockRow == null ? null
						: firstInt(unlockRow, DBTableID.SlayerUnlock.ID, DBTableID.SlayerUnlock.COL_BIT));
				Integer areaRow = firstInt(row, DBTableID.SlayerMasterTask.ID,
						DBTableID.SlayerMasterTask.COL_AREAS);
				List<Integer> areas = new ArrayList<>();
				if (areaRow != null) {
					Integer areaId = firstInt(areaRow, DBTableID.SlayerArea.ID,
							DBTableID.SlayerArea.COL_AREA_ID);
					if (areaId != null) {
						areas.add(areaId);
					}
				}
				out.put("areas", areas);
				rows.add(out);
			}
		}
		return rows;
	}

	private List<Map<String, Object>> dumpAreas() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int areaId = 1; areaId < MAX_AREA_ID; areaId++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("id", areaId);
				out.put("name", firstString(row, DBTableID.SlayerArea.ID,
						DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER));
				rows.add(out);
			}
		}
		return rows;
	}

	private List<Map<String, Object>> dumpSublist() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int sublistId = 1; sublistId < MAX_SUBLIST_ID; sublistId++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerTaskSublist.ID,
					DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, sublistId)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("sublist_id", sublistId);
				Integer taskRow = firstInt(row, DBTableID.SlayerTaskSublist.ID,
						DBTableID.SlayerTaskSublist.COL_TASK);
				out.put("task_id", taskRow == null ? null
						: firstInt(taskRow, DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID));
				out.put("task_name", taskRow == null ? null
						: firstString(taskRow, DBTableID.SlayerTask.ID,
								DBTableID.SlayerTask.COL_NAME_UPPERCASE));
				rows.add(out);
			}
		}
		return rows;
	}

	private List<Map<String, Object>> dumpUnlocks() {
		List<Map<String, Object>> rows = new ArrayList<>();
		for (int bit = 0; bit < MAX_UNLOCK_BIT; bit++) {
			for (int row : client.getDBRowsByValue(
					DBTableID.SlayerUnlock.ID, DBTableID.SlayerUnlock.COL_BIT, 0, bit)) {
				Map<String, Object> out = new LinkedHashMap<>();
				out.put("bit", bit);
				out.put("cost", firstInt(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_COST));
				out.put("name", firstString(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_NAME));
				out.put("description", firstString(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_DESCRIPTION));
				Integer refundable = firstInt(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_REFUNDABLE);
				out.put("refundable", refundable != null && refundable != 0);
				Integer taskRow = firstInt(row, DBTableID.SlayerUnlock.ID,
						DBTableID.SlayerUnlock.COL_RELATED_TASK);
				out.put("task_id", taskRow == null ? null
						: firstInt(taskRow, DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID));
				rows.add(out);
			}
		}
		return rows;
	}

	private Integer firstInt(int row, int table, int column) {
		try {
			Object[] values = client.getDBTableField(row, column, 0);
			if (values != null && values.length > 0 && values[0] instanceof Integer) {
				return (Integer) values[0];
			}
		} catch (RuntimeException e) {
			log.trace("DB field read failed: table={} row={} col={}", table, row, column);
		}
		return null;
	}

	private String firstString(int row, int table, int column) {
		try {
			Object[] values = client.getDBTableField(row, column, 0);
			if (values != null && values.length > 0 && values[0] instanceof String) {
				return (String) values[0];
			}
		} catch (RuntimeException e) {
			log.trace("DB field read failed: table={} row={} col={}", table, row, column);
		}
		return null;
	}

	private static String sha256(String input) {
		try {
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder(hash.length * 2);
			for (byte b : hash) {
				hex.append(String.format("%02x", b));
			}
			return hex.toString();
		} catch (NoSuchAlgorithmException e) {
			return null;
		}
	}
}

package com.mystix;

import com.mystix.model.BankSyncPayload;
import com.mystix.model.DiaryTierResult;
import com.mystix.model.LootSyncPayload;
import com.mystix.model.Roadmap;
import com.mystix.model.RoadmapGoal;
import com.mystix.model.TimerSyncItem;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Bridges game events and the monitors to {@link GoalProgressState}, and turns
 * the state's outbound requests into monitor calls. Registered on the event bus
 * and wired to the monitors' listeners by {@link MystixPlugin}.
 */
@Slf4j
@Singleton
public class GoalProgressTracker implements GoalProgressState.SyncHooks {
	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final PlayerSkillsMonitor playerSkillsMonitor;
	private final LootMonitor lootMonitor;
	private final BankMemoryMonitor bankMemoryMonitor;
	private final RoadmapManager roadmapManager;
	private final GoalCompletionNotifier completionNotifier;
	private final GoalProgressState state;
	/** Storage-item monitors (rune pouch, barrels...) to flush on a local completion; set by the plugin. */
	private volatile Runnable storageSyncNow;

	/** Farming completions are time-based, so re-check every few ticks. */
	private static final int FARMING_CHECK_TICKS = 8;


	@Inject
	public GoalProgressTracker(
			Client client,
			ClientThread clientThread,
			ItemManager itemManager,
			PlayerSkillsMonitor playerSkillsMonitor,
			LootMonitor lootMonitor,
			BankMemoryMonitor bankMemoryMonitor,
			RoadmapManager roadmapManager,
			GoalCompletionNotifier completionNotifier) {
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.playerSkillsMonitor = playerSkillsMonitor;
		this.lootMonitor = lootMonitor;
		this.bankMemoryMonitor = bankMemoryMonitor;
		this.roadmapManager = roadmapManager;
		this.completionNotifier = completionNotifier;
		this.state = new GoalProgressState(this);
	}

	public void setStorageSyncNow(Runnable storageSyncNow) {
		this.storageSyncNow = storageSyncNow;
	}

	// ---------------------------------------------------------- game events

	@Subscribe
	public void onStatChanged(StatChanged event) {
		state.onSkillXp(event.getSkill().getName(), event.getXp());
	}

	/** Inventory and equipment changes keep owned-item goals exact between bank
	 * visits: cutting or picking up raises them, dropping lowers them. */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		boolean equipment;
		if (event.getContainerId() == InventoryID.INV) {
			equipment = false;
		} else if (event.getContainerId() == InventoryID.WORN) {
			equipment = true;
		} else {
			return;
		}
		ItemContainer container = event.getItemContainer();
		Map<Integer, Integer> quantities = new HashMap<>();
		if (container != null) {
			for (Item item : container.getItems()) {
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) {
					continue;
				}
				quantities.merge(canonicalItemId(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		state.onInventoryChanged(equipment, quantities);
	}

	/** A bank upload was built: its bank section (and any deposit-box deposits)
	 * become this session's snapshots for those sources (ids folded onto the
	 * unnoted item). Inventory is tracked live from container events. */
	public void onBankPayload(BankSyncPayload payload) {
		if (payload == null) {
			return;
		}
		for (Map.Entry<String, List<BankSyncPayload.BankItem>> e : payload.getItems().entrySet()) {
			if (BankMemoryMonitor.SOURCE_INVENTORY.equals(e.getKey()) || e.getValue() == null) {
				continue;
			}
			Map<Integer, Integer> quantities = new HashMap<>();
			for (BankSyncPayload.BankItem item : e.getValue()) {
				quantities.merge(canonicalItemId(item.getItemId()), item.getQuantity(), Integer::sum);
			}
			state.onContainerSnapshot(e.getKey(), quantities);
		}
	}

	/**
	 * A storage container that syncs as its own bank-memory source (seed vault,
	 * looting bag, a boat's cargo hold, the fish barrel ledger...) was read:
	 * its contents become this session's snapshot for that source, so moving
	 * items into it no longer reads as a loss. Client thread.
	 */
	public void onContainerSnapshot(String source, Map<Integer, Integer> quantities) {
		Map<Integer, Integer> canonical = new HashMap<>();
		if (quantities != null) {
			for (Map.Entry<Integer, Integer> e : quantities.entrySet()) {
				if (e.getKey() == null || e.getValue() == null || e.getValue() <= 0) {
					continue;
				}
				canonical.merge(canonicalItemId(e.getKey()), e.getValue(), Integer::sum);
			}
		}
		state.onContainerSnapshot(source, canonical);
	}

	/** Noted items map to their unnoted item id (client thread). */
	private int canonicalItemId(int itemId) {
		ItemComposition composition = itemManager.getItemComposition(itemId);
		if (composition != null && composition.getNote() != -1) {
			return composition.getLinkedNoteId();
		}
		return itemId;
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		state.settleOwned();
		if (client.getTickCount() % FARMING_CHECK_TICKS == 0) {
			state.checkFarming(System.currentTimeMillis());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (endsSession(event.getGameState())) {
			state.resetSession();
		}
	}

	/**
	 * Only a real logout ends the local session. Region loads, world hops and
	 * brief connection drops pass through LOADING / HOPPING / CONNECTION_LOST on
	 * the way back to LOGGED_IN with the player's XP, inventory and kills intact,
	 * so treating them as a logout would wipe progress made since the last
	 * server read (a goal completed seconds before a teleport, for example).
	 */
	static boolean endsSession(GameState newState) {
		return newState == GameState.LOGIN_SCREEN
				|| newState == GameState.LOGIN_SCREEN_AUTHENTICATOR;
	}

	// ------------------------------------------------ monitor / manager feeds

	public void onServerRoadmap(Roadmap roadmap) {
		state.onServerRoadmap(roadmap);
		if (roadmap != null) {
			resolveNpcNames(roadmap);
		}
	}

	/** The player's current set of roadmaps; any others are forgotten. */
	public void retainRoadmaps(Set<Integer> collectionIds) {
		state.retainRoadmaps(collectionIds);
	}

	/**
	 * Kill-count goals carry one canonical NPC id, but many NPCs (guards, for
	 * example) have several in-game ids sharing a name. The server sends the
	 * canonical name; for older responses without it, resolve the id to a name
	 * on the client thread as a fallback (multi-form NPCs resolve to "null").
	 */
	private void resolveNpcNames(Roadmap roadmap) {
		clientThread.invokeLater(() -> {
			for (RoadmapGoal goal : roadmap.getGoals()) {
				Integer npcId = goal.getNpcId();
				if (npcId == null || goal.getNpcName() != null) {
					continue; // the server already told us the canonical name
				}
				NPCComposition composition = client.getNpcDefinition(npcId);
				String name = composition == null ? null : composition.getName();
				log.debug("Goal {} npc {} resolves to name '{}'", goal.getId(), npcId, name);
				if (name != null && !"null".equals(name)) {
					state.setNpcName(goal.getId(), name);
				}
			}
		});
	}

	public void onSkillsUploaded(Map<String, Integer> xpBySkillName) {
		state.onSkillsUploaded(xpBySkillName);
	}

	public void onLootDrop(int npcId, String npcName, int kills, List<LootSyncPayload.LootItem> items) {
		log.debug("Goal progress: loot drop npc {} '{}' x{}", npcId, npcName, kills);
		state.onLootDrop(npcId, npcName, kills, items);
	}

	public void onCollectionLogItemObtained(int itemId, int quantity) {
		state.onCollectionLogItemObtained(itemId, quantity);
	}

	public void onSourceSynced(SyncSource source) {
		state.onSourceSynced(source);
	}

	public void onQuestStates(Map<String, Integer> statusByQuestName) {
		state.onQuestStates(statusByQuestName);
	}

	public void onDiaryRead(Map<String, Map<String, DiaryTierResult>> diaries) {
		state.onDiaryRead(diaries);
	}

	public void onCombatTasksCompleted(List<Integer> taskIds) {
		state.onCombatTasksCompleted(taskIds);
	}

	public void onFarmingTimers(List<TimerSyncItem> timers) {
		state.onFarmingTimers(timers, System.currentTimeMillis());
	}

	public void clear() {
		state.clearAll();
	}

	/** What the server last held in a bank-memory source for each in-progress owned goal's item. */
	public Map<Integer, Integer> serverHeldFor(String source) {
		return state.serverHeldFor(source);
	}

	/** Item ids of owned-item goals still in progress: the sources holding them upload on the short debounce. */
	public Set<Integer> ownedGoalItemIds() {
		return state.ownedGoalItemIds();
	}

	// ----------------------------------------------------------------- reads

	public GoalProgressView progressFor(RoadmapGoal goal) {
		return state.progressFor(goal);
	}

	public boolean isComplete(RoadmapGoal goal) {
		return state.isComplete(goal);
	}

	/** True when the goal's completion was first seen this session (it lingers in the tree). */
	public boolean completedThisSession(RoadmapGoal goal) {
		return goal != null && state.completedThisSession(goal.getId());
	}

	/** The first goal in sort order the plugin does not consider complete. */
	public RoadmapGoal firstIncompleteGoal(Roadmap roadmap) {
		if (roadmap == null) {
			return null;
		}
		for (RoadmapGoal goal : roadmap.getGoalsSorted()) {
			if (!isComplete(goal)) {
				return goal;
			}
		}
		return null;
	}

	// ------------------------------------------------------------- SyncHooks

	@Override
	public void forceSkillsSync() {
		playerSkillsMonitor.forceSync();
	}

	@Override
	public void flushLootDrops() {
		lootMonitor.flushDropsNow();
	}

	@Override
	public void forceBankSync() {
		// Inventory and gear (plus the bank when it was opened this session) so
		// the server can confirm without waiting for a bank visit.
		bankMemoryMonitor.syncInventoryNow();
		Runnable storage = storageSyncNow;
		if (storage != null) {
			storage.run();
		}
	}

	@Override
	public void requestReconcile(int delaySeconds) {
		roadmapManager.requestReconcile(delaySeconds);
	}

	@Override
	public void goalCompleted(RoadmapGoal goal, Roadmap roadmap) {
		log.debug("Roadmap goal completed: {}", goal.getName());
		int total = 0;
		int done = 0;
		if (roadmap != null) {
			for (RoadmapGoal g : roadmap.getGoals()) {
				total++;
				// The just-completed goal is already marked complete in the state.
				if (isComplete(g)) {
					done++;
				}
			}
			// A completion in another roadmap makes that roadmap the active one.
			roadmapManager.selectRoadmap(roadmap);
		}
		completionNotifier.show(goal, roadmap == null ? null : roadmap.getTitle(), done, total);
		// Move the goal into the panel's Completed section right away.
		roadmapManager.notifyPanel();
	}
}

package com.mystix;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BiFunction;

/**
 * Reads the storage state the community "Charges Improved" plugin
 * (config group {@code tictac7x-charges}) keeps for the same storage items
 * we infer. When a player runs it, its state is exact and battle-tested,
 * so it overrides our own inference: read once at login and again on every
 * change it writes. Read-only: the plugin hub forbids writing to another
 * plugin's config group.
 */
final class ChargesPluginBridge {
	static final String CONFIG_GROUP = "tictac7x-charges";
	static final String STORAGE_SUFFIX = "_storage";

	/** Their config key (without the suffix) to our bank-memory source. Several keys fold into one source. */
	static final Map<String, String> SOURCE_BY_KEY;

	static {
		Map<String, String> m = new LinkedHashMap<>();
		m.put("fish_barrel", "fish_barrel");
		m.put("herb_sack", "herb_sack");
		m.put("silklined_herb_sack", "herb_sack");
		m.put("log_basket", "log_basket");
		m.put("forestry_basket", "log_basket");
		m.put("gem_bag", "gem_bag");
		m.put("gem_pouch", "gem_bag");
		m.put("gem_satchel", "gem_bag");
		m.put("gem_tote", "gem_bag");
		m.put("gem_sack", "gem_bag");
		m.put("coal_bag", "coal_bag");
		SOURCE_BY_KEY = Collections.unmodifiableMap(m);
	}

	private ChargesPluginBridge() {
	}

	/** Our source for one of their config keys ({@code fish_barrel_storage}), or null when not one we mirror. */
	static String sourceForConfigKey(String key) {
		if (key == null || !key.endsWith(STORAGE_SUFFIX)) {
			return null;
		}
		return SOURCE_BY_KEY.get(key.substring(0, key.length() - STORAGE_SUFFIX.length()));
	}

	/** Their JSON ({@code [{"itemId":13439,"quantity":5}]}) to item id to quantity; null when absent or malformed. */
	static Map<Integer, Integer> parse(String json) {
		if (json == null || json.isBlank()) {
			return null;
		}
		try {
			JsonElement root = new JsonParser().parse(json);
			if (!root.isJsonArray()) {
				return null;
			}
			Map<Integer, Integer> contents = new LinkedHashMap<>();
			for (JsonElement e : (JsonArray) root) {
				if (!e.isJsonObject()) {
					continue;
				}
				JsonObject o = e.getAsJsonObject();
				if (!o.has("itemId") || !o.has("quantity")) {
					continue;
				}
				int qty = o.get("quantity").getAsInt();
				if (qty > 0) {
					contents.merge(o.get("itemId").getAsInt(), qty, Integer::sum);
				}
			}
			return contents;
		} catch (RuntimeException ex) {
			return null;
		}
	}

	/**
	 * Every mirrored source's contents as their plugin has them, summing the
	 * keys that fold into one source. Sources with no stored value at all are
	 * left out (their plugin is not installed, or never tracked that item).
	 */
	static Map<String, Map<Integer, Integer>> readAll(BiFunction<String, String, String> config) {
		Map<String, Map<Integer, Integer>> bySource = new LinkedHashMap<>();
		for (Map.Entry<String, String> e : SOURCE_BY_KEY.entrySet()) {
			Map<Integer, Integer> contents = parse(config.apply(CONFIG_GROUP, e.getKey() + STORAGE_SUFFIX));
			if (contents == null) {
				continue;
			}
			Map<Integer, Integer> merged = bySource.computeIfAbsent(e.getValue(), s -> new LinkedHashMap<>());
			contents.forEach((id, qty) -> merged.merge(id, qty, Integer::sum));
		}
		return bySource;
	}

	/** The config keys that fold into a source. */
	static List<String> keysFor(String source) {
		List<String> keys = new java.util.ArrayList<>();
		for (Map.Entry<String, String> e : SOURCE_BY_KEY.entrySet()) {
			if (e.getValue().equals(source)) {
				keys.add(e.getKey() + STORAGE_SUFFIX);
			}
		}
		return keys;
	}
}

package com.mystix.model;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Payload for syncing Managing Miscellania state to the Mystix API.
 * Matches the format expected by POST /api/runelite/kingdom/
 *
 * <p>Carries the raw kingdom varbits (approval points out of 127, coffer coins,
 * subjects per labour and the three allocation choice values); the backend owns
 * the decoding and the daily decay maths so a correction never needs a plugin
 * release. There is no client timestamp: the server stamps receipt time, which
 * keeps the client-side dedupe effective.
 */
public class KingdomSyncPayload {
	private final String player_username;
	private final boolean in_kingdom;
	private final boolean throne_completed;
	private final boolean royal_trouble_completed;
	private final int approval_points;
	private final int coffer;
	private final int workers_wood;
	private final int workers_herb;
	private final int workers_fish;
	private final int workers_mine;
	private final int workers_rarewood;
	private final int workers_farm;
	private final int cooked_fish;
	private final int rarewood_type;
	private final int herbs_or_flax;
	private final Map<String, Integer> extra;

	public KingdomSyncPayload(
			String playerUsername,
			boolean inKingdom,
			boolean throneCompleted,
			boolean royalTroubleCompleted,
			int approvalPoints,
			int coffer,
			int workersWood,
			int workersHerb,
			int workersFish,
			int workersMine,
			int workersRarewood,
			int workersFarm,
			int cookedFish,
			int rarewoodType,
			int herbsOrFlax,
			Map<String, Integer> extra) {
		this.player_username = playerUsername;
		this.in_kingdom = inKingdom;
		this.throne_completed = throneCompleted;
		this.royal_trouble_completed = royalTroubleCompleted;
		this.approval_points = approvalPoints;
		this.coffer = coffer;
		this.workers_wood = workersWood;
		this.workers_herb = workersHerb;
		this.workers_fish = workersFish;
		this.workers_mine = workersMine;
		this.workers_rarewood = workersRarewood;
		this.workers_farm = workersFarm;
		this.cooked_fish = cookedFish;
		this.rarewood_type = rarewoodType;
		this.herbs_or_flax = herbsOrFlax;
		this.extra = extra == null ? Collections.emptyMap() : new LinkedHashMap<>(extra);
	}

	public String getPlayerUsername() {
		return player_username;
	}

	public boolean isInKingdom() {
		return in_kingdom;
	}

	public boolean isThroneCompleted() {
		return throne_completed;
	}

	public boolean isRoyalTroubleCompleted() {
		return royal_trouble_completed;
	}

	public int getApprovalPoints() {
		return approval_points;
	}

	public int getCoffer() {
		return coffer;
	}

	public int getWorkersWood() {
		return workers_wood;
	}

	public int getWorkersHerb() {
		return workers_herb;
	}

	public int getWorkersFish() {
		return workers_fish;
	}

	public int getWorkersMine() {
		return workers_mine;
	}

	public int getWorkersRarewood() {
		return workers_rarewood;
	}

	public int getWorkersFarm() {
		return workers_farm;
	}

	public int getCookedFish() {
		return cooked_fish;
	}

	public int getRarewoodType() {
		return rarewood_type;
	}

	public int getHerbsOrFlax() {
		return herbs_or_flax;
	}

	public Map<String, Integer> getExtra() {
		return Collections.unmodifiableMap(extra);
	}

	public String toJson(Gson gson) {
		return gson.toJson(this);
	}
}

package com.mystix.model;

import com.google.gson.Gson;
import java.util.Map;

/**
 * Payload for syncing quest states to the Mystix API.
 * Matches the format expected by POST /api/runelite/quests/
 *
 * Mirrors the WikiSync quests shape so the backend reuses the existing
 * processor: a {questName: status} map where status is 0 = not started,
 * 1 = in progress, 2 = completed.
 */
public class QuestsSyncPayload {
	private final String player_username;
	private final Map<String, Integer> quests;

	public QuestsSyncPayload(String playerUsername, Map<String, Integer> quests) {
		this.player_username = playerUsername;
		this.quests = quests;
	}

	public String getPlayerUsername() {
		return player_username;
	}

	public Map<String, Integer> getQuests() {
