	 * Serialize the timers list to JSON for the sync endpoint.
	 */
	public static String toJson(List<TimerSyncItem> timers)
	{
		StringBuilder sb = new StringBuilder("{\"timers\":[");
		for (int i = 0; i < timers.size(); i++)
		{
			if (i > 0)
			{
				sb.append(",");
