import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Monitors vault and storage containers the client exposes as real item
 * containers (Seed Vault, Looting Bag, Sailing cargo holds, seed box, ...)
 * and syncs their contents to the Mystix API using the bank sync endpoint
 * with a per-source key. Every read is also handed to the goal tracker so
 * owned-item goals do not count a deposit as a loss.
 */
@Slf4j
@Singleton
public class VaultMonitor {
	/** Container id to bank-sync source. Each container is its own source:
	 * the backend replaces a whole source per upload and the plugin can only
	 * snapshot a container it has seen, so two containers must not share one. */
	private static final Map<Integer, String> VAULT_SOURCES;

	static {
		Map<Integer, String> m = new HashMap<>();
		m.put(InventoryID.SEED_VAULT, "seed_vault");
		m.put(InventoryID.LOOTING_BAG, "looting_bag");
		m.put(InventoryID.SAILING_BOAT_1_CARGOHOLD, "boat_cargo_hold_1");
		m.put(InventoryID.SAILING_BOAT_2_CARGOHOLD, "boat_cargo_hold_2");
		m.put(InventoryID.SAILING_BOAT_3_CARGOHOLD, "boat_cargo_hold_3");
		m.put(InventoryID.SAILING_BOAT_4_CARGOHOLD, "boat_cargo_hold_4");
		m.put(InventoryID.SAILING_BOAT_5_CARGOHOLD, "boat_cargo_hold_5");
		m.put(InventoryID.SAILING_TRAWLING_NET, "trawling_net");
		m.put(InventoryID.SEED_BOX, "seed_box");
		m.put(InventoryID.TACKLE_BOX, "tackle_box");
		m.put(InventoryID.FORESTRY_KIT, "forestry_kit");
		m.put(InventoryID.HUNTSMANS_KIT, "huntsmans_kit");
		VAULT_SOURCES = Collections.unmodifiableMap(m);
	}

	/** Set on container ids the client reports for interface-owned inventories (a boat's hold arrives as 965 | 0x8000). */
	static final int REMOTE_CONTAINER_FLAG = 0x8000;

	/** The bank-sync source for a container id, or null when not tracked. */
	static String sourceFor(int containerId) {
		String source = VAULT_SOURCES.get(containerId);
		if (source == null && (containerId & REMOTE_CONTAINER_FLAG) != 0) {
			source = VAULT_SOURCES.get(containerId & ~REMOTE_CONTAINER_FLAG);
		}
		return source;
	}

	/** Crew member option that banks the current boat's hold without any container event reaching the client. */
	static final String BANK_CARGO_OPTION = "Bank-cargo";

	private final Client client;
	private final ItemManager itemManager;
	private final SourceSyncer syncer;
	private GameState previousGameState = GameState.UNKNOWN;
	/** Contents last read this session, per source. */
	private final Map<String, Map<Integer, Integer>> lastRead = new HashMap<>();
	/** Receives the hold's contents when a crew member banks them; set by the plugin. */
	private volatile Consumer<Map<Integer, Integer>> cargoBankedListener;

	public void setCargoBankedListener(Consumer<Map<Integer, Integer>> listener) {
		this.cargoBankedListener = listener;
	}

	/** Receives every container read (source, canonical item id to quantity),
	 * before any sync gate, so goal progress moves even with sync disabled. */
	private volatile BiConsumer<String, Map<Integer, Integer>> snapshotListener;

	public void setSnapshotListener(BiConsumer<String, Map<Integer, Integer>> listener) {
		this.snapshotListener = listener;
	}

	@Inject
	public VaultMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			ItemManager itemManager,
			Gson gson,
			ScheduledExecutorService executor) {
		this.client = client;
		this.itemManager = itemManager;
		this.syncer = new SourceSyncer("vaults", gson, executor,
				() -> config.syncBankMemory() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client),
				() -> SyncGuard.getPlayerUsername(client),
				apiClient::sendBankSync);
	}

	/** Item ids active owned-item goals are counting (short debounce for them); set by the plugin. */
	public void setGoalItems(Supplier<Set<Integer>> goalItems) {
		syncer.setGoalItems(goalItems);
	}

	public void stop() {
		syncer.stop();
		lastRead.clear();
	}

	/** The source of the current boat's hold, from the Sailing varp holding its inventory id, or null. */
	static String currentHoldSource(int holdInventoryId) {
		String source = sourceFor(holdInventoryId);
		return source != null && source.startsWith("boat_cargo_hold_") ? source : null;
	}

	/**
	 * "Bank-cargo" on a crew member moves the hold into the bank with no
	 * container event, so the bank would count the items again on its next
	 * read while the hold snapshot still held them. Hand the hold's contents
	 * to the bank-deposits overlay (cleared when the bank is read) and empty
	 * the hold locally and on the server.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (!BANK_CARGO_OPTION.equalsIgnoreCase(event.getMenuOption())) {
			return;
		}
		String current = currentHoldSource(client.getVarpValue(VarPlayerID.SAILING_BOAT_CARGOHOLD_INV));
		Map<Integer, Integer> banked = new LinkedHashMap<>();
		Map<String, Map<Integer, Integer>> emptied = new LinkedHashMap<>();
		for (Map.Entry<String, Map<Integer, Integer>> e : lastRead.entrySet()) {
			boolean hold = e.getKey().startsWith("boat_cargo_hold_");
			if (!hold || e.getValue().isEmpty() || (current != null && !current.equals(e.getKey()))) {
				continue;
			}
			e.getValue().forEach((id, qty) -> banked.merge(id, qty, Integer::sum));
			emptied.put(e.getKey(), new LinkedHashMap<>());
		}
		log.debug("Bank-cargo: current hold {} -> banking {} from {}", current, banked, emptied.keySet());
		if (emptied.isEmpty()) {
			return;
		}
		BiConsumer<String, Map<Integer, Integer>> listener = snapshotListener;
		for (String source : emptied.keySet()) {
			lastRead.put(source, new LinkedHashMap<>());
			if (listener != null) {
				listener.accept(source, new LinkedHashMap<>());
			}
		}
		Consumer<Map<Integer, Integer>> bankedListener = cargoBankedListener;
		if (bankedListener != null) {
			bankedListener.accept(banked);
		}
		syncer.submitSources(emptied, true);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (SyncGuard.isLogout(previousGameState, newState)) {
			syncer.flushPending();
		}
		previousGameState = newState;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		String source = sourceFor(event.getContainerId());
		if (source == null) {
			return;
		}
		ItemContainer container = client.getItemContainer(event.getContainerId());
		if (container == null) {
			return;
		}

		Map<Integer, Integer> itemQuantities = new LinkedHashMap<>();
		ItemCollector.collectItems(container, itemManager, itemQuantities);
		log.debug("Container {} ({}) read: {} distinct items", event.getContainerId(), source, itemQuantities.size());
		lastRead.put(source, new LinkedHashMap<>(itemQuantities));

		BiConsumer<String, Map<Integer, Integer>> listener = snapshotListener;
		if (listener != null) {
			listener.accept(source, itemQuantities);
		}

		Map<String, Map<Integer, Integer>> bySource = new LinkedHashMap<>();
		bySource.put(source, itemQuantities);
		syncer.submitSources(bySource, false);
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.SlayerRewardsPayload;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Scrapes the Slayer Rewards task list interface when the player opens it and
 * syncs the rows to the Mystix API.
 *
 * <p>The game renders, per task: the name with its amount range, a status icon
 * (available / cannot assign / blocked / current task), and the assignment
 * percentage the game itself computed for THIS player's blocks, unlocks and
 * levels. That percentage is data no varp exposes, and it is the calibration
 * source for Mystix's task-probability engine, so this is worth capturing
 * every time the interface opens. Opportunistic by nature: it only fires when
 * the player visits the rewards screen.
 *
 * <p>Each row is a run of four consecutive children in the DRAWABLE layer:
 * name text (type 4), spacer (type 3), status sprite (type 5), percent text
 * (type 4). Status is read from the sprite id, never from colours.
 */
@Slf4j
@Singleton
public class SlayerRewardsMonitor {
	/** "Aberrant Spectres (130-200)" -> name, min, max. */
	private static final Pattern NAME_WITH_RANGE =
			Pattern.compile("^(.*?)\\s*\\((\\d+)\\s*-\\s*(\\d+)\\)\\s*$");
	private static final Pattern PERCENT = Pattern.compile("^([\\d.]+)%$");

	private static final int TYPE_TEXT = 4;
	private static final int TYPE_SPACER = 3;
	private static final int TYPE_SPRITE = 5;

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final Gson gson;

	/** Minimum interval between scrape posts even when content changed. */
	private static final long MIN_SCRAPE_INTERVAL_MS = 10_000L;

	/**
	 * Dedupe key of the last sent scrape: rows + master only. The payload's
	 * captured_at is stamped per build, so comparing full payload JSON would
	 * never match and every tab toggle in the rewards UI would post a full
	 * snapshot.
	 */
	private String lastContentKey;
	private long lastScrapeSentMs;

	@Inject
	public SlayerRewardsMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.gson = gson;
	}

	public void stop() {
		lastContentKey = null;
		lastScrapeSentMs = 0;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		if (event.getGroupId() != InterfaceID.SLAYER_REWARDS_TASK_LIST) {
			return;
		}
		// Children populate as the interface finishes loading; read next cycle.
		clientThread.invokeLater(this::scrapeAndSync);
	}

	/** Reads the task list rows and syncs them. Client thread only. */
	private void scrapeAndSync() {
		if (!config.syncSlayer() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		Widget drawable = client.getWidget(InterfaceID.SlayerRewardsTaskList.DRAWABLE);
		if (drawable == null) {
			return;
		}
		Widget[] children = drawable.getDynamicChildren();
		if (children == null || children.length < 4) {
			return;
		}

		List<SlayerRewardsPayload.Row> rows = new ArrayList<>();
		for (int i = 0; i + 3 < children.length; i++) {
			if (!isTaskRow(children, i)) {
				continue;
			}
			SlayerRewardsPayload.Row row = parseRow(
					children[i].getText(),
					children[i + 2].getSpriteId(),
					children[i + 3].getText());
			if (row != null) {
				rows.add(row);
				i += 3;
			}
		}
		if (rows.isEmpty()) {
			log.debug("Slayer rewards scrape found no task rows");
			return;
		}

		int masterId = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		String contentKey = masterId + "|" + gson.toJson(rows);
		if (contentKey.equals(lastContentKey)) {
			log.debug("Slayer rewards scrape unchanged, skipping sync");
			return;
		}
		long nowMs = System.currentTimeMillis();
		if (nowMs - lastScrapeSentMs < MIN_SCRAPE_INTERVAL_MS) {
			log.debug("Slayer rewards scrape throttled");
			return;
		}
		SlayerRewardsPayload payload = new SlayerRewardsPayload(
				playerUsername,
				masterId == 0 ? null : masterId,
				rows,
				Instant.now().toString());
		lastContentKey = contentKey;
		lastScrapeSentMs = nowMs;
		log.debug("Syncing slayer rewards scrape: {} rows for player: {}",
				rows.size(), playerUsername);
		apiClient.sendSlayerRewards(payload);
	}

	private static boolean isTaskRow(Widget[] children, int i) {
		return children[i].getType() == TYPE_TEXT && children[i].getText() != null
				&& children[i + 1].getType() == TYPE_SPACER
				&& children[i + 2].getType() == TYPE_SPRITE
				&& children[i + 3].getType() == TYPE_TEXT && children[i + 3].getText() != null;
	}

	/** Parses one widget row; package-private for tests. Returns null on mismatch. */
	static SlayerRewardsPayload.Row parseRow(String nameText, int spriteId, String percentText) {
		if (nameText == null || percentText == null) {
			return null;
		}
		Matcher percentMatcher = PERCENT.matcher(Text.removeTags(percentText).trim());
		if (!percentMatcher.matches()) {
			return null;
		}
		double percent;
		try {
			percent = Double.parseDouble(percentMatcher.group(1));
		} catch (NumberFormatException e) {
			return null;
		}

		String name = Text.removeTags(nameText).trim();
		Integer amountMin = null;
		Integer amountMax = null;
		Matcher nameMatcher = NAME_WITH_RANGE.matcher(name);
		if (nameMatcher.matches()) {
			name = nameMatcher.group(1).trim();
			amountMin = Integer.valueOf(nameMatcher.group(2));
			amountMax = Integer.valueOf(nameMatcher.group(3));
		}
		if (name.isEmpty()) {
			return null;
		}
		return new SlayerRewardsPayload.Row(name, amountMin, amountMax, percent, spriteId);
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.CombatAchievementsSyncPayload;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.function.Consumer;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's completed combat achievements and syncs them to the Mystix API.
 *
 * <p>Combat achievement completion is stored in a fixed set of VarPlayers (the same source
 * WikiSync reads), each a 32-bit field. A task is completed iff its bit is set, where
 * {@code taskId = 32 * varpIndex + bitPosition}. Decoding these varps reproduces the exact
 * task-id list WikiSync's server derives, so the backend consumes the payload unchanged as a
 * flat {@code combat_achievements: [taskId, ...]} list.
 *
 * <p>Triggers: a sync on login (after a short delay so the CA varps have loaded) and on
 * logout, plus a near-real-time sync when a combat achievement completes. Completion flips one
 * of the CA varps, so we mark a re-check on the matching {@link VarbitChanged} and read+dedupe
 * on the next {@link GameTick} (throttled), which collapses churn to at most one read per few
 * ticks. A JSON equality check means an unchanged CA set is never resent.
 */
@Slf4j
@Singleton
public class CombatAchievementMonitor {
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	// Minimum ticks between varp-driven reads, so any varp churn doesn't re-read every
	// tick. A CA completion still syncs within a few ticks, and login/logout syncs are
	// the safety net.
	private static final int RESYNC_THROTTLE_TICKS = 3;

	// The VarPlayers holding combat achievement completion bits, in the order that defines
	// task ids (taskId = 32 * index + bit). Mirrors WikiSync's combatAchievementVarps list;
	// order matters, so this is kept as an ordered array and must not be reordered.
	private static final int[] COMBAT_ACHIEVEMENT_VARPS = {
			3116, 3117, 3118, 3119, 3120, 3121, 3122, 3123, 3124, 3125,
			3126, 3127, 3128, 3387, 3718, 3773, 3774, 4204, 4496, 4721,
			5673};
	// Membership set for the VarbitChanged filter, so we only re-check on CA varp changes.
	private static final Set<Integer> COMBAT_ACHIEVEMENT_VARP_SET = new HashSet<>();

	static {
		for (int varp : COMBAT_ACHIEVEMENT_VARPS) {
			COMBAT_ACHIEVEMENT_VARP_SET.add(varp);
		}
	}

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean caCheckPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public CombatAchievementMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.gson = gson;
	}

	/** Receives every read of the completed in-game task ids; set by the plugin. */
	private volatile Consumer<List<Integer>> completedListener;

	public void setCompletedListener(Consumer<List<Integer>> listener) {
		this.completedListener = listener;
	}

	/** Invoked after each upload so roadmap progress can be re-read; set by the plugin. */
	private volatile Runnable syncedListener;

	public void setSyncedListener(Runnable listener) {
		this.syncedListener = listener;
	}

	private void notifySynced() {
		Runnable listener = syncedListener;
		if (listener != null) {
			listener.run();
		}
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		caCheckPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the current combat achievements on the client thread. Used by
	 * the roadmap panel's "Sync &amp; refresh"; clears the dedup cache so an unchanged set
	 * still sends.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncCombatAchievements();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			// CA varps load shortly after LOGGED_IN, so wait before reading.
			executorService.schedule(() -> clientThread.invokeLater(this::syncCombatAchievements),
					LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			// Logging out: flush final state (this handler runs on the client thread).
			syncCombatAchievements();
		}
		previousGameState = newState;
	}

	/** A CA completion flips one of the CA varps; mark a re-check for the next game tick. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (COMBAT_ACHIEVEMENT_VARP_SET.contains(event.getVarpId())) {
			caCheckPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (!caCheckPending) {
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
			return;
		}
		caCheckPending = false;
		lastReadTick = client.getTickCount();
		syncCombatAchievements();
	}

	/** Reads all completed CAs, builds the payload, and syncs (deduped). Client thread only. */
	private void syncCombatAchievements() {
		if (!config.syncCombatAchievements() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		// Ascending (index, bit) order gives a stable JSON ordering so the dedup check is
		// reliable.
		List<Integer> completed = new ArrayList<>();
		for (int index = 0; index < COMBAT_ACHIEVEMENT_VARPS.length; index++) {
			int value = client.getVarpValue(COMBAT_ACHIEVEMENT_VARPS[index]);
			for (int bit = 0; bit < 32; bit++) {
				if ((value & (1 << bit)) != 0) {
					completed.add(32 * index + bit);
				}
			}
		}

		Consumer<List<Integer>> listener = completedListener;
		if (listener != null) {
			listener.accept(completed);
		}

		CombatAchievementsSyncPayload payload =
				new CombatAchievementsSyncPayload(playerUsername, completed);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Combat achievements unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing {} combat achievements for player: {}", completed.size(), playerUsername);
		apiClient.sendCombatAchievementsSync(payload);
		notifySynced();
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.KingdomSyncPayload;
import java.util.Collections;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Syncs Managing Miscellania state (approval, coffer, subject allocation and the two
 * kingdom quests) so Mystix can warn when the coffer runs low or approval decays.
 *
 * <p>The kingdom varbits are part of the varp block every logged-in client receives, so
 * they are readable anywhere, not only on the islands. Read timing reuses
 * {@link DiarySyncTrigger}: the first read waits for the post-login replay to settle (a
 * mid-replay read could report a prior account's values), later changes resync a few
 * ticks after their {@link VarbitChanged}, and the final state is flushed on logout.
 * Walking onto the islands also triggers a resync so the backend can record the visit
 * (collection and wages pause after 30 days without one). Nothing is sent before Throne
 * of Miscellania is finished, and an approval read of 0 (impossible after the quest, the
 * floor is 25%) is treated as not loaded yet.
 */
@Slf4j
@Singleton
public class KingdomMonitor {
	/** Miscellania and Etceteria. */
	static final Set<Integer> KINGDOM_REGIONS = Collections.unmodifiableSet(
			new HashSet<>(java.util.Arrays.asList(10044, 10300)));

	/**
	 * Accumulated resource pool (not yet in the gameval constants of the RuneLite version
	 * we build against). Forwarded raw under {@code extra} until its meaning is confirmed.
	 */
	static final int RESTOTAL_LOWBITS_VARBIT = 11564;
	static final String EXTRA_RESTOTAL_LOWBITS = "restotal_lowbits";

	private static final Set<Integer> KINGDOM_VARBITS = Collections.unmodifiableSet(
			new HashSet<>(java.util.Arrays.asList(
					VarbitID.MISC_APPROVAL,
					VarbitID.MISC_COFFERS,
					VarbitID.MISC_POINTS_WOOD,
					VarbitID.MISC_POINTS_HERB,
					VarbitID.MISC_POINTS_FISH,
					VarbitID.MISC_POINTS_MINE,
					VarbitID.MISC_POINTS_RAREWOOD,
					VarbitID.MISC_POINTS_FARM,
					VarbitID.MISC_COOKED,
					VarbitID.MISC_RAREWOOD_TYPE,
					VarbitID.MISC_HERBS_OR_FLAX,
					RESTOTAL_LOWBITS_VARBIT)));

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final Gson gson;
	private final DiarySyncTrigger trigger = new DiarySyncTrigger();

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean wasInKingdom;
	private String lastSyncJson;

	@Inject
	public KingdomMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.gson = gson;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		wasInKingdom = false;
		trigger.reset();
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the kingdom state on the client thread (the panel's
	 * "Sync &amp; refresh"); clears the dedup so an unchanged value still sends. No-op until
	 * the session has settled, so it can never sample the post-login replay window.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			if (client.getGameState() != GameState.LOGGED_IN || !trigger.isBaselineSynced()) {
				return;
			}
			lastSyncJson = null;
			syncKingdom();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		boolean wasLoggedIn = previousGameState == GameState.LOGGED_IN;
		boolean nowLoggedIn = newState == GameState.LOGGED_IN;
		if (wasLoggedIn && !nowLoggedIn) {
			if (trigger.leaveAndShouldFlush()) {
				syncKingdom();
			}
			// Every login re-sends once so the server's capture time stays fresh even
			// when nothing changed.
			lastSyncJson = null;
			wasInKingdom = false;
		}
		previousGameState = newState;
	}

	/** Only the kingdom varbits matter here; every other change is ignored. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (KINGDOM_VARBITS.contains(event.getVarbitId())) {
			trigger.varbitChanged();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		boolean inKingdom = loggedIn && isInKingdom();
		if (inKingdom && !wasInKingdom) {
			trigger.varbitChanged();
		}
		wasInKingdom = inKingdom;
		if (trigger.tick(client.getTickCount(), loggedIn) == DiarySyncTrigger.Decision.SYNC) {
			syncKingdom();
		}
	}

	static boolean isKingdomRegion(int regionId) {
		return KINGDOM_REGIONS.contains(regionId);
	}

	/** Whether a read is trustworthy enough to send. */
	static boolean shouldSend(boolean throneCompleted, int approvalPoints) {
		return throneCompleted && approvalPoints > 0;
	}

	private boolean isInKingdom() {
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || localPlayer.getWorldLocation() == null) {
			return false;
		}
		return isKingdomRegion(localPlayer.getWorldLocation().getRegionID());
	}

	/** Reads the kingdom varbits and syncs them (deduped). Client thread only. */
	private void syncKingdom() {
		if (!config.syncKingdom() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		boolean throneCompleted = Quest.THRONE_OF_MISCELLANIA.getState(client) == QuestState.FINISHED;
		int approvalPoints = client.getVarbitValue(VarbitID.MISC_APPROVAL);
		if (!shouldSend(throneCompleted, approvalPoints)) {
			return;
		}
		boolean royalTroubleCompleted = Quest.ROYAL_TROUBLE.getState(client) == QuestState.FINISHED;
		Map<String, Integer> extra = Collections.singletonMap(
				EXTRA_RESTOTAL_LOWBITS, client.getVarbitValue(RESTOTAL_LOWBITS_VARBIT));

		KingdomSyncPayload payload = new KingdomSyncPayload(
				playerUsername,
				wasInKingdom,
				throneCompleted,
				royalTroubleCompleted,
				approvalPoints,
				client.getVarbitValue(VarbitID.MISC_COFFERS),
				client.getVarbitValue(VarbitID.MISC_POINTS_WOOD),
				client.getVarbitValue(VarbitID.MISC_POINTS_HERB),
				client.getVarbitValue(VarbitID.MISC_POINTS_FISH),
				client.getVarbitValue(VarbitID.MISC_POINTS_MINE),
				client.getVarbitValue(VarbitID.MISC_POINTS_RAREWOOD),
				client.getVarbitValue(VarbitID.MISC_POINTS_FARM),
				client.getVarbitValue(VarbitID.MISC_COOKED),
				client.getVarbitValue(VarbitID.MISC_RAREWOOD_TYPE),
				client.getVarbitValue(VarbitID.MISC_HERBS_OR_FLAX),
				extra);
		String json = payload.toJson(gson);
		// Dedup on the whole payload (username included), so switching to another
		// account with identical values still syncs.
		if (json.equals(lastSyncJson)) {
			log.debug("Kingdom state unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing kingdom state (approval {}, coffer {}) for player: {}",
				approvalPoints, payload.getCoffer(), playerUsername);
		apiClient.sendKingdomSync(payload);
	}
}

