	/**
	 * Manually marks a single goal complete and returns the re-rendered roadmap.
	 */
	public void completeRoadmapGoal(int collectionId, int goalId, String playerUsername,
		RoadmapCallback<Roadmap> callback)
	{
		String url = ROADMAPS_ENDPOINT + collectionId + "/goals/" + goalId + "/complete/";
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", playerUsername);
		postForResult(url, gson.toJson(body), "roadmap-goal-complete", Roadmap.class, callback);
	}

	/**
	 * Deletes a single goal from a roadmap and returns the re-rendered roadmap.
	 */
	public void deleteRoadmapGoal(int collectionId, int goalId, String playerUsername,
		RoadmapCallback<Roadmap> callback)
	{
		String url = ROADMAPS_ENDPOINT + collectionId + "/goals/" + goalId + "/delete/";
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", playerUsername);
		postForResult(url, gson.toJson(body), "roadmap-goal-delete", Roadmap.class, callback);
	}

	private <T> void getAsync(String endpoint, String label, Class<T> type, RoadmapCallback<T> callback)
	{
		if (!SyncGuard.hasAppKey(config))
		{
			callback.onError("No Mystix App Key configured");
			return;
		}

		Request request = new Request.Builder()
			.url(API_BASE_URL + endpoint)
			.header("X-RuneLite-Key", config.mystixAppKey().trim())
			.get()
			.build();

		okHttpClient.newCall(request).enqueue(parsingCallback(label, type, callback));
	}

	private <T> void postForResult(String endpoint, String json, String label, Class<T> type,
		RoadmapCallback<T> callback)
	{
		if (!SyncGuard.hasAppKey(config))
		{
			callback.onError("No Mystix App Key configured");
			return;
		}

		Request request = new Request.Builder()
			.url(API_BASE_URL + endpoint)
			.header("Content-Type", "application/json")
			.header("X-RuneLite-Key", config.mystixAppKey().trim())
			.post(RequestBody.create(JSON_MEDIA_TYPE, json))
			.build();

		largeRequestClient.newCall(request).enqueue(parsingCallback(label, type, callback));
	}

	private <T> Callback parsingCallback(String label, Class<T> type, RoadmapCallback<T> callback)
	{
		return new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed {} request to Mystix API: {}", label, e.getMessage());
				callback.onError("Network error");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try
				{
					if (response.code() < HTTP_OK_MIN || response.code() >= HTTP_OK_MAX)
					{
						log.warn("Mystix API returned {} for {}", response.code(), label);
						callback.onError("Server returned " + response.code());
						return;
					}
					String responseBody = response.body() != null ? response.body().string() : "";
					T parsed = gson.fromJson(responseBody, type);
					if (parsed == null)
					{
						callback.onError("Empty response");
						return;
					}
					callback.onSuccess(parsed);
				}
				catch (IOException | JsonSyntaxException e)
				{
					log.warn("Failed to parse {} response: {}", label, e.getMessage());
					callback.onError("Could not read response");
				}
				finally
				{
					response.close();
				}
			}
		};
	}

	private static String urlEncode(String value)
	{
		if (value == null)
		{
			return "";
		}
		try
		{
			return URLEncoder.encode(value, StandardCharsets.UTF_8.name());
		}
		catch (UnsupportedEncodingException e)
		{
			return value;
		}
	}

	private void postAsync(String endpoint, String json, String syncType, boolean largeRequest,
		boolean dedupe, Runnable onSuccess)
	{
		if (!SyncGuard.hasAppKey(config))
		{
			log.debug("Skipping {} sync: no Mystix App Key configured", syncType);
			return;
		}

		if (dedupe && isDuplicate(lastSentBodyByType.get(syncType), json))
		{
			log.debug("Skipping {} sync: identical to last sent request", syncType);
			return;
		}

		String appKey = config.mystixAppKey();
		String url = API_BASE_URL + endpoint;

		Request request = new Request.Builder()
			.url(url)
			.header("Content-Type", "application/json")
			.header("X-RuneLite-Key", appKey.trim())
			.post(RequestBody.create(JSON_MEDIA_TYPE, json))
			.build();

		OkHttpClient client = largeRequest ? largeRequestClient : okHttpClient;
		client.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed to send {} sync to Mystix API: {}", syncType, e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try
				{
					if (response.code() >= HTTP_OK_MIN && response.code() < HTTP_OK_MAX)
					{
						if (dedupe)
						{
							lastSentBodyByType.put(syncType, json);
						}
						onSuccess.run();
					}
					else
					{
						log.warn("Mystix API returned {} for {} sync", response.code(), syncType);
					}
				}
				finally
				{
					response.close();
				}
			}
		});
	}

	static boolean isDuplicate(String previousBody, String currentJson)
	{
		return previousBody != null && previousBody.equals(currentJson);
	}

	/**
	 * Forgets the last-sent body for every sync type, so the next send of each
	 * type goes out even if its payload is byte-identical to the previous one.
	 *
	 * <p>The roadmap panel's "Sync &amp; refresh" is an explicit, user-triggered
	 * re-sync: the dedupe guard (which silently skips unchanged idempotent syncs)
	 * must not swallow it, or the button would do nothing when the player's data
	 * hasn't changed since the last automatic sync.
	 */
	public void clearDedupeCache()
	{
		lastSentBodyByType.clear();
	}
}

package com.mystix;

import com.mystix.model.RoadmapGoal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;

/**
 * Splits a roadmap's goals into the dependency tree the panel draws and the
 * flat "Completed" list beneath it.
 *
 * <p>The tree keeps only incomplete goals; a goal moves to the completed list
 * the moment the plugin considers it done. The completed list is sorted newest
 * first: goals completed this session (which have no server timestamp yet)
 * come first, then by the server's completion time, unknown times last. Pure,
 * so it is testable without Swing.
 */
final class GoalPartition {
	private final List<RoadmapGoal> tree;
	private final List<RoadmapGoal> completed;

	private GoalPartition(List<RoadmapGoal> tree, List<RoadmapGoal> completed) {
		this.tree = Collections.unmodifiableList(tree);
		this.completed = Collections.unmodifiableList(completed);
	}

	/**
	 * @param goals    goals in sort order
	 * @param complete whether the plugin considers a goal complete (server or local)
	 * @param session  whether the goal's completion was first seen this session
	 *                 (sorted newest in the completed list)
	 */
	static GoalPartition of(List<RoadmapGoal> goals,
			Predicate<RoadmapGoal> complete, Predicate<RoadmapGoal> session) {
		List<RoadmapGoal> tree = new ArrayList<>();
		List<RoadmapGoal> done = new ArrayList<>();
		Map<Integer, Long> recency = new HashMap<>();
		for (RoadmapGoal g : goals) {
			if (!complete.test(g)) {
				tree.add(g);
				continue;
			}
			done.add(g);
			recency.put(g.getId(), recencyKey(g, session.test(g)));
		}
		// Newest first; List.sort is stable so ties keep the roadmap's order.
		done.sort((a, b) -> Long.compare(recency.get(b.getId()), recency.get(a.getId())));
		return new GoalPartition(tree, done);
	}

	/** Session completions have no server timestamp yet: treat them as newest;
	 * a missing or unparseable timestamp sorts oldest. */
	private static long recencyKey(RoadmapGoal g, boolean thisSession) {
		if (thisSession) {
			return Long.MAX_VALUE;
		}
		Instant at = g.getCompletedAt();
		return at == null ? Long.MIN_VALUE : at.toEpochMilli();
	}

	/** Goals to draw as the dependency tree, in the given order. */
	List<RoadmapGoal> getTree() {
		return tree;
	}

	/** Finished goals for the collapsible list, newest completion first. */
	List<RoadmapGoal> getCompleted() {
		return completed;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.BiConsumer;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks the rune pouch (regular, divine and colossal: up to six slots) from
 * its varbits, which the game keeps current whether the pouch is carried or
 * banked. Every change is handed to the goal tracker so rune goals move
 * live, and uploaded as bank-memory source {@code rune_pouch} through a
 * debounced {@link SourceSyncer} (casting drains a rune per tick).
 */
@Slf4j
@Singleton
public class RunePouchMonitor {
	static final String SOURCE = "rune_pouch";

	private static final int[] TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6,
	};
	private static final int[] QUANTITY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6,
	};

	private final Client client;
	private final SourceSyncer syncer;

	private boolean dirty;
	private GameState previousGameState = GameState.UNKNOWN;
	private volatile BiConsumer<String, Map<Integer, Integer>> snapshotListener;

	@Inject
	public RunePouchMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			Gson gson,
			ScheduledExecutorService executor) {
		this.client = client;
		this.syncer = new SourceSyncer(SOURCE, gson, executor,
				() -> config.syncBankMemory() && SyncGuard.hasAppKey(config) && !GameModeUtil.isSpecialGameMode(client),
				() -> SyncGuard.getPlayerUsername(client),
				apiClient::sendBankSync);
	}

	/** Receives every read (source, item id to quantity), before any sync gate. */
	public void setSnapshotListener(BiConsumer<String, Map<Integer, Integer>> listener) {
		this.snapshotListener = listener;
	}

	/** Item ids active owned-item goals are counting (short debounce for them); set by the plugin. */
	public void setGoalItems(Supplier<Set<Integer>> goalItems) {
		syncer.setGoalItems(goalItems);
	}

	public void stop() {
		syncer.stop();
		dirty = false;
	}

	/** Upload the current contents right away (an owned-item goal just completed). */
	public void syncNow() {
		syncer.invalidate();
		dirty = true;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		int id = event.getVarbitId();
		for (int i = 0; i < TYPE_VARBITS.length; i++) {
			if (id == TYPE_VARBITS[i] || id == QUANTITY_VARBITS[i]) {
				dirty = true;
				return;
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			dirty = true; // push the pouch as it is at login
		} else if (SyncGuard.isLogout(previousGameState, newState)) {
			syncer.flushPending();
		}
		previousGameState = newState;
	}

	/** Reads on the game tick so a burst of varbit changes is read once. */
	@Subscribe
	public void onGameTick(GameTick event) {
		if (!dirty) {
			return;
		}
		dirty = false;
		EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runes == null) {
			return;
		}
		int[] types = new int[TYPE_VARBITS.length];
		int[] quantities = new int[QUANTITY_VARBITS.length];
		for (int i = 0; i < TYPE_VARBITS.length; i++) {
			types[i] = client.getVarbitValue(TYPE_VARBITS[i]);
			quantities[i] = client.getVarbitValue(QUANTITY_VARBITS[i]);
		}
		Map<Integer, Integer> contents = contents(types, quantities, runes::getIntValue);
		BiConsumer<String, Map<Integer, Integer>> listener = snapshotListener;
		if (listener != null) {
			listener.accept(SOURCE, contents);
		}
		syncer.submit(contents, false);
	}

	/**
	 * Slot varbits to item id and quantity. A slot's type is a rune-pouch rune
	 * index (0 = empty) resolved through the {@code RUNEPOUCH_RUNE} enum; the
	 * same rune in two slots is merged.
	 */
	static Map<Integer, Integer> contents(int[] types, int[] quantities, IntUnaryOperator runeToItemId) {
		Map<Integer, Integer> contents = new LinkedHashMap<>();
		for (int i = 0; i < types.length && i < quantities.length; i++) {
			if (types[i] <= 0 || quantities[i] <= 0) {
				continue;
			}
			int itemId = runeToItemId.applyAsInt(types[i]);
			if (itemId <= 0) {
				continue;
			}
			contents.merge(itemId, quantities[i], Integer::sum);
		}
		return contents;
	}
}

