	private final ScheduledExecutorService executorService;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	/** Persistent client identifier unique to this RuneLite installation. */
	private String clientId;
	/** Tracks cumulative kill counts per NPC name for the current session. */
	private final Map<String, Integer> sessionKillCounts = new LinkedHashMap<>();
	/** Queued loot drops waiting to be flushed to the API. */
	private final List<LootDropPayload> pendingDrops = new ArrayList<>();
	/** Caches NPC name -> NPC ID from NpcLootReceived events (fires before LootReceived). */
	private final Map<String, Integer> recentNpcIds = new LinkedHashMap<>();
	private ScheduledFuture<?> flushTask;
	/** Uploads a notable drop right away instead of waiting for the next timed flush. */
	private final NotableLootFlusher notableFlusher;
	/** MD5 hash of the last successfully synced loot data, used to skip redundant syncs. */
	private String lastSyncHash;

	@Inject
	public LootMonitor(
		Client client,
		MystixConfig config,
		MystixApiClient apiClient,
		ScheduledExecutorService executorService,
		ClientThread clientThread,
		ConfigManager configManager,
		ItemManager itemManager,
		Gson gson)
	{
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.gson = gson;
		this.notableFlusher = new NotableLootFlusher(executorService, this::flushDrops);
	}

	public void start()
	{
		// Read or generate a persistent client ID (per-machine, not per RS profile).
		clientId = configManager.getConfiguration("mystix", "clientId");
		if (clientId == null || clientId.isEmpty())
		{
			clientId = UUID.randomUUID().toString();
			configManager.setConfiguration("mystix", "clientId", clientId);
		}

		flushTask = executorService.scheduleAtFixedRate(
			this::flushDrops, FLUSH_INTERVAL_SECONDS, FLUSH_INTERVAL_SECONDS, TimeUnit.SECONDS);
	}

	/** Invoked after each upload so roadmap progress can be re-read; set by the plugin. */
	private volatile Runnable syncedListener;

	public void setSyncedListener(Runnable listener)
	{
		this.syncedListener = listener;
	}

	private void notifySynced()
	{
		Runnable listener = syncedListener;
		if (listener != null)
		{
			listener.run();
		}
	}

	/** Receives every loot drop the monitor queues for upload (set by the plugin). */
	public interface DropListener
	{
		void onDrop(int npcId, String npcName, int kills, List<LootSyncPayload.LootItem> items);
	}

	private volatile DropListener dropListener;

	public void setDropListener(DropListener listener)
	{
		this.dropListener = listener;
	}

	/**
	 * Flushes queued drops on the background executor right away (a roadmap goal
	 * just completed locally and the server should hear about it promptly).
	 */
	public void flushDropsNow()
	{
		executorService.execute(this::flushDrops);
	}

	public void stop()
	{
		if (flushTask != null)
		{
			flushTask.cancel(false);
			flushTask = null;
		}
		notableFlusher.cancel();
		flushDrops();
		previousGameState = GameState.UNKNOWN;
		sessionKillCounts.clear();
		recentNpcIds.clear();
		lastSyncHash = null;
	}

	/**
	 * Re-runs the loot sync immediately on the background executor, forcing a
	 * resend by clearing the change-detection hash. Used by the roadmap panel's
	 * "Sync &amp; refresh" button.
	 */
	public void forceSync()
	{
		executorService.execute(() ->
		{
			lastSyncHash = null;
			syncLoot();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();

		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
		{
			log.debug("Player logged in, waiting for RS profile before loot sync");
			// Use clientThread.invokeLater to poll each tick until the RS profile
			// key is available. Returns false to retry, true when done.
			clientThread.invokeLater(() ->
			{
				if (client.getGameState().getState() < GameState.LOGGED_IN.getState())
				{
					// Logged out before profile loaded — abort
					return true;
				}
				String profileKey = configManager.getRSProfileKey();
				if (profileKey == null)
				{
					return false; // not ready yet, retry next tick
				}
				log.debug("RS profile ready ({}), scheduling loot sync in {}s", profileKey, PROFILE_SYNC_DELAY_SECONDS);
				executorService.schedule(this::syncLoot, PROFILE_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
				return true;
			});
		}
		else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN)
		{
			log.debug("Player logged out, flushing pending drops and syncing loot");
			flushDrops();
			syncLoot();
		}

		previousGameState = newState;
	}

	/**
	 * Handles loot drops from the RuneLite loot tracker plugin.
	 * LootReceived fires after the loot tracker processes a kill, providing
	 * the NPC name, kill count (amount), items, and NPC metadata with the ID.
	 */
	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		if (npc != null && npc.getName() != null)
		{
			recentNpcIds.put(npc.getName(), npc.getId());
		}
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event.getType() != LootRecordType.NPC && event.getType() != LootRecordType.EVENT)
		{
			return;
		}
		if (!config.syncLoot())
		{
			return;
		}
		if (!SyncGuard.hasAppKey(config))
		{
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null)
		{
			return;
		}

		String npcName = event.getName();

		// event.getAmount() is the number of kills in THIS event (always 1),
		// not cumulative KC. We track KC ourselves: seed from the loot tracker
		// config on first kill, then increment locally per kill.
		int killCount = sessionKillCounts.compute(npcName, (name, current) ->
		{
			if (current == null)
			{
				// First kill this session — seed from loot tracker config.
				// Config has the count BEFORE this kill, so add the event amount.
				return readCumulativeKillCount(name) + event.getAmount();
			}
			return current + event.getAmount();
		});

		// The metadata contains an NpcMetadata object with the NPC ID.
		// NpcMetadata is package-private, so we access it via reflection-free approach:
		// resolve from nearby loaded NPCs by name, or from metadata if castable.
		int npcId = resolveNpcIdFromEvent(event);

		List<LootSyncPayload.LootItem> items = new ArrayList<>();
		boolean notable = false;
		for (ItemStack itemStack : event.getItems())
		{
			int itemId = canonicalizeItemId(itemStack.getId());
			items.add(new LootSyncPayload.LootItem(itemId, itemStack.getQuantity()));
			notable = notable || isNotable(itemId, itemStack.getQuantity());
		}

		if (items.isEmpty())
		{
			return;
		}

		String droppedAt = DateTimeFormatter.ISO_INSTANT.format(Instant.now().atOffset(ZoneOffset.UTC));
		LootDropPayload payload = new LootDropPayload(playerUsername, clientId, npcId, npcName, killCount, droppedAt, items);
		log.debug("Loot drop from {} (id={}, kc={}): {} items (queued)", npcName, npcId, killCount, items.size());

		synchronized (pendingDrops)
		{
			pendingDrops.add(payload);
		}
		DropListener listener = dropListener;
		if (listener != null)
		{
			listener.onDrop(npcId, npcName, event.getAmount(), items);
		}
		if (notable)
		{
			notableFlusher.request();
		}
	}

	private boolean isNotable(int itemId, int quantity)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		boolean tradeable = comp == null || comp.isTradeable();
		return NotableLootFlusher.isNotable(itemId, quantity, itemManager.getItemPrice(itemId), tradeable);
	}

	/**
	 * Flushes all queued loot drops to the API in a single batch request.
	 */
	private void flushDrops()
	{
		List<LootDropPayload> dropsToSend;
		synchronized (pendingDrops)
		{
			if (pendingDrops.isEmpty())
			{
				return;
			}
			dropsToSend = new ArrayList<>(pendingDrops);
			pendingDrops.clear();
		}

		log.debug("Flushing {} loot drops to API", dropsToSend.size());
		apiClient.sendLootDrops(dropsToSend);
		notifySynced();
	}

	/**
	 * Reads cumulative loot data from RuneLite's loot tracker config and syncs to the API.
	 */
	private void syncLoot()
	{
		if (!config.syncLoot())
		{
			return;
		}
		if (!SyncGuard.hasAppKey(config))
		{
			log.debug("Loot sync skipped: no App Key configured");
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client))
		{
			log.debug("Loot sync skipped: special game mode detected");
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null)
		{
			log.warn("Loot sync skipped: could not get player username");
			return;
		}

		List<LootSyncPayload.LootRecord> lootRecords = readLootTrackerData();
		if (lootRecords.isEmpty())
		{
			log.debug("No loot tracker data to sync");
			return;
		}

		String currentHash = computeLootHash(lootRecords);

		// Lazily load persisted hash on first sync after start/restart
		if (lastSyncHash == null)
		{
			lastSyncHash = configManager.getRSProfileConfiguration("mystix", LAST_SYNC_HASH_KEY);
		}

		if (currentHash.equals(lastSyncHash))
		{
			log.debug("Loot data unchanged, skipping sync ({} records)", lootRecords.size());
			return;
		}

		LootSyncPayload payload = new LootSyncPayload(playerUsername, clientId, lootRecords);
		log.debug("Syncing {} loot records for player: {}", lootRecords.size(), playerUsername);
		apiClient.sendLootSync(payload);
		notifySynced();

		lastSyncHash = currentHash;
		configManager.setRSProfileConfiguration("mystix", LAST_SYNC_HASH_KEY, currentHash);
	}

	/**
	 * Computes an MD5 hash of the loot records for change detection.
	 * Records are sorted by NPC name to ensure deterministic ordering.
	 */
	private String computeLootHash(List<LootSyncPayload.LootRecord> records)
	{
		try
		{
			MessageDigest md = MessageDigest.getInstance("MD5");
			List<LootSyncPayload.LootRecord> sorted = new ArrayList<>(records);
			sorted.sort((a, b) -> a.getNpcName().compareTo(b.getNpcName()));
			for (LootSyncPayload.LootRecord record : sorted)
			{
				md.update(record.getNpcName().getBytes(java.nio.charset.StandardCharsets.UTF_8));
				md.update(intToBytes(record.getNpcId()));
				md.update(intToBytes(record.getKillCount()));
				for (LootSyncPayload.LootItem item : record.getItems())
				{
					md.update(intToBytes(item.getItemId()));
					md.update(intToBytes(item.getQuantity()));
				}
			}
			byte[] digest = md.digest();
			StringBuilder sb = new StringBuilder();
			for (byte b : digest)
			{
				sb.append(String.format("%02x", b & 0xff));
			}
			return sb.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			log.debug("MD5 not available, skipping hash-based dedup", e);
			return UUID.randomUUID().toString();
		}
	}

	private static byte[] intToBytes(int value)
	{
		return new byte[] {
			(byte) (value >> 24), (byte) (value >> 16),
			(byte) (value >> 8), (byte) value
		};
	}

	/**
	 * Reads cumulative loot data from RuneLite's loot tracker ConfigManager storage.
	 *
	 * The loot tracker stores ConfigLoot objects as JSON under RSProfile keys
	 * with the format: drops_{LootRecordType}_{NpcName} (e.g. "drops_NPC_Zulrah").
	 */
	private List<LootSyncPayload.LootRecord> readLootTrackerData()
	{
		List<LootSyncPayload.LootRecord> records = new ArrayList<>();

		try
		{
			String profileKey = configManager.getRSProfileKey();
			if (profileKey == null)
			{
				log.debug("No RS profile key available for loot sync");
				return records;
			}

			List<String> keys = configManager.getRSProfileConfigurationKeys(
				LOOT_TRACKER_CONFIG_GROUP, profileKey, LOOT_TRACKER_DROPS_PREFIX
			);

			for (String key : keys)
			{
				try
				{
					String json = configManager.getConfiguration(LOOT_TRACKER_CONFIG_GROUP, profileKey, key);
					if (json == null || json.isEmpty())
					{
						continue;
					}

					LootSyncPayload.LootRecord record = parseConfigLootJson(json);
					if (record != null)
					{
						records.add(record);
					}
				}
				catch (Exception e)
				{
					log.debug("Failed to parse loot tracker key: {}", key, e);
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to read loot tracker data from config", e);
		}

		return records;
	}

	/**
	 * Parses a serialized ConfigLoot JSON object into our LootRecord format.
	 * This runs on the executor thread so it avoids client-thread-only APIs
	 * (no NPC lookups, no ItemManager calls). The loot tracker already stores
	 * canonical item IDs and the NPC name is used by the backend for matching.
	 */
	private LootSyncPayload.LootRecord parseConfigLootJson(String json)
	{
		JsonObject obj = gson.fromJson(json, JsonObject.class);

		String type = obj.has("type") ? obj.get("type").getAsString() : "";
		if (!"NPC".equals(type) && !"EVENT".equals(type))
		{
			return null;
		}

		String npcName = obj.has("name") ? obj.get("name").getAsString() : null;
		if (npcName == null || npcName.isEmpty())
		{
			return null;
		}

		// Use a deterministic hash for the NPC ID since we can't call client
		// APIs from the executor thread. The backend resolves the real NPC via name.
		int npcId = npcName.hashCode() & 0x7FFFFFFF;
		int killCount = obj.has("kills") ? obj.get("kills").getAsInt() : 0;

		Map<Integer, Integer> aggregatedItems = new LinkedHashMap<>();
		if (obj.has("drops"))
		{
			JsonArray drops = obj.getAsJsonArray("drops");
			for (int i = 0; i + 1 < drops.size(); i += 2)
			{
				int itemId = drops.get(i).getAsInt();
				int quantity = drops.get(i + 1).getAsInt();
				aggregatedItems.merge(itemId, quantity, Integer::sum);
			}
		}

		List<LootSyncPayload.LootItem> items = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : aggregatedItems.entrySet())
		{
			items.add(new LootSyncPayload.LootItem(entry.getKey(), entry.getValue()));
		}

		return new LootSyncPayload.LootRecord(npcId, npcName, killCount, items);
	}

	/**
	 * Reads the cumulative kill count for an NPC from the loot tracker's config.
	 * The loot tracker stores config under key "drops_NPC_{name}" with a "kills" field.
	 * This runs on the client thread (called from onLootReceived) so ConfigManager access is safe.
	 */
	private int readCumulativeKillCount(String npcName)
	{
		try
		{
			String profileKey = configManager.getRSProfileKey();
			if (profileKey == null)
			{
				return 0;
			}
			String configKey = LOOT_TRACKER_DROPS_PREFIX + "NPC_" + npcName;
			String json = configManager.getConfiguration(LOOT_TRACKER_CONFIG_GROUP, profileKey, configKey);
			if (json == null || json.isEmpty())
			{
				return 0;
			}
			JsonObject obj = gson.fromJson(json, JsonObject.class);
			return obj.has("kills") ? obj.get("kills").getAsInt() : 0;
		}
		catch (Exception e)
		{
			log.debug("Could not read cumulative kill count for {}", npcName, e);
			return 0;
		}
	}

	/**
	 * Resolves the NPC ID from a LootReceived event.
	 * Checks the cache populated by NpcLootReceived, falls back to nearby NPC lookup.
	 */
	private int resolveNpcIdFromEvent(LootReceived event)
	{
		Integer cachedId = recentNpcIds.get(event.getName());
		if (cachedId != null && cachedId > 0)
		{
			return cachedId;
		}

		return resolveNpcId(event.getName());
	}

	/**
	 * Resolves an NPC name to its NPC ID by checking currently loaded NPCs.
	 * Falls back to a deterministic hash if no matching NPC is found nearby.
	 */
	private int resolveNpcId(String npcName)
	{
		for (NPC npc : getWorldNpcs())
		{
			if (npc.getName() != null && npc.getName().equalsIgnoreCase(npcName))
			{
				return npc.getId();
			}
		}
		return npcName.hashCode() & 0x7FFFFFFF;
	}

	private Iterable<? extends NPC> getWorldNpcs()
	{
		WorldView wv = client.getTopLevelWorldView();
		return wv == null ? Collections.emptyList() : wv.npcs();
	}

	/**
	 * Converts noted item IDs to their base item ID using the ItemManager.
	 */
	private int canonicalizeItemId(int itemId)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		if (comp != null && comp.getNote() != -1)
		{
			return comp.getLinkedNoteId();
		}
		return itemId;
	}
}

package com.mystix;

import com.mystix.api.MystixApiClient;
import com.mystix.model.PlayerSkillsSyncPayload;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Uploads skill levels and XP: on login, on logout, and while training (at most
 * every {@link #TRAINING_SYNC_INTERVAL_SECONDS} while XP is actually rising) so
 * the server can keep roadmap skill goals current without waiting for logout.
 */
@Slf4j
@Singleton
public class PlayerSkillsMonitor {
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	/** How often to re-upload while training; nothing is sent when XP is static. */
	static final int TRAINING_SYNC_INTERVAL_SECONDS = 120;

	private final Client client;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;

	private GameState previousGameState = GameState.UNKNOWN;
	/** Last XP seen per skill (client thread); the first value after login is the replay. */
	private final Map<String, Integer> lastSeenXp = new HashMap<>();
	private volatile boolean xpDirty;
	private ScheduledFuture<?> trainingTask;
	/** The XP snapshot of the last upload the server acknowledged, keyed by skill name. */
	private volatile Map<String, Integer> lastUploadedXp = Collections.emptyMap();
	private volatile Consumer<Map<String, Integer>> uploadListener;

	@Inject
	public PlayerSkillsMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService) {
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
	}

	public void start() {
		if (trainingTask == null) {
			trainingTask = executorService.scheduleAtFixedRate(this::syncIfDirty,
					TRAINING_SYNC_INTERVAL_SECONDS, TRAINING_SYNC_INTERVAL_SECONDS, TimeUnit.SECONDS);
		}
	}

	public void stop() {
		if (trainingTask != null) {
			trainingTask.cancel(false);
			trainingTask = null;
		}
		previousGameState = GameState.UNKNOWN;
		lastSeenXp.clear();
		xpDirty = false;
		uploadListener = null;
	}

	/** Receives each acknowledged upload's XP snapshot (set by the plugin). */
	public void setUploadListener(Consumer<Map<String, Integer>> listener) {
		this.uploadListener = listener;
	}

	public Map<String, Integer> getLastUploadedXp() {
		return lastUploadedXp;
	}

	/**
	 * Re-runs the skills sync immediately on the background executor. Used by the
	 * roadmap panel's "Sync &amp; refresh" button to re-push current progress.
	 */
	public void forceSync() {
		executorService.execute(this::syncPlayerSkills);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();

		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			log.debug("Player logged in, scheduling skills sync in {}s", LOGIN_SYNC_DELAY_SECONDS);
			executorService.schedule(this::syncPlayerSkills, LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			log.debug("Player logged out, syncing skills");
			lastSeenXp.clear();
			xpDirty = false;
			syncPlayerSkills();
		}

		previousGameState = newState;
	}

	@Subscribe
	public void onStatChanged(StatChanged event) {
		Integer previous = lastSeenXp.put(event.getSkill().getName(), event.getXp());
		if (xpIncreased(previous, event.getXp())) {
			xpDirty = true;
		}
	}

	/** True only for a real gain: the first observation after login is the server
	 * replay, and boosted-level events carry the same XP. */
	static boolean xpIncreased(Integer previous, int now) {
		return previous != null && now > previous;
	}

	private void syncIfDirty() {
		if (!xpDirty || client.getGameState() != GameState.LOGGED_IN) {
			return;
		}
		xpDirty = false;
		syncPlayerSkills();
	}

	/**
	 * Reads all skill levels and XP from the client, builds a payload with
	 * total and combat levels, and sends it to the Mystix API.
	 */
	private void syncPlayerSkills() {
		if (!SyncGuard.hasAppKey(config)) {
			log.debug("Player skills sync skipped: no App Key configured");
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			log.debug("Player skills sync skipped: special game mode detected (Leagues, DMM, etc.)");
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Player skills sync skipped: could not get player username");
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		Map<String, PlayerSkillsSyncPayload.SkillData> skills = new HashMap<>();
		Map<String, Integer> xpSnapshot = new HashMap<>();
		int totalLevel = 0;

		for (Skill skill : Skill.values()) {
			int level = client.getRealSkillLevel(skill);
			int xp = client.getSkillExperience(skill);
			skills.put(skill.getName(), new PlayerSkillsSyncPayload.SkillData(level, xp));
			xpSnapshot.put(skill.getName(), xp);
			totalLevel += level;
		}

		int combatLevel = localPlayer.getCombatLevel();

		PlayerSkillsSyncPayload payload = new PlayerSkillsSyncPayload(playerUsername, skills, totalLevel, combatLevel);
		log.debug("Syncing {} skills for player: {} (Total Level: {}, Combat Level: {})",
				skills.size(), playerUsername, totalLevel, combatLevel);
		Map<String, Integer> snapshot = Collections.unmodifiableMap(xpSnapshot);
		apiClient.sendPlayerSkillsSync(payload, () -> {
			lastUploadedXp = snapshot;
			Consumer<Map<String, Integer>> listener = uploadListener;
			if (listener != null) {
				listener.accept(snapshot);
			}
		});
	}
}

package com.mystix;

/**
 * Pure decision logic for <em>when</em> {@link AchievementDiaryMonitor} may read diary state.
 *
 * <p>The client's varplayer array is not reset atomically on login / world-hop /
 * account-switch: the server replays the varp block over several ticks after
 * {@code GameState.LOGGED_IN}. Reading during that window can mirror a prior session's
 * fully-complete diary bits onto the current player, which the append-only backend records
 * permanently. This state machine ensures:
 *
 * <ul>
 *   <li>the first read of a session (the <em>baseline</em>) only happens after a short
 *       settle period, by which time the server's varp block has landed;</li>
 *   <li>the varbit-driven near-real-time resync never fires <em>before</em> that baseline
 *       (the varp replay is itself a flood of {@code VarbitChanged}, which previously
 *       pre-empted the login delay and triggered a read mid-replay);</li>
 *   <li>state resets on leaving {@code LOGGED_IN}, so a prior session's values can never be
 *       adopted as the next account's baseline.</li>
 * </ul>
 *
 * <p>It holds no RuneLite references, so it is unit-testable without a live {@code Client}.
 */
final class DiarySyncTrigger {
	/**
	 * Ticks to wait after login before the first (baseline) read, so the server's varp
	 * replay has landed. ~5 ticks is roughly 3 seconds, matching the previous login delay
	 * while now being enforced against every read path rather than a single scheduled task.
	 */
	static final int LOGIN_SETTLE_TICKS = 5;
	/** Minimum ticks between varbit-driven resyncs once the baseline has been established. */
	static final int RESYNC_THROTTLE_TICKS = 3;

	enum Decision {
		NONE,
		SYNC
	}

	private boolean loggedIn;
	private boolean baselineSynced;
	private int loginTick = -1;
	private boolean resyncPending;
	private int lastReadTick = -1;

	/** A varbit changed; request a resync. Acted on only once the baseline has run. */
	void varbitChanged() {
		resyncPending = true;
	}

	/**
	 * Drive from every {@code GameTick}. Returns {@link Decision#SYNC} when the monitor
	 * should read and sync now, {@link Decision#NONE} otherwise.
	 *
	 * @param currentTick the client tick count
	 * @param loggedInNow whether the client is currently in the LOGGED_IN state
	 */
	Decision tick(int currentTick, boolean loggedInNow) {
		if (!loggedInNow) {
			reset();
			return Decision.NONE;
		}
		if (!loggedIn) {
			// Entered logged-in (also covers a missed GameStateChanged, e.g. the plugin
			// being enabled mid-session): start the settle clock, do not read yet.
			enterSession(currentTick);
			return Decision.NONE;
		}
		if (!baselineSynced) {
			if (currentTick - loginTick >= LOGIN_SETTLE_TICKS) {
				baselineSynced = true;
				resyncPending = false;
				lastReadTick = currentTick;
				return Decision.SYNC;
			}
			return Decision.NONE;
		}
		if (resyncPending && currentTick - lastReadTick >= RESYNC_THROTTLE_TICKS) {
			resyncPending = false;
			lastReadTick = currentTick;
			return Decision.SYNC;
		}
		return Decision.NONE;
	}

	/**
	 * Call on a {@code LOGGED_IN -> not-logged-in} transition. Returns whether to flush the
	 * final state (only when a trustworthy baseline was established this session, so a
	 * logout during the settle window never sends transitional data), then resets.
	 */
	boolean leaveAndShouldFlush() {
		// baselineSynced is only ever set while logged in, so it already implies loggedIn.
		boolean flush = baselineSynced;
		reset();
		return flush;
	}

	/** True once this session's settle period has elapsed and the baseline read has run. */
	boolean isBaselineSynced() {
		return baselineSynced;
	}

	/** Clears all session state; the next logged-in tick starts a fresh settle window. */
	void reset() {
		loggedIn = false;
		baselineSynced = false;
		loginTick = -1;
		resyncPending = false;
		lastReadTick = -1;
	}

	private void enterSession(int currentTick) {
		reset();
		loggedIn = true;
		loginTick = currentTick;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.mystix.model.DiaryTierResult;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

/**
 * Reads achievement diary completion from the live game and produces the
 * WikiSync {@code achievement_diaries} shape ({@code {region: {tier: {complete,
 * tasks: [bool, ...]}}}}).
 *
 * <p>The region/tier/task -&gt; varbit mapping is embedded verbatim from the WikiSync
 * API's server-authoritative spec
 * (<a href="https://github.com/weirdgloop/wikisync-api">weirdgloop/wikisync-api</a>,
 * MIT; {@code src/runelite/data/achievementDiariesSpecs.json}). Each task reads a
 * varbit ({@code type: "bits"}, complete when the varbit equals {@code value}) or
 * a bit of a varplayer ({@code type: "player"}, complete when bit {@code offset}
 * is set). Reproducing that spec's order keeps each {@code tasks} array positional
 * in in-game varbit order, matching the backend's
 * {@code OSRSAchievementDiaryTask.sequence}.
 */
@Slf4j
@Singleton
public class AchievementDiariesReader {
	private static final String SPEC_RESOURCE = "achievement_diaries_specs.json";
	private static final String TYPE_BITS = "bits";
	private static final String TYPE_PLAYER = "player";

	// The one task the WikiSync transformer resolves specially (ironman vs
	// non-ironman recorded it in different varps): Desert Medium task index 10.
	private static final String DESERT = "Desert";
	private static final String MEDIUM = "Medium";
	private static final int DESERT_MEDIUM_SPECIAL_INDEX = 10;

	private final Map<String, Map<String, TierSpec>> specs;

	@Inject
	public AchievementDiariesReader(Gson gson) {
		this.specs = loadSpecs(gson);
	}

	/** Reads current completion for every diary on the client thread. */
	public Map<String, Map<String, DiaryTierResult>> read(Client client) {
		return read(client::getVarbitValue, client::getVarpValue);
	}

	/**
	 * Evaluates the spec against varbit / varplayer value lookups. Package-private
	 * so unit tests can drive it without a live {@link Client}.
	 */
	Map<String, Map<String, DiaryTierResult>> read(IntUnaryOperator varbit, IntUnaryOperator varp) {
		Map<String, Map<String, DiaryTierResult>> out = new LinkedHashMap<>();
		for (Map.Entry<String, Map<String, TierSpec>> regionEntry : specs.entrySet()) {
			String region = regionEntry.getKey();
			Map<String, DiaryTierResult> tiers = new LinkedHashMap<>();
			for (Map.Entry<String, TierSpec> tierEntry : regionEntry.getValue().entrySet()) {
				String tierName = tierEntry.getKey();
				TierSpec tierSpec = tierEntry.getValue();
				boolean complete = evalSpec(tierSpec.complete, varbit, varp);
				List<Boolean> tasks = new ArrayList<>(tierSpec.tasks.size());
				for (int i = 0; i < tierSpec.tasks.size(); i++) {
					tasks.add(evalTask(region, tierName, i, tierSpec.tasks.get(i), varbit, varp));
				}
				tiers.put(tierName, new DiaryTierResult(complete, tasks));
			}
			out.put(region, tiers);
		}
		return out;
	}

	private static boolean evalTask(String region, String tier, int index, VarSpec spec,
			IntUnaryOperator varbit, IntUnaryOperator varp) {
		if (DESERT.equals(region) && MEDIUM.equals(tier) && index == DESERT_MEDIUM_SPECIAL_INDEX) {
			return isBitSet(varp.applyAsInt(1199), 9) || isBitSet(varp.applyAsInt(1198), 22);
		}
		return evalSpec(spec, varbit, varp);
	}

	private static boolean evalSpec(VarSpec spec, IntUnaryOperator varbit, IntUnaryOperator varp) {
		if (spec == null || spec.type == null) {
			return false;
		}
		if (TYPE_BITS.equals(spec.type)) {
			return varbit.applyAsInt(spec.var_id) == spec.value;
		}
		if (TYPE_PLAYER.equals(spec.type)) {
			return isBitSet(varp.applyAsInt(spec.var_id), spec.offset);
		}
		return false;
	}

	private static boolean isBitSet(int bitmap, int index) {
		return (bitmap & (1 << index)) != 0;
	}

	private Map<String, Map<String, TierSpec>> loadSpecs(Gson gson) {
		try (InputStream in = getClass().getResourceAsStream(SPEC_RESOURCE)) {
			if (in == null) {
				log.error("Mystix: achievement diary spec resource {} not found", SPEC_RESOURCE);
				return Collections.emptyMap();
			}
			Type type = new TypeToken<LinkedHashMap<String, LinkedHashMap<String, TierSpec>>>() {
			}.getType();
			Map<String, Map<String, TierSpec>> parsed =
					gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
			return parsed != null ? parsed : Collections.emptyMap();
		} catch (Exception e) {
			log.error("Mystix: failed to load achievement diary specs", e);
			return Collections.emptyMap();
		}
	}

	/** One varbit / varplayer reference from the embedded spec. */
	private static final class VarSpec {
		private String type;
		private int var_id;
		private Integer value;
		private Integer offset;
	}

	/** One tier's completion flag plus its ordered per-task references. */
	private static final class TierSpec {
		private VarSpec complete;
		private List<VarSpec> tasks;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.HouseLocationSyncPayload;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Syncs where the player's house is ({@link VarbitID#POH_HOUSE_LOCATION}) so Mystix Farm
 * Routes only recommend "Teleport to House" where the portal actually lands.
 *
 * <p>Read timing reuses {@link DiarySyncTrigger}: the varp block is replayed over several
 * ticks after login, so the first read waits for the session to settle (a mid-replay read
 * could report a prior account's house), and a later change (moving house at the estate
 * agent) resyncs a few ticks after its {@link VarbitChanged}. A value of 0 means no house
 * and is never sent, so a location the player set by hand in the app survives a fresh
 * account or a login before the house is bought.
 */
@Slf4j
@Singleton
public class HouseLocationMonitor {
	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final Gson gson;
	private final DiarySyncTrigger trigger = new DiarySyncTrigger();

	private GameState previousGameState = GameState.UNKNOWN;
	private String lastSyncJson;

	@Inject
	public HouseLocationMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.gson = gson;
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		trigger.reset();
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the house location on the client thread (the panel's
	 * "Sync &amp; refresh"); clears the dedup so an unchanged value still sends. No-op until
	 * the session has settled, so it can never sample the post-login replay window.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			if (client.getGameState() != GameState.LOGGED_IN || !trigger.isBaselineSynced()) {
				return;
			}
			lastSyncJson = null;
			syncHouseLocation();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		boolean wasLoggedIn = previousGameState == GameState.LOGGED_IN;
		boolean nowLoggedIn = newState == GameState.LOGGED_IN;
		if (wasLoggedIn && !nowLoggedIn) {
			if (trigger.leaveAndShouldFlush()) {
				syncHouseLocation();
			}
		}
		previousGameState = newState;
	}

	/** Only the house-location varbit matters here; every other change is ignored. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (event.getVarbitId() == VarbitID.POH_HOUSE_LOCATION) {
			trigger.varbitChanged();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		if (trigger.tick(client.getTickCount(), loggedIn) == DiarySyncTrigger.Decision.SYNC) {
			syncHouseLocation();
		}
	}

	/** Reads the varbit and syncs it (deduped). Client thread only. */
	private void syncHouseLocation() {
		if (!config.syncHouseLocation() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		int value = client.getVarbitValue(VarbitID.POH_HOUSE_LOCATION);
		if (value == 0) {
			// No house (or not loaded yet): never overwrite a manual pick with "unknown".
			return;
		}
		HouseLocationSyncPayload payload = new HouseLocationSyncPayload(playerUsername, value);
		String json = payload.toJson(gson);
		// Dedup on the whole payload (username included), so switching to another
		// account whose house happens to share the same id still syncs.
		if (json.equals(lastSyncJson)) {
			log.debug("House location unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing house location {} for player: {}", value, playerUsername);
		apiClient.sendHouseLocationSync(payload);
	}
}

package com.mystix;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;

/**
 * Shared pre-sync validation checks used by all monitors.
 */
public final class SyncGuard {

	/**
	 * Minimum length a value must reach to be treated as a complete app key.
	 * Keys are currently generated server-side as a 16-character string (see the
	 * backend's UserProfile.generate_runelite_key); this floor stays valid if that
	 * length ever changes, while still rejecting obviously-partial input.
	 */
	public static final int APP_KEY_MIN_LENGTH = 8;

	private SyncGuard() {
	}

	public static boolean hasAppKey(MystixConfig config) {
		String key = config.mystixAppKey();
		return key != null && !key.isBlank();
	}

	/**
	 * Returns true when a ConfigChanged event represents a complete Mystix app key
	 * being entered: the Mystix config group, the app-key item, and a value at least
	 * APP_KEY_MIN_LENGTH characters long. The length floor rejects obviously-partial
	 * input and key clears while tolerating a future change to the key length.
	 */
	public static boolean isCompleteAppKeyEntry(String group, String key, String newValue) {
		if (!MystixConfig.CONFIG_GROUP.equals(group) || !MystixConfig.APP_KEY.equals(key)) {
			return false;
		}
		return newValue != null && newValue.trim().length() >= APP_KEY_MIN_LENGTH;
	}

	/**
	 * Returns the local player's username, or null if unavailable.
	 */
	/**
	 * True when the game-state transition is a real logout (to the login
	 * screen). Region loads, world hops and connection drops pass through
	 * LOADING / HOPPING / CONNECTION_LOST with the player still known, so they
	 * are not logouts and must not trigger final syncs or session resets.
	 */
	public static boolean isLogout(GameState previous, GameState next) {
		boolean nextIsLogin = next == GameState.LOGIN_SCREEN || next == GameState.LOGIN_SCREEN_AUTHENTICATOR;
		boolean previousWasLogin = previous == GameState.LOGIN_SCREEN || previous == GameState.LOGIN_SCREEN_AUTHENTICATOR;
		return nextIsLogin && !previousWasLogin;
	}

	public static String getPlayerUsername(Client client) {
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null) {
			return null;
		}
		String name = localPlayer.getName();
		if (name == null || name.isBlank()) {
			return null;
		}
		return name;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.CollectionLogSyncPayload;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's Collection Log and syncs obtained items to the Mystix API.
 *
 * <p>Since the 2023 collection log rework, obtained items are only materialised
 * when the collection log interface is drawn — there is no clean login-time read.
 * So the first time the player opens their collection log each session we replicate
 * WikiSync's technique: trigger the in-log "search" ({@link #SEARCH_SCRIPT}), which
 * forces the draw script ({@link #DRAW_SCRIPT}) to fire for every obtained item.
 * Each fire carries the item id and its obtained quantity on the argument stack
 * (args[1] and args[2]), so we collect both and push them. After that,
 * {@link #DRAW_SCRIPT} keeps firing for new-item unlocks, so incremental obtains
 * flow in real time. A final deduped sync runs on logout. No manual button, no
 * per-page clicking.
 */
@Slf4j
@Singleton
public class CollectionLogMonitor {
	// Fired once the collection log interface has been built/opened.
	private static final int SETUP_SCRIPT = 7797;
	// Fired once per obtained item as the collection log draws its list.
	private static final int DRAW_SCRIPT = 4100;
	// The in-log "search all" script; forces a full draw of every obtained item.
	private static final int SEARCH_SCRIPT = 2240;
	// Submit two ticks after the last draw script fires (lets the burst settle).
	private static final int SYNC_DELAY_TICKS = 2;

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final Gson gson;

	// Obtained item id -> its in-game obtained quantity, captured from the draw
	// script (args[1] = item id, args[2] = quantity).
	private final Map<Integer, Integer> obtainedQuantityByItemId = new HashMap<>();
	private GameState previousGameState = GameState.UNKNOWN;
	private boolean captureActive;
	private boolean fullReadTriggeredThisSession;
	private int tickScriptFired = -1;
	private String lastSyncJson;

	@Inject
	public CollectionLogMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.gson = gson;
	}

	/** Invoked after each upload so roadmap progress can be re-read; set by the plugin. */
	private volatile Runnable syncedListener;

	public void setSyncedListener(Runnable listener) {
		this.syncedListener = listener;
	}

	private void notifySynced() {
		Runnable listener = syncedListener;
		if (listener != null) {
			listener.run();
		}
	}

	/** Receives (item id, quantity) for newly obtained collection log items; set by the plugin. */
	private volatile BiConsumer<Integer, Integer> obtainedListener;

	public void setObtainedListener(BiConsumer<Integer, Integer> listener) {
		this.obtainedListener = listener;
	}

	public void stop() {
		resetSessionState();
		previousGameState = GameState.UNKNOWN;
		lastSyncJson = null;
	}

	/**
	 * Re-pushes the currently captured collection log on the client thread. Used
	 * by the roadmap panel's "Sync &amp; refresh". A no-op until the log has been
	 * opened at least once this session (nothing is captured before then).
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncCollectionLog();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState state = event.getGameState();
		switch (state) {
			case LOGGED_IN:
				if (previousGameState != GameState.LOGGED_IN) {
					// Fresh login: capture from now so real-time unlocks are caught
					// even before the player opens their log.
					resetSessionState();
					captureActive = true;
				}
				break;
			case HOPPING:
			case LOGGING_IN:
			case CONNECTION_LOST:
				// Clear per-account state; the next login re-enumerates on log open.
				resetSessionState();
				break;
			default:
				if (previousGameState == GameState.LOGGED_IN) {
					// Logging out: flush whatever we captured, then reset.
					syncCollectionLog();
					resetSessionState();
				}
				break;
		}
		previousGameState = state;
	}

	/**
	 * The collection log interface just finished setup. The first time this happens
	 * in a session, force a full read of every obtained item.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		if (event.getScriptId() != SETUP_SCRIPT) {
			return;
		}
		if (!config.syncCollectionLog() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (fullReadTriggeredThisSession) {
			return;
		}
		fullReadTriggeredThisSession = true;
		captureActive = true;
		clientThread.invokeLater(this::triggerFullRead);
	}

	/**
	 * Each obtained item the collection log draws fires this script with the item id
	 * (args[1]) and its obtained quantity (args[2]) on the argument stack. Captures
	 * both the full-read burst and single-item real-time unlocks.
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		if (event.getScriptId() != DRAW_SCRIPT || !captureActive) {
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args == null || args.length < 2 || !(args[1] instanceof Integer)) {
			return;
		}
		int itemId = (Integer) args[1];
		int quantity = args.length > 2 && args[2] instanceof Integer ? (Integer) args[2] : 0;
		Integer previous = obtainedQuantityByItemId.put(itemId, quantity);
		BiConsumer<Integer, Integer> listener = obtainedListener;
		if (listener != null && quantity > 0 && (previous == null || quantity > previous)) {
			listener.accept(itemId, quantity);
		}
		tickScriptFired = client.getTickCount();
	}

	/**
	 * Submit shortly after the last draw-script fire so the whole burst is captured
	 * in one payload (mirrors WikiSync's two-tick settle).
	 */
	@Subscribe
	public void onGameTick(GameTick event) {
		if (tickScriptFired == -1 || tickScriptFired + SYNC_DELAY_TICKS > client.getTickCount()) {
			return;
		}
		tickScriptFired = -1;
		syncCollectionLog();
	}

	/** Opens the in-log search and runs it, forcing a draw of every obtained item. */
	private void triggerFullRead() {
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(SEARCH_SCRIPT);
	}

	private void syncCollectionLog() {
		if (!config.syncCollectionLog() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null || obtainedQuantityByItemId.isEmpty()) {
			return;
		}

		List<Integer> sortedIds = new ArrayList<>(obtainedQuantityByItemId.keySet());
		Collections.sort(sortedIds);
		// TreeMap gives a stable JSON key order so the dedup check is reliable.
		Map<Integer, Integer> quantities = new TreeMap<>(obtainedQuantityByItemId);
		CollectionLogSyncPayload payload =
				new CollectionLogSyncPayload(playerUsername, sortedIds, quantities);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Collection log unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing {} collection log items for player: {}", sortedIds.size(), playerUsername);
		apiClient.sendCollectionLogSync(payload);
		notifySynced();
	}

	private void resetSessionState() {
		obtainedQuantityByItemId.clear();
		captureActive = false;
		fullReadTriggeredThisSession = false;
		tickScriptFired = -1;
	}
}

package com.mystix;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * App-style progress bar for the goal overlay: a thin rounded bar with a
 * "current / target" label beneath it and an optional right-aligned percent.
 *
 * <p>RuneLite's {@code ProgressBarComponent} is fixed at 16px with square corners
 * and the label inside the bar, so it cannot match the app's look; this draws the
 * 6px pill the app uses instead.
 */
final class GoalProgressBarComponent implements LayoutableRenderableEntity {
	static final int TOP_GAP = 4;
	static final int BAR_HEIGHT = 6;
	static final int BAR_TEXT_GAP = 3;
	static final int PERCENT_GAP = 8;

	static final Color TRACK = new Color(0, 0, 0, 110);
	static final Color FILL = new Color(0x25, 0x63, 0xEB);
	static final Color LABEL = new Color(0xC6, 0xC6, 0xC6);

	private final double fraction;
	private final String label;
	private final String percent;

	private Point preferredLocation = new Point();
	private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, 0);
	private final Rectangle bounds = new Rectangle();

	/**
	 * @param fraction bar fill in [0, 1]
	 * @param label    text drawn under the bar, e.g. "12.4K XP / 100K XP"
	 * @param percent  right-aligned text, e.g. "12%", or null to omit
	 */
	GoalProgressBarComponent(double fraction, String label, String percent) {
		this.fraction = Math.max(0, Math.min(1, fraction));
		this.label = label == null ? "" : label;
		this.percent = percent;
	}

	@Override
	public Dimension render(Graphics2D g) {
		final int x = preferredLocation.x;
		final int barY = preferredLocation.y + TOP_GAP;
		final int width = preferredSize.width;
		final FontMetrics fm = g.getFontMetrics();

		Object oldAa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(TRACK);
		g.fillRoundRect(x, barY, width, BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
		int fill = (int) Math.round(width * fraction);
		if (fill > 0) {
			g.setColor(FILL);
			// Never narrower than the corner diameter so a 1% bar is still a pill.
			g.fillRoundRect(x, barY, Math.min(width, Math.max(fill, BAR_HEIGHT)), BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
		}
		if (oldAa != null) {
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAa);
		}

		int textBaseline = barY + BAR_HEIGHT + BAR_TEXT_GAP + fm.getAscent();
		TextComponent text = new TextComponent();
		text.setText(label);
		text.setColor(LABEL);
		text.setPosition(new Point(x, textBaseline));
		text.render(g);

		if (percent != null) {
			int pw = fm.stringWidth(percent);
			if (fm.stringWidth(label) + PERCENT_GAP + pw <= width) {
				TextComponent pct = new TextComponent();
				pct.setText(percent);
				pct.setColor(LABEL);
				pct.setPosition(new Point(x + width - pw, textBaseline));
				pct.render(g);
			}
		}

		int height = TOP_GAP + BAR_HEIGHT + BAR_TEXT_GAP + fm.getHeight();
		bounds.setBounds(x, preferredLocation.y, width, height);
		return new Dimension(width, height);
	}

	/** Width needed so the label (and percent) fit on one line. */
	int minWidth(FontMetrics fm) {
		int w = fm.stringWidth(label);
		if (percent != null) {
			w += PERCENT_GAP + fm.stringWidth(percent);
		}
		return w;
	}

	@Override
	public Rectangle getBounds() {
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point position) {
		this.preferredLocation = position;
	}

	@Override
	public void setPreferredSize(Dimension dimension) {
		this.preferredSize = dimension;
	}
}

package com.mystix;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * In-memory cache of goal artwork (OSRS Wiki images for bosses, combat tasks
 * and the like), scaled to overlay icon size. Only images on the hardcoded
 * {@link #WIKI_HOST} are fetched; any other URL the server sends is ignored,
 * so the plugin never contacts a host taken from a server response. Images are
 * fetched once per URL on the background executor; until one arrives
 * {@link #get} returns null and the overlay simply draws no icon. Failed URLs
 * are not retried for the rest of the session.
 */
@Slf4j
@Singleton
public class GoalImageCache {
	/** Icons are scaled to fit this square, matching RuneLite's item sprites. */
	static final int ICON_SIZE = 32;
	private static final int FETCH_TIMEOUT_SECONDS = 10;
	/** The only host goal images are fetched from. */
	static final String WIKI_HOST = "oldschool.runescape.wiki";
	private static final String WIKI_IMAGE_PATH = "/images/";

	private final OkHttpClient httpClient;
	private final ScheduledExecutorService executorService;

	private final Map<String, BufferedImage> images = new ConcurrentHashMap<>();
	private final Set<String> pending = ConcurrentHashMap.newKeySet();
	private final Set<String> failed = ConcurrentHashMap.newKeySet();

	@Inject
	public GoalImageCache(OkHttpClient okHttpClient, ScheduledExecutorService executorService) {
		this.httpClient = okHttpClient.newBuilder()
				.callTimeout(FETCH_TIMEOUT_SECONDS, TimeUnit.SECONDS)
				.build();
		this.executorService = executorService;
	}

	/**
	 * The scaled image for a URL if it has been loaded; otherwise starts loading
	 * it (once) and returns null. Safe to call every render frame.
	 */
	public BufferedImage get(String url) {
		if (!isAllowed(url)) {
			return null;
		}
		BufferedImage cached = images.get(url);
		if (cached != null) {
			return cached;
		}
		if (!failed.contains(url) && pending.add(url)) {
			executorService.execute(() -> fetch(url));
		}
		return null;
	}

	/** True when the URL is an https image on the OSRS Wiki. */
	static boolean isAllowed(String url) {
		HttpUrl parsed = url == null ? null : HttpUrl.parse(url);
		return parsed != null
				&& parsed.isHttps()
				&& WIKI_HOST.equals(parsed.host())
				&& parsed.port() == 443
				&& parsed.encodedPath().startsWith(WIKI_IMAGE_PATH);
	}

	public void clear() {
		images.clear();
		pending.clear();
		failed.clear();
	}

	private void fetch(String url) {
		try {
			Request request = new Request.Builder().url(url).get().build();
			try (Response response = httpClient.newCall(request).execute()) {
				if (!response.isSuccessful() || response.body() == null) {
					log.debug("Goal image fetch failed ({}): {}", response.code(), url);
					failed.add(url);
					return;
				}
				try (InputStream in = response.body().byteStream()) {
					BufferedImage image = ImageIO.read(in);
					if (image == null) {
						log.debug("Goal image not decodable: {}", url);
						failed.add(url);
						return;
					}
					images.put(url, fit(image));
				}
			}
		} catch (IOException | RuntimeException e) {
			log.debug("Goal image fetch error for {}: {}", url, e.toString());
			failed.add(url);
		} finally {
			pending.remove(url);
		}
	}

	/** Scales the image down to fit the icon square, keeping its aspect ratio. */
	static BufferedImage fit(BufferedImage image) {
		int w = image.getWidth();
		int h = image.getHeight();
		if (w <= ICON_SIZE && h <= ICON_SIZE) {
			return image;
		}
		double scale = Math.min((double) ICON_SIZE / w, (double) ICON_SIZE / h);
		int nw = Math.max(1, (int) Math.round(w * scale));
		int nh = Math.max(1, (int) Math.round(h * scale));
		return ImageUtil.resizeImage(image, nw, nh);
	}
}

package com.mystix;

import com.mystix.model.GoalType;
import java.util.EnumSet;
import java.util.Set;

/**
 * A kind of upload the server evaluates roadmap goals against. After an upload
 * the roadmap is only worth re-reading when it has an unfinished goal of a type
 * that upload can move: a bank upload cannot change quest progress, and loot
 * cannot change a net worth goal.
 */
enum SyncSource {
	LOOT(GoalType.KC, GoalType.ITEM_QUANTITY, GoalType.NPC_DROP, GoalType.CLOG_ITEM),
	COLLECTION_LOG(GoalType.NPC_DROP, GoalType.CLOG_ITEM),
	QUESTS(GoalType.QUEST),
	DIARIES(GoalType.DIARY_TASK),
	COMBAT_ACHIEVEMENTS(GoalType.COMBAT_ACHIEVEMENT),
	KILL_COUNTS(GoalType.KC),
	TIMERS(GoalType.FARMING_TIMER, GoalType.TEARS_OF_GUTHIX),
	BANK(GoalType.ITEM_OWNED, GoalType.NET_WORTH);

	private final Set<GoalType> moves;

	SyncSource(GoalType first, GoalType... rest) {
		this.moves = EnumSet.of(first, rest);
	}

	/** Whether this upload can change a goal of {@code type}. Types this plugin
	 * version doesn't know (added on the server later) always count. */
	boolean affects(GoalType type) {
		return type == GoalType.UNKNOWN || moves.contains(type);
	}
}

package com.mystix;

import com.mystix.model.GoalType;
import com.mystix.model.RoadmapGoal;

/**
 * A goal's progress as the plugin currently believes it: the server's numbers
 * plus whatever the client has observed locally since. Immutable snapshot built
 * per read by {@link GoalProgressState}.
 */
public final class GoalProgressView {
	private final GoalType type;
	private final int current;
	private final int target;
	/** 0-100, or null for binary goals that have no progress bar. */
	private final Integer percent;
	private final boolean complete;

	GoalProgressView(GoalType type, int current, int target, Integer percent, boolean complete) {
		this.type = type;
		this.current = current;
		this.target = target;
		this.percent = percent;
		this.complete = complete;
	}

	/** The server's view of a goal, untouched by local tracking. */
	public static GoalProgressView fromServer(RoadmapGoal goal) {
		Integer percent = goal.getProgressPercent();
		if (goal.isComplete() && percent != null) {
			percent = 100;
		}
		return new GoalProgressView(goal.getType(), goal.getCurrent(), goal.getTarget(), percent, goal.isComplete());
	}

	public GoalType getType() {
		return type;
	}

	public int getCurrent() {
		return current;
	}

	public int getTarget() {
		return target;
	}

	public Integer getPercent() {
		return percent;
	}

	public boolean isComplete() {
		return complete;
	}

	/** True when this goal is drawn with a progress bar. */
	public boolean isMeasurable() {
		return percent != null;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.QuestsSyncPayload;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's quest progress and syncs it to the Mystix API.
 *
 * <p>Reads every quest's state via RuneLite's {@link Quest} enum + {@link QuestState}
 * (the same source WikiSync uses) and pushes a {questName: status} map where status is
 * 0 = not started, 1 = in progress, 2 = completed. Using {@link Quest#getName()} for the
 * keys reproduces WikiSync's exact names (including the Recipe for Disaster subquests),
 * so the backend consumes the payload unchanged.
 *
 * <p>Triggers: a sync on login (after a short delay so quest varps have loaded) and on
 * logout, plus a near-real-time sync when a quest completes. Quest state changes flip a
 * varp, so we mark a re-check on {@link VarbitChanged} and read+dedupe on the next
 * {@link GameTick} (throttled), which collapses varp churn to at most one read per few
 * ticks. A JSON equality check means an unchanged quest set is never resent.
 *
 * <p>A quest RuneLite's {@link Quest} enum doesn't list yet (a brand-new release) is
 * invisible to that read, so two more sources fill the gap. The game builds its quest
 * list from a database table and RuneLite's client fires a {@code questFilter} script
 * callback for each row it lays out; the row ids collected there give every quest's
 * display name and, through the same script the enum uses, its state. And the
 * quest-complete scroll names any quest as it finishes, so a name read from it is
 * carried as completed for the rest of the login session. The scroll text is parsed
 * the way RuneLite's own screenshot plugin parses it.
 */
@Slf4j
@Singleton
public class QuestMonitor {
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	// Minimum ticks between varp-driven reads, so continuous varp churn during play
	// doesn't re-read every quest every tick. A quest completion still syncs within
	// a few ticks, and login/logout syncs are the safety net.
	private static final int RESYNC_THROTTLE_TICKS = 3;

	// "You have completed The Corsair Curse!" / "'One Small Favour' completed!"
	private static final Pattern QUEST_PATTERN_1 = Pattern.compile(
			".+?ve\\.*? (?<verb>been|rebuilt|.+?ed)? ?(?:the )?'?(?<quest>.+?)'?(?: [Qq]uest)?[!.]?$");
	private static final Pattern QUEST_PATTERN_2 = Pattern.compile(
			"'?(?<quest>.+?)'?(?: [Qq]uest)? (?<verb>[a-z]\\w+?ed)?(?: f.*?)?[!.]?$");
	// Recipe for Disaster subquests announce "You have freed/defeated/saved ...".
	private static final List<String> RFD_TAGS = Arrays.asList("Another Cook", "freed", "defeated", "saved");
	// Quests whose name ends in "Quest", which the patterns strip.
	private static final List<String> WORD_QUEST_IN_NAME_TAGS = Arrays.asList(
			"Another Cook", "Doric", "Heroes", "Legends", "Observatory", "Olaf", "Waterfall");

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean questCheckPending;
	private boolean questScrollPending;
	/** Quest names read from the quest-complete scroll this login session. */
	private final Set<String> completedFromScroll = new HashSet<>();
	/** Quest table row ids seen while the game laid out its quest list. */
	private final Set<Integer> questRows = new HashSet<>();
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public QuestMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ScheduledExecutorService executorService,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executorService = executorService;
		this.gson = gson;
	}

	/** Receives every quest read (RuneLite quest name to status 0/1/2); set by the plugin. */
	private volatile Consumer<Map<String, Integer>> statesListener;

	public void setStatesListener(Consumer<Map<String, Integer>> listener) {
		this.statesListener = listener;
	}

	/** Invoked after each upload so roadmap progress can be re-read; set by the plugin. */
	private volatile Runnable syncedListener;

	public void setSyncedListener(Runnable listener) {
		this.syncedListener = listener;
	}

	private void notifySynced() {
		Runnable listener = syncedListener;
		if (listener != null) {
			listener.run();
		}
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		questCheckPending = false;
		questScrollPending = false;
		completedFromScroll.clear();
		questRows.clear();
		lastReadTick = -1;
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the current quest states on the client thread. Used by the
	 * roadmap panel's "Sync &amp; refresh"; clears the dedup cache so an unchanged set
	 * still sends.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncQuests();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			// Quest varps load shortly after LOGGED_IN, so wait before reading.
			executorService.schedule(() -> clientThread.invokeLater(this::syncQuests),
					LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			// Logging out: flush final state (this handler runs on the client thread).
			syncQuests();
		}
		if (newState == GameState.LOGIN_SCREEN) {
			// Scroll completions belong to the account that was logged in.
			completedFromScroll.clear();
		}
		previousGameState = newState;
	}

	/**
	 * The game lays out its quest list from the quest table, and RuneLite's client
	 * calls back once per row with the row id on top of the int stack (the row below it
	 * is the hide flag, left untouched). Rows are only collected here; names and states
	 * are read on the next sync.
	 */
	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event) {
		if (!"questFilter".equals(event.getEventName())) {
			return;
		}
		int[] intStack = client.getIntStack();
		int size = client.getIntStackSize();
		if (size < 1) {
			return;
		}
		if (questRows.add(intStack[size - 1])) {
			questCheckPending = true;
		}
	}

	/** The quest-complete scroll opened; read its title once its text is set. */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		if (event.getGroupId() == InterfaceID.QUESTSCROLL) {
			questScrollPending = true;
		}
	}

	/** A quest state change flips a varp; mark a re-check for the next game tick. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		questCheckPending = true;
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (questScrollPending) {
			questScrollPending = false;
			readQuestScroll();
		}
		if (!questCheckPending) {
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
			return;
		}
		questCheckPending = false;
		lastReadTick = client.getTickCount();
		syncQuests();
	}

	/** Reads the quest name off the quest-complete scroll and syncs it as completed. */
	private void readQuestScroll() {
		Widget title = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
		String name = title == null ? null : parseQuestCompletedScroll(title.getText());
		if (name == null) {
			return;
		}
		log.debug("Quest complete scroll names '{}'", name);
		if (completedFromScroll.add(name)) {
			questCheckPending = false;
			lastReadTick = client.getTickCount();
			syncQuests();
		}
	}

	/**
	 * The quest named by the quest-complete scroll's title text, or null when the text
	 * isn't a completion. Mirrors RuneLite's screenshot plugin: Recipe for Disaster
	 * subquests are prefixed, and names the scroll shortens get their "Quest" back.
	 */
	static String parseQuestCompletedScroll(String text) {
		if (text == null) {
			return null;
		}
		Matcher m1 = QUEST_PATTERN_1.matcher(text);
		Matcher m2 = QUEST_PATTERN_2.matcher(text);
		Matcher match = m1.matches() ? m1 : m2;
		if (!match.matches()) {
			return null;
		}
		String quest = match.group("quest");
		String verb = match.group("verb") != null ? match.group("verb") : "";
		if (verb.contains("kind of")) {
			return null; // a partial completion is not a completion
		}
		if (verb.contains("completely")) {
			quest += " II";
		}
		String questAndVerb = quest + verb;
		if (RFD_TAGS.stream().anyMatch(questAndVerb::contains)) {
			quest = "Recipe for Disaster - " + quest;
		}
		if (WORD_QUEST_IN_NAME_TAGS.stream().anyMatch(quest::contains)) {
			quest += " Quest";
		}
		return quest;
	}

	/** Reads all quest states, builds the payload, and syncs (deduped). Client thread only. */
	private void syncQuests() {
		if (!config.syncQuests() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}

		// Sorted keys give a stable JSON ordering so the dedup check is reliable.
		Map<String, Integer> questStates = new TreeMap<>();
		for (Quest quest : Quest.values()) {
			questStates.put(quest.getName(), toStatus(quest.getState(client)));
		}
		// Quests the enum doesn't list, read from the game's own quest table; the
		// enum's read wins for names it has.
		for (int row : questRows) {
			String name = questRowName(row);
			if (name != null && !questStates.containsKey(name)) {
				questStates.put(name, questRowStatus(row));
			}
		}
		// Completions the enum can't see yet; the enum's own read wins for names it has.
		for (String name : completedFromScroll) {
			questStates.putIfAbsent(name, 2);
		}

		Consumer<Map<String, Integer>> states = statesListener;
		if (states != null) {
			states.accept(questStates);
		}

		QuestsSyncPayload payload = new QuestsSyncPayload(playerUsername, questStates);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Quests unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing {} quests for player: {}", questStates.size(), playerUsername);
		apiClient.sendQuestsSync(payload);
		notifySynced();
	}

	/** A quest row's display name, or null when the row can't be read. */
	private String questRowName(int row) {
		try {
			Object[] field = client.getDBTableField(row, DBTableID.Quest.COL_DISPLAYNAME, 0);
			return field != null && field.length > 0 && field[0] instanceof String ? (String) field[0] : null;
		} catch (RuntimeException e) {
			log.debug("Quest row {} has no readable name", row, e);
			return null;
		}
	}

	/** A quest row's status (0/1/2), read the same way {@link Quest#getState} does. */
	private int questRowStatus(int row) {
		client.runScript(ScriptID.QUEST_STATUS_GET, row);
		return statusFromScript(client.getIntStack()[0]);
	}

	/**
	 * Maps the raw {@code QUEST_STATUS_GET} result to the WikiSync status code, mirroring
	 * {@link Quest#getState}: 2 is finished, 1 is not started, anything else in progress.
	 */
	static int statusFromScript(int raw) {
		if (raw == 2) {
			return 2;
		}
		return raw == 1 ? 0 : 1;
	}

	/** Maps a RuneLite {@link QuestState} to the WikiSync status code (0/1/2). */
	private static int toStatus(QuestState state) {
		if (state == QuestState.FINISHED) {
			return 2;
		}
		if (state == QuestState.IN_PROGRESS) {
			return 1;
		}
		return 0;
	}
}

package com.mystix;

import com.google.gson.Gson;
import com.mystix.api.MystixApiClient;
import com.mystix.model.KillCountsSyncPayload;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Monitors the player's boss kill counts and syncs them to the Mystix API.
 *
 * <p>Reads RuneLite's persisted {@code killcount} RSProfile config — the store the
 * in-game {@code !kc} command reads, which RuneLite populates from the game's own
 * kill-count chat messages. That makes it the accurate, self-correcting count
 * (unlike loot-tracker-derived KC) and lets us pull the player's whole KC history
 * in one read, instead of waiting to witness a kill.
 *
 * <p>Triggers: a sync on login (after a delay so the RSProfile is resolved) and on
 * logout, plus a near-real-time sync when a kill count changes. RuneLite rewrites
 * the config on each kill, firing {@link ConfigChanged}; we mark a re-check and
 * read + dedupe on the next {@link GameTick} (throttled). A JSON equality check
 * means an unchanged set is never resent.
 */
@Slf4j
@Singleton
public class KillCountMonitor {
	private static final String KILLCOUNT_GROUP = "killcount";
	// The RSProfile is set a little after LOGGED_IN, so wait before the first read.
	private static final int LOGIN_SYNC_DELAY_SECONDS = 5;
	private static final int RESYNC_THROTTLE_TICKS = 3;
	// killcount keys that aren't boss KCs (Duel Arena win/loss/streak counters).
	private static final String DUEL_ARENA_PREFIX = "duel arena";

	private final Client client;
	private final ClientThread clientThread;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executorService;
	private final Gson gson;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean kcCheckPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public KillCountMonitor(
			Client client,
			ClientThread clientThread,
			MystixConfig config,
			MystixApiClient apiClient,
			ConfigManager configManager,
			ScheduledExecutorService executorService,
			Gson gson) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
		this.executorService = executorService;
		this.gson = gson;
	}

	/** Invoked after each upload so roadmap progress can be re-read; set by the plugin. */
	private volatile Runnable syncedListener;

	public void setSyncedListener(Runnable listener) {
		this.syncedListener = listener;
	}

	private void notifySynced() {
		Runnable listener = syncedListener;
		if (listener != null) {
			listener.run();
		}
	}

	public void stop() {
		previousGameState = GameState.UNKNOWN;
		kcCheckPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	/**
	 * Re-reads and re-pushes the stored kill counts on the client thread. Used by the
	 * roadmap panel's "Sync &amp; refresh"; clears the dedup cache so an unchanged set
	 * still sends.
	 */
	public void forceSync() {
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncKillCounts();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			// The RSProfile the kill counts live under is resolved shortly after login.
			executorService.schedule(() -> clientThread.invokeLater(this::syncKillCounts),
					LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		} else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN) {
			// Logging out: flush final state (this handler runs on the client thread).
			syncKillCounts();
		}
		previousGameState = newState;
	}

	/** RuneLite rewrites a killcount config key on each kill; mark a re-check. */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (KILLCOUNT_GROUP.equals(event.getGroup())) {
			kcCheckPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		if (!kcCheckPending) {
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS) {
			return;
		}
		kcCheckPending = false;
		lastReadTick = client.getTickCount();
		syncKillCounts();
	}

	/** Reads RuneLite's stored kill counts, builds the payload, and syncs (deduped). */
	private void syncKillCounts() {
		if (!config.syncKillCounts() || !SyncGuard.hasAppKey(config)) {
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			return;
		}
		String profile = configManager.getRSProfileKey();
		if (profile == null) {
			return;  // RSProfile not resolved yet
		}

		// TreeMap gives a stable JSON key order so the dedup check is reliable.
		Map<String, Integer> killCounts = new TreeMap<>();
		for (String boss : configManager.getRSProfileConfigurationKeys(KILLCOUNT_GROUP, profile, "")) {
			if (boss == null || boss.startsWith(DUEL_ARENA_PREFIX)) {
				continue;
			}
			Integer kc = configManager.getRSProfileConfiguration(KILLCOUNT_GROUP, boss, int.class);
			if (kc != null) {
				killCounts.put(boss, kc);
			}
		}

		if (killCounts.isEmpty()) {
			return;
		}

		KillCountsSyncPayload payload = new KillCountsSyncPayload(playerUsername, killCounts);
		String json = payload.toJson(gson);

		if (json.equals(lastSyncJson)) {
			log.debug("Kill counts unchanged, skipping sync");
			return;
		}
		lastSyncJson = json;
		log.debug("Syncing {} kill counts for player: {}", killCounts.size(), playerUsername);
		apiClient.sendKillCountsSync(payload);
		notifySynced();
	}
}

package com.mystix;

import java.util.EnumSet;
import net.runelite.api.Client;
import net.runelite.api.WorldType;

/**
 * Shared utility for detecting special game modes that should not sync
 * to avoid data conflicts with main game progression.
 */
public final class GameModeUtil {

	private static final EnumSet<WorldType> SPECIAL_GAME_MODES = EnumSet.of(
			WorldType.SEASONAL,
			WorldType.DEADMAN,
			WorldType.FRESH_START_WORLD,
			WorldType.TOURNAMENT_WORLD,
			WorldType.BETA_WORLD,
			WorldType.NOSAVE_MODE,
			WorldType.QUEST_SPEEDRUNNING,
			// PvP Arena hands the player a temporary copy of their character
			// whose varps (quest states, diary varbits, slayer points) are not
			// the real account's.
			WorldType.PVP_ARENA);

	private GameModeUtil() {
	}

	/**
	 * Returns true if the player is on a special game mode world (Leagues, DMM,
	 * Fresh Start, Tournaments, Beta, Speedrunning, PvP Arena) where syncing
	 * should be skipped to avoid data conflicts with main game progression.
	 */
	public static boolean isSpecialGameMode(Client client) {
		EnumSet<WorldType> worldTypes = client.getWorldType();
		for (WorldType special : SPECIAL_GAME_MODES) {
			if (worldTypes.contains(special)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Returns true if the player is on a Leagues (seasonal) world but not Deadman mode.
	 * Used to adjust growth rates for farming timers.
	 */
	public static boolean isLeaguesWorld(Client client) {
		EnumSet<WorldType> worldTypes = client.getWorldType();
		return worldTypes.contains(WorldType.SEASONAL) && !worldTypes.contains(WorldType.DEADMAN);
	}
}

package com.mystix;

import com.mystix.api.MystixApiClient;
import com.mystix.model.Roadmap;
import com.mystix.model.RoadmapList;
import com.mystix.model.RoadmapSummary;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;

/**
 * Shared roadmap state for the side panel and the overlay.
 *
 * <p>Holds the currently selected roadmap id (persisted per RuneLite profile via
 * {@link ConfigManager}) and the last fetched {@link Roadmap}, so the panel and
 * the overlay render the same data without each issuing their own requests. All
 * mutation happens through here; the panel drives fetches, the overlay reads the
 * cached roadmap.
 *
 * <p>Also owns the background reconciliation: a periodic re-read of every one
 * of the player's roadmaps plus debounced re-reads requested shortly after data
 * uploads, so the server's view of goal progress reaches the plugin without the
 * panel open. Every fetched roadmap is handed to the roadmap listener (the goal
 * tracker); only the selected one becomes the overlay's current roadmap.
 */
@Slf4j
@Singleton
public class RoadmapManager {
	static final String CONFIG_GROUP = "mystix";
	static final String SELECTED_ROADMAP_KEY = "selectedRoadmapId";
	static final String COMPLETED_EXPANDED_KEY = "completedGoalsExpanded";

	private final Client client;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ConfigManager configManager;
	private final ReconcileScheduler scheduler;
	private final RoadmapListCache listCache = new RoadmapListCache();

	private volatile Roadmap currentRoadmap;
	/** Hears every fetched roadmap, selected or not; set by the plugin. */
	private volatile Consumer<Roadmap> roadmapListener;
	/** Hears the player's current set of roadmap ids after each list fetch. */
	private volatile Consumer<Set<Integer>> roadmapSetListener;
	/** Hears roadmaps that arrived from a background refresh; set by the open panel. */
	private volatile Consumer<Roadmap> panelListener;
	private volatile boolean panelActive;

	@Inject
	public RoadmapManager(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			ConfigManager configManager,
			ScheduledExecutorService executorService) {
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
		this.scheduler = new ReconcileScheduler(executorService, this::refreshAllQuietly);
	}

	/** The logged-in RS username, or null if not logged in. */
	public String getPlayerUsername() {
		return SyncGuard.getPlayerUsername(client);
	}

	public boolean hasAppKey() {
		return SyncGuard.hasAppKey(config);
	}

	/** The last fetched roadmap (may be null), used by the overlay. */
	public Roadmap getCurrentRoadmap() {
		return currentRoadmap;
	}

	void setCurrentRoadmap(Roadmap roadmap) {
		this.currentRoadmap = roadmap;
	}

	void clear() {
		setCurrentRoadmap(null);
		listCache.invalidate();
	}

	public void setRoadmapListener(Consumer<Roadmap> listener) {
		this.roadmapListener = listener;
	}

	public void setRoadmapSetListener(Consumer<Set<Integer>> listener) {
		this.roadmapSetListener = listener;
	}

	/** Every fetched roadmap goes to the tracker; the selected one also becomes current. */
	private void onRoadmapFetched(Roadmap roadmap) {
		Consumer<Roadmap> listener = roadmapListener;
		if (listener != null) {
			listener.accept(roadmap);
		}
		Integer selected = getSelectedRoadmapId();
		if (selected != null && selected == roadmap.getCollectionId()) {
			setCurrentRoadmap(roadmap);
		}
	}

	/**
	 * Makes a roadmap the active one (a goal in it just completed): persists the
	 * selection, swaps the overlay's roadmap and lets an open panel follow.
	 */
	public void selectRoadmap(Roadmap roadmap) {
		if (roadmap == null) {
			return;
		}
		Integer selected = getSelectedRoadmapId();
		if (selected == null || selected != roadmap.getCollectionId()) {
			log.debug("Switching active roadmap to {}", roadmap.getTitle());
			setSelectedRoadmapId(roadmap.getCollectionId());
		}
		setCurrentRoadmap(roadmap);
	}

	public void setPanelListener(Consumer<Roadmap> listener) {
		this.panelListener = listener;
	}

	/** Asks an open panel to re-render the cached roadmap (local progress changed). */
	public void notifyPanel() {
		Roadmap roadmap = currentRoadmap;
		Consumer<Roadmap> listener = panelListener;
		if (roadmap != null && listener != null) {
			listener.accept(roadmap);
		}
	}

	/** Whether the side panel is open; background refreshes run while it is. */
	public void setPanelActive(boolean active) {
		this.panelActive = active;
	}

	public Integer getSelectedRoadmapId() {
		return configManager.getConfiguration(
				CONFIG_GROUP, SELECTED_ROADMAP_KEY, Integer.class);
	}

	public void setSelectedRoadmapId(int collectionId) {
		configManager.setConfiguration(CONFIG_GROUP, SELECTED_ROADMAP_KEY, collectionId);
	}

	/** Whether the panel's "Completed (N)" list is expanded; collapsed by default. */
	public boolean isCompletedGoalsExpanded() {
		Boolean expanded = configManager.getConfiguration(
				CONFIG_GROUP, COMPLETED_EXPANDED_KEY, Boolean.class);
		return expanded != null && expanded;
	}

	public void setCompletedGoalsExpanded(boolean expanded) {
		configManager.setConfiguration(CONFIG_GROUP, COMPLETED_EXPANDED_KEY, expanded);
	}

	/**
	 * Fetches the player's roadmap list. The callback runs on the OkHttp thread;
	 * Swing callers must marshal back to the EDT themselves.
	 */
	public void fetchRoadmaps(MystixApiClient.RoadmapCallback<RoadmapList> callback) {
		String player = getPlayerUsername();
		if (player == null) {
			callback.onError("Log in to load your roadmaps");
			return;
		}
		apiClient.getRoadmaps(player, new MystixApiClient.RoadmapCallback<RoadmapList>() {
			@Override
			public void onSuccess(RoadmapList result) {
				// Keep the tracker aware of every roadmap, not just the one the
				// panel is about to open.
				onRoadmapListFetched(result, player, null);
				callback.onSuccess(result);
			}

			@Override
			public void onError(String message) {
				callback.onError(message);
			}
		});
	}

	/**
	 * Tells the tracker which roadmaps exist and fetches each one that the caller
	 * is not already fetching itself, so goals in every roadmap are tracked.
	 *
	 * @param skipId roadmap the caller fetches on its own (may be null)
	 * @param onDone runs once every fetch has finished (may be null)
	 */
	private void onRoadmapListFetched(RoadmapList list, String player, Runnable onDone) {
		List<RoadmapSummary> summaries = list.getRoadmaps();
		listCache.record(player, summaries, System.currentTimeMillis());
		Set<Integer> ids = new HashSet<>();
		for (RoadmapSummary summary : summaries) {
			ids.add(summary.getCollectionId());
		}
		Consumer<Set<Integer>> setListener = roadmapSetListener;
		if (setListener != null) {
			setListener.accept(ids);
		}
		if (getSelectedRoadmapId() == null && !summaries.isEmpty()) {
			setSelectedRoadmapId(summaries.get(0).getCollectionId());
		}
		fetchEach(summaries, player, onDone);
	}

	/** Fetches each roadmap and feeds it to the tracker; {@code onDone} runs once
	 * all have finished. A failed read drops the cached list (the roadmap may be
	 * gone), so the next refresh fetches the list again. */
	private void fetchEach(List<RoadmapSummary> summaries, String player, Runnable onDone) {
		if (summaries.isEmpty()) {
			if (onDone != null) {
				onDone.run();
			}
			return;
		}
		AtomicInteger remaining = new AtomicInteger(summaries.size());
		for (RoadmapSummary summary : summaries) {
			apiClient.getRoadmap(summary.getCollectionId(), player, new MystixApiClient.RoadmapCallback<Roadmap>() {
				@Override
				public void onSuccess(Roadmap result) {
					onRoadmapFetched(result);
					finish();
				}

				@Override
				public void onError(String message) {
					log.debug("Roadmap {} refresh failed: {}", summary.getCollectionId(), message);
					listCache.invalidate();
					finish();
				}

				private void finish() {
					if (remaining.decrementAndGet() == 0 && onDone != null) {
						onDone.run();
					}
				}
			});
		}
	}

	/**
	 * Fetches one roadmap fully rendered and caches it as the current roadmap on
	 * success (so the overlay picks it up). The callback also fires.
	 */
	public void fetchRoadmap(int collectionId, MystixApiClient.RoadmapCallback<Roadmap> callback) {
		String player = getPlayerUsername();
		if (player == null) {
			callback.onError("Log in to load your roadmap");
			return;
		}
		apiClient.getRoadmap(collectionId, player, cacheThen(collectionId, callback));
	}

	/**
	 * Manually marks a goal complete on the backend and caches the re-rendered
	 * roadmap (so the overlay's next goal updates too). The callback runs on the
	 * OkHttp thread; Swing callers marshal back to the EDT themselves.
	 */
	public void completeGoal(int collectionId, int goalId,
			MystixApiClient.RoadmapCallback<Roadmap> callback) {
		String player = getPlayerUsername();
		if (player == null) {
			callback.onError("Log in to update your roadmap");
			return;
		}
		apiClient.completeRoadmapGoal(collectionId, goalId, player, cacheThen(collectionId, callback));
	}

	/**
	 * Deletes a goal from the backend and caches the re-rendered roadmap (so the
	 * overlay's next goal updates too). Callback runs on the OkHttp thread.
	 */
	public void deleteGoal(int collectionId, int goalId,
			MystixApiClient.RoadmapCallback<Roadmap> callback) {
		String player = getPlayerUsername();
		if (player == null) {
			callback.onError("Log in to update your roadmap");
			return;
		}
		apiClient.deleteRoadmapGoal(collectionId, goalId, player, cacheThen(collectionId, callback));
	}

	// ------------------------------------------------------- reconciliation

	/** Starts the periodic background re-read of the selected roadmap. */
	public void startPeriodicRefresh() {
		scheduler.startPeriodic();
	}

	public void stopPeriodicRefresh() {
		scheduler.stop();
	}

	/** Re-reads every roadmap after a short lag (debounced). */
	public void requestReconcile(int delaySeconds) {
		scheduler.request(delaySeconds);
		notifyPanel(); // so server-driven goals can show their syncing state
	}

	/** True while a server re-read is running or about to (drives "Syncing" hints). */
	public boolean isSyncing() {
		return scheduler.isSyncingSoon();
	}

	/**
	 * Refreshes every roadmap silently (no UI callback): the list (reused while
	 * recent, see {@link RoadmapListCache}), then each roadmap's rendered goals.
	 * Runs on login, on the periodic schedule and after uploads that can move a
	 * goal, so goal progress in any roadmap reaches the plugin even when the
	 * panel is closed. A plain GET re-evaluates goals server-side, so no
	 * recompute call is needed.
	 */
	public void refreshAllQuietly() {
		if (!hasAppKey() || (!config.showNextGoal() && !panelActive)) {
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN || GameModeUtil.isSpecialGameMode(client)) {
			return;
		}
		String player = getPlayerUsername();
		if (player == null) {
			return;
		}
		if (!scheduler.markInFlight()) {
			log.debug("Quiet roadmap refresh skipped: one already in flight");
			return;
		}
		notifyPanel();
		Runnable done = () -> {
			scheduler.clearInFlight();
			notifyPanel();
		};
		List<RoadmapSummary> known = listCache.reusable(player, System.currentTimeMillis());
		if (known != null) {
			fetchEach(known, player, done);
			return;
		}
		apiClient.getRoadmaps(player, new MystixApiClient.RoadmapCallback<RoadmapList>() {
			@Override
			public void onSuccess(RoadmapList result) {
				onRoadmapListFetched(result, player, done);
			}

			@Override
			public void onError(String message) {
				scheduler.clearInFlight();
				log.debug("Quiet roadmap refresh failed: {}", message);
				notifyPanel();
			}
		});
	}

	private MystixApiClient.RoadmapCallback<Roadmap> cacheThen(
			int collectionId, MystixApiClient.RoadmapCallback<Roadmap> callback) {
		return new MystixApiClient.RoadmapCallback<Roadmap>() {
			@Override
			public void onSuccess(Roadmap result) {
				// Feeds the tracker; caches for the overlay only if selected.
				onRoadmapFetched(result);
				callback.onSuccess(result);
			}

			@Override
			public void onError(String message) {
				callback.onError(message);
			}
		};
	}

	/** Convenience for callers that only need the cached roadmap, no fetch. */
	public void withCurrentRoadmap(Consumer<Roadmap> consumer) {
		consumer.accept(currentRoadmap);
	}
}

package com.mystix;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/**
 * Side-panel progress bar: the same 6px rounded pill the Mystix app draws under
 * each goal. Stretches to the card width; height is fixed.
 */
final class GoalProgressBar extends JComponent {
	static final int HEIGHT = 6;
	private static final Color TRACK = new Color(0x17, 0x17, 0x22);
	private static final Color FILL = new Color(0x25, 0x63, 0xEB);

	private final double fraction;

	GoalProgressBar(double fraction) {
		this.fraction = Math.max(0, Math.min(1, fraction));
		setOpaque(false);
		setPreferredSize(new Dimension(0, HEIGHT));
		setMinimumSize(new Dimension(0, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2 = (Graphics2D) g.create();
		try {
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			g2.setColor(TRACK);
			g2.fillRoundRect(0, 0, w, HEIGHT, HEIGHT, HEIGHT);
			int fill = (int) Math.round(w * fraction);
			if (fill > 0) {
				g2.setColor(FILL);
				g2.fillRoundRect(0, 0, Math.min(w, Math.max(fill, HEIGHT)), HEIGHT, HEIGHT, HEIGHT);
			}
		} finally {
			g2.dispose();
		}
	}
}

package com.mystix;

import com.mystix.api.MystixApiClient;
import com.mystix.model.TimerSyncItem;
import com.mystix.model.TimersSyncPayload;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;
import com.mystix.runelite.farming.CropState;
import com.mystix.runelite.farming.FarmingPatch;
import com.mystix.runelite.farming.FarmingTracker;
import com.mystix.runelite.farming.FarmingWorld;
import com.mystix.runelite.farming.PatchPrediction;
import com.mystix.runelite.farming.Produce;
import com.mystix.runelite.hunter.BirdHouse;
import com.mystix.runelite.hunter.BirdHouseSpace;

@Slf4j
public class TimerMonitor {
	private static final int INITIAL_DELAY_SECONDS = 10;
	private static final int SYNC_INTERVAL_SECONDS = 45;
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	private static final int TEARS_OF_GUTHIX_RESET_DAYS = 7;
	private static final int LEAGUES_GROWTH_RATE_DIVISOR = 5;
	// Average time to harvest 10 birds, matches RuneLite's BirdHouseTracker.BIRD_HOUSE_DURATION.
	private static final long BIRD_HOUSE_DURATION_SECONDS = Duration.ofMinutes(50).getSeconds();

	private final Client client;
	private final MystixConfig config;
	private final MystixApiClient apiClient;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executorService;
	private final FarmingTracker farmingTracker;
	private final FarmingWorld farmingWorld;

	private ScheduledFuture<?> scheduledFuture;
	private String lastSentSnapshot;
	private volatile Instant tearsOfGuthixNextReset = null;
	private GameState previousGameState = GameState.UNKNOWN;

	public TimerMonitor(
			Client client,
			MystixConfig config,
			MystixApiClient apiClient,
			ConfigManager configManager,
			ScheduledExecutorService executorService,
			FarmingTracker farmingTracker,
			FarmingWorld farmingWorld) {
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
		this.executorService = executorService;
		this.farmingTracker = farmingTracker;
		this.farmingWorld = farmingWorld;
	}

	public void start() {
		if (scheduledFuture != null) {
			return;
		}
		scheduledFuture = executorService.scheduleAtFixedRate(
				this::sync,
				INITIAL_DELAY_SECONDS,
				SYNC_INTERVAL_SECONDS,
				TimeUnit.SECONDS);
	}

	/** Receives every recomputed timer set (farming, bird houses, ...); set by the plugin. */
	private volatile Consumer<List<TimerSyncItem>> timersListener;

	public void setTimersListener(Consumer<List<TimerSyncItem>> listener) {
		this.timersListener = listener;
	}

	/** Invoked after each upload so roadmap progress can be re-read; set by the plugin. */
	private volatile Runnable syncedListener;

	public void setSyncedListener(Runnable listener) {
		this.syncedListener = listener;
	}

	private void notifySynced() {
		Runnable listener = syncedListener;
		if (listener != null) {
			listener.run();
		}
	}

	public void stop() {
		if (scheduledFuture != null) {
			scheduledFuture.cancel(false);
			scheduledFuture = null;
		}
		lastSentSnapshot = null;
		tearsOfGuthixNextReset = null;
		previousGameState = GameState.UNKNOWN;
	}

	/**
	 * Re-runs the timer sync immediately on the background executor, forcing a
	 * resend by clearing the change-detection snapshot. Used by the roadmap
	 * panel's "Sync &amp; refresh" button.
	 */
	public void forceSync() {
		executorService.execute(() -> {
			lastSentSnapshot = null;
			sync();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN) {
			log.debug("Player logged in, scheduling timer sync in {}s", LOGIN_SYNC_DELAY_SECONDS);
			lastSentSnapshot = null;
			executorService.schedule(this::sync, LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		}
		previousGameState = newState;
	}

	/**
	 * Called when the player enters the Tears of Guthix cave.
	 * ToG is playable again 7 days after completion, rounded down to 00:00 UTC.
	 */
	public void onTearsOfGuthixCompleted() {
		ZonedDateTime nowUtc = Instant.now().atZone(ZoneOffset.UTC);
		ZonedDateTime completionDayStart = nowUtc.toLocalDate().atStartOfDay(ZoneOffset.UTC);
		tearsOfGuthixNextReset = completionDayStart.plusDays(TEARS_OF_GUTHIX_RESET_DAYS).toInstant();
		lastSentSnapshot = null;
		log.debug("Tears of Guthix completed; next reset at {}", tearsOfGuthixNextReset);
		// Push it now rather than waiting for the periodic sync.
		executorService.execute(this::sync);
	}

	/**
	 * Collects all timer data (farming, bird houses, Tears of Guthix) and sends
	 * to the Mystix API if anything changed since the last sync.
	 */
	private void sync() {
		if (!SyncGuard.hasAppKey(config)) {
			log.debug("Mystix sync skipped: no App Key configured");
			return;
		}
		if (!config.syncTimeTracking()) {
			log.debug("Mystix sync skipped: sync disabled");
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN) {
			log.debug("Mystix sync skipped: not logged in");
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client)) {
			log.debug("Mystix sync skipped: special game mode detected (Leagues, DMM, etc.)");
			return;
		}

		String playerUsername = SyncGuard.getPlayerUsername(client);
		if (playerUsername == null) {
			log.warn("Mystix sync skipped: could not get player username");
			return;
		}

		farmingTracker.loadCompletionTimes();
		farmingTracker.updateCompletionTime();

		boolean syncEnabled = config.syncTimeTracking();
		List<TimerSyncItem> timers = new ArrayList<>();

		collectFarmingTimers(timers, playerUsername, syncEnabled);
		collectBirdHouseTimers(timers, playerUsername, syncEnabled);
		collectTearsOfGuthixTimer(timers, playerUsername, syncEnabled);

		Consumer<List<TimerSyncItem>> listener = timersListener;
		if (listener != null) {
			listener.accept(timers);
		}

		String snapshot = TimersSyncPayload.toJson(timers);
		if (!snapshot.equals(lastSentSnapshot)) {
			lastSentSnapshot = snapshot;
			log.debug("Mystix syncing {} timer(s) for {}", timers.size(), playerUsername);
			apiClient.sendTimersSync(timers);
			notifySynced();
		}
	}

	/**
	 * Iterates all farming patches across all tabs, builds a TimerSyncItem for each
	 * patch with a valid, in-progress prediction, and appends them to the timers list.
	 */
	private void collectFarmingTimers(List<TimerSyncItem> timers, String playerUsername, boolean syncEnabled) {
		for (var entry : farmingWorld.getTabs().entrySet()) {
			for (FarmingPatch patch : entry.getValue()) {
				PatchPrediction prediction = farmingTracker.predictPatch(patch);
				if (!isValidFarmingPrediction(prediction)) {
					continue;
				}

				long doneEstimate = prediction.getDoneEstimate();
				if (doneEstimate <= 0) {
					continue;
				}

				boolean notificationsEnabled = syncEnabled && isFarmingNotifyEnabled(patch);
				String regionName = resolveRegionName(patch, entry.getKey());
				String tabName = resolveTabName(entry.getKey());

				Instant completedAt = Instant.ofEpochSecond(doneEstimate);
				Instant startedAt = computeFarmingStartedAt(prediction, doneEstimate);
				int produceItemId = prediction.getProduce().getItemID();

				timers.add(new TimerSyncItem(
						tabName,
						regionName,
						prediction.getProduce().getName(),
						completedAt,
						notificationsEnabled,
						playerUsername,
						startedAt,
						prediction.getCropState().name().toLowerCase(),
						produceItemId >= 0 ? produceItemId : null,
						patch.getVarbit()));
			}
		}
	}

	private boolean isValidFarmingPrediction(PatchPrediction prediction) {
		if (prediction == null || prediction.getProduce().getItemID() < 0) {
			return false;
		}
		if (prediction.getProduce() == Produce.WEEDS || prediction.getProduce() == Produce.SCARECROW) {
			return false;
		}
		return prediction.getCropState() != CropState.EMPTY && prediction.getCropState() != CropState.FILLING;
	}

	private String resolveRegionName(FarmingPatch patch, com.mystix.runelite.Tab tab) {
		String regionName = patch.getRegion().getName();
		if (regionName == null || regionName.isBlank()) {
			return tab.name().toLowerCase();
		}
		return regionName;
	}

	private String resolveTabName(com.mystix.runelite.Tab tab) {
		String tabName = tab.getName();
		if (tabName == null || tabName.isBlank()) {
			return tab.name().toLowerCase();
		}
		return tabName;
	}

	/**
	 * Reads bird house state directly from the {@code timetracking} RS profile config
	 * (written by the core Time Tracking plugin) and emits a TimerSyncItem for each
	 * seeded house that has not yet completed.
	 */
	private void collectBirdHouseTimers(List<TimerSyncItem> timers, String playerUsername, boolean syncEnabled) {
		boolean birdHouseNotify = syncEnabled && isBirdHouseNotifyEnabled();
		long now = Instant.now().getEpochSecond();

		for (BirdHouseSpace space : BirdHouseSpace.values()) {
			String key = TimeTrackingConfig.BIRD_HOUSE + "." + space.getVarp();
			String stored = configManager.getRSProfileConfiguration(TimeTrackingConfig.CONFIG_GROUP, key);
			if (stored == null) {
				continue;
			}

			String[] parts = stored.split(":");
			if (parts.length != 2) {
				continue;
			}

			int varp;
			long timestamp;
			try {
				varp = Integer.parseInt(parts[0]);
				timestamp = Long.parseLong(parts[1]);
			} catch (NumberFormatException e) {
				continue;
			}

			// Seeded when varp is a positive multiple of 3; see RuneLite BirdHouseState.
			if (varp <= 0 || varp % 3 != 0) {
				continue;
			}

			long spaceCompletionTime = timestamp + BIRD_HOUSE_DURATION_SECONDS;
			if (spaceCompletionTime <= now) {
				continue;
			}

			BirdHouse birdHouse = BirdHouse.fromVarpValue(varp);
			Integer birdHouseEntityId = birdHouse != null ? birdHouse.getItemID() : null;
			String entityName = birdHouse != null ? birdHouse.getName() : "Bird House";

			timers.add(new TimerSyncItem(
					"bird house",
					space.getName(),
					entityName,
					Instant.ofEpochSecond(spaceCompletionTime),
					birdHouseNotify,
					playerUsername,
					Instant.ofEpochSecond(timestamp),
					null,
					birdHouseEntityId,
					space.getVarp()));
		}
	}

	private void collectTearsOfGuthixTimer(List<TimerSyncItem> timers, String playerUsername, boolean syncEnabled) {
		Instant togReset = tearsOfGuthixNextReset;
		if (togReset != null && togReset.isAfter(Instant.now())) {
			timers.add(new TimerSyncItem(
					"tears of guthix",
					"tears of guthix",
					"tears of guthix",
					togReset,
					syncEnabled,
					playerUsername,
					null,
					null,
					null,
					0));
		}
	}

	private boolean isFarmingNotifyEnabled(FarmingPatch patch) {
		String notifyKey = TimeTrackingConfig.NOTIFY + "." + patch.getRegion().getRegionID() + "." + patch.getVarbit();
		String profileKey = configManager.getRSProfileKey();
		return Boolean.TRUE
				.equals(configManager.getConfiguration(TimeTrackingConfig.CONFIG_GROUP, profileKey, notifyKey, Boolean.class));
	}

	private boolean isBirdHouseNotifyEnabled() {
		return Boolean.TRUE.equals(configManager.getRSProfileConfiguration(TimeTrackingConfig.CONFIG_GROUP,
				TimeTrackingConfig.BIRDHOUSE_NOTIFY, boolean.class));
	}

	/**
	 * Computes started_at for a farming patch by subtracting the total growth
	 * duration from the estimated completion time. Adjusts tick rate for Leagues worlds.
	 */
	private Instant computeFarmingStartedAt(PatchPrediction prediction, long doneEstimate) {
		int tickRate = prediction.getProduce().getTickrate();
		if (GameModeUtil.isLeaguesWorld(client)) {
			tickRate = tickRate / LEAGUES_GROWTH_RATE_DIVISOR;
		}
		int stages = prediction.getStages();
		if (tickRate <= 0 || stages <= 1) {
			return null;
		}
		long growthSeconds = (long) (stages - 1) * tickRate * 60;
		return Instant.ofEpochSecond(doneEstimate - growthSeconds);
	}
}

